INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Abençoar Alimentos', 'Divina', 1, 'Transmutação', 'padrão', 'curto', 'cena', '', '', '', 'Você purifica e abençoa uma porção de comida ou dose de bebida. Isso torna um alimento sujo, estragado ou envenenado próprio para consumo. Além disso, se for consumido até o final da duração, o alimento oferece 5 PV temporários ou 1 PM temporário (além de quaisquer bônus que já oferecesse). Bônus de alimentação duram um dia e cada personagem só pode receber um bônus de alimentação por dia.', '[{"cost":"Truque","effect":"o alimento é purificado (não causa nenhum efeito nocivo se estava estragado ou envenenado), mas não oferece bônus ao ser consumido.","isTrick":true},{"cost":"+1 PM","effect":"aumenta o número de alvos em +1.","isTrick":false},{"cost":"+1 PM","effect":"muda a duração para permanente, o alvo para 1 frasco com água e adiciona componente material (pó de prata no valor de T$ 5). Em vez do normal, cria um frasco de água benta.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Acalmar Animal', 'Divina', 1, 'Encantamento', 'padrão', 'curto', 'cena', '', 'Vontade anula', '', 'O animal fica prestativo em relação a você. Ele não fica sob seu controle, mas percebe suas palavras e ações da maneira mais favorável possível. Você recebe +10 nos testes de Adestramento e Diplomacia que fizer contra o animal.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Açoite Flamejante', 'Arcana', 1, 'Convocação', 'padrão', 'pessoal', 'sustentada', '', 'Reflexos parcial', '', 'Um açoite de fogo surge em uma de suas mãos com a qual possa empunhar uma arma (essa mão fica ocupada pela duração da magia). Você pode usar uma ação padrão para causar 2d6 pontos de dano de fogo com o açoite em uma criatura em alcance curto e deixá-la em chamas e enredada enquanto estiver em chamas dessa forma. Passar na resistência reduz o dano à metade e evita as chamas.', '[{"cost":"+2 PM","effect":"muda a execução para movimento.","isTrick":false},{"cost":"+2 PM","effect":"muda o dano para 4d6. Requer 2º círculo.","isTrick":false},{"cost":"+5 PM","effect":"muda o dano para 6d6. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Adaga Mental', 'Arcana', 1, 'Encantamento', 'padrão', 'curto', 'instantânea', '', 'Vontade parcial', '', 'Você manifesta e dispara uma adaga imaterial contra a mente do alvo, que sofre 2d6 pontos de dano psíquico e fica Atordoado por uma rodada. Se passar no teste de resistência, sofre apenas metade do dano e evita a condição. Uma criatura só pode ficar atordoada por esta magia uma vez por cena.', '[{"cost":"+1 PM","effect":"você lança a magia sem gesticular ou\npronunciar palavras (o que permite lançar essa magia de armadura) e a adaga se torna invisível. Se o alvo falhar no teste de resistência, não percebe que você lançou uma magia\ncontra ele.","isTrick":false},{"cost":"+2 PM","effect":"muda a duração para 1 dia. Além do normal, você “finca” a adaga na mente do alvo. Enquanto a magia durar, você sabe a direção e localização do alvo, desde que ele esteja no mesmo mundo.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o dano em +1d6.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Alarme', 'Arcana', 1, 'Abjuração', 'padrão', 'curto', '1 dia', 'Esfera de 9m de raio', '', '', 'Você cria uma barreira protetora invisível que detecta qualquer criatura que tocar ou entrar na área protegida. Ao lançar a magia, você pode escolher quais criaturas podem entrar na área sem ativar seus efeitos. Alarme pode emitir um aviso telepático ou sonoro, decidido quando a magia é lançada. Um aviso telepático alerta apenas você, inclusive acordando-o se estiver dormindo, mas apenas se estiver a até 1km da área protegida. Um aviso sonoro alerta todas as criaturas em alcance longo.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Amedrontar', 'Arcana', 1, 'Necromancia', 'padrão', 'curto', 'cena', '', 'Vontade parcial', '', 'O alvo é envolvido por energias sombrias e assustadoras. Se falhar na resistência, fica Apavorado por 1 rodada, depois Abalado. Se passar, fica abalado por 1d4 rodadas.', '[{"cost":"+2 PM","effect":"alvos que falhem na resistência ficam apavorados por 1d4+1 rodadas, em vez de apenas 1.","isTrick":false},{"cost":"+2 PM","effect":"muda o alvo para 1 criatura.","isTrick":false},{"cost":"+5 PM","effect":"afeta todos os alvos válidos a sua escolha dentro do alcance.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Arma de Jade', 'Divina', 1, 'Transmutação', 'padrão', 'toque', 'cena', '', '', '', 'Esta magia ofertada por Lin-Wu transfere temporariamente para uma arma as qualdades místicas do jade, um raro material de Tamu-ra. A arma é considerada mágica, pode ser sacada e guardada como ação livre e fornece +1 nos testes de ataque e rolagens de dano (isso conta como um bônus de encanto). Contra espíritos, os bônus fornecidos pela magia são dobrados.', '[{"cost":"+1 PM","effect":"a arma causa +1d4 de dano de eletricidade.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o bônus de ataque e dano em +1 (bônus máximo limitado pelo círculo máximo de magia que você pode lançar).","isTrick":false},{"cost":"+2 PM","effect":"(Apenas Devotos de LinWu): muda o bônus de dano do aprimoramento acima para +2d4.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Arma Espiritual', 'Divina', 1, 'Convocação', 'padrão', 'pessoal', 'cena', '', '', '', 'Você invoca a arma preferida de sua divindade (se tiver uma), que surge flutuando a seu lado. Uma vez por rodada, quando você sofre um ataque corpo a corpo, pode usar uma reação para que a arma cause automaticamente 2d6 pontos de dano do tipo da arma — por exemplo, uma espada longa causa dano de corte — no oponente que fez o ataque. Esta magia se dissipa se você morrer.', '[{"cost":"+1 PM","effect":"além do normal, a arma o protege. Você recebe +1 na Defesa.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o bônus na Defesa em +1.","isTrick":false},{"cost":"+2 PM","effect":"muda a duração para sustentada. Além do normal, uma vez por rodada, você pode gastar uma ação livre para fazer a arma acertar automaticamente um alvo adjacente. Se a arma atacar, não poderá contra-atacar até seu próximo turno. Requer 2o círculo.","isTrick":false},{"cost":"+2 PM","effect":"muda o tipo do dano para essência. Requer 2o círculo.","isTrick":false},{"cost":"+5 PM","effect":"invoca duas armas, permitindo que você contra-ataque (ou ataque, se usar o aprimoramento acima) duas vezes por rodada. Requer 3o círculo.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o dano causado pela arma em +1d6, limitado pelo círculo máximo de magia que você pode lançar.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Arma Mágica', 'Universal', 1, 'Transmutação', 'padrão', 'toque', 'cena', '', '', '', 'A arma fornece um bônus de +1 nos testes de ataque e rolagens de dano e é considerada mágica (não cumulativo com bônus de encantos). Caso você esteja empunhando a arma, pode usar seu atributo-chave de magias em vez do atributo original nos testes de ataque (não cumulativo com efeitos que somam este atributo).', '[{"cost":"+2 PM","effect":"aumenta o bônus em +1 (bônus máximo limitado pelo círculo máximo de magia que você pode lançar).","isTrick":false},{"cost":"+2 PM","effect":"a arma passa a causar +1d6 de dano de ácido, eletricidade, fogo ou frio, escolhido no momento em que a magia é lançada. Este aprimoramento só pode ser usado uma vez.","isTrick":false},{"cost":"+3 PM","effect":"muda o bônus de dano do aprimoramento elemental para +2d6.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Armadura Arcana', 'Arcana', 1, 'Abjuração', 'padrão', 'pessoal', 'cena', '', '', '', 'Esta magia cria uma película protetora invisível, mas tangível, fornecendo +5 na Defesa. Esse bônus é cumulativo com outras magias, mas não com bônus fornecido por armaduras.', '[{"cost":"+1 PM","effect":"muda a execução para reação.\nEm vez do normal, você cria um escudo\nmágico que fornece +5 na Defesa contra o próximo ataque que sofrer (cumulativo com o bônus fornecido pelo efeito básico desta magia e armaduras).","isTrick":false},{"cost":"+2 PM","effect":"aumenta o bônus na Defesa em +1.","isTrick":false},{"cost":"+2 PM","effect":"muda a duração para 1 dia.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Armadura Elemental', 'Arcana', 1, 'Evocação', 'padrão', 'pessoal', 'cena', '', '', '', 'Escolha um tipo de energia entre ácido, eletricidade, fogo ou frio. Uma aura faiscante dessa energia emana de seu corpo — sempre que uma criatura adjacente acertar um ataque corpo a corpo em você, ela sofre 2d6 pontos de dano do tipo escolhido.', '[{"cost":"+2 PM","effect":"muda o alcance para toque e o alvo para 1 criatura. Requer 2º círculo.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o dano em +1d6 (total de dados limitado pelo círculo máximo de magia que você pode lançar). Requer 3º círculo.","isTrick":false},{"cost":"+3 PM","effect":"muda a energia para essência. Requer 2º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Armamento da Natureza', 'Divina', 1, 'Transmutação', 'padrão', 'toque', 'cena', '', '', '', 'Você fortalece uma arma mundana primitiva (sem custo em T$, como bordão, clava, funda ou tacape), uma arma natural ou um ataque desarmado. O dano da arma aumenta em um passo e ela é considerada mágica. Ao lançar a magia, você pode mudar o tipo de dano da arma (escolhendo entre corte, impacto ou perfuração).', '[{"cost":"+1 PM","effect":"fornece +1 nos testes de ataque com a arma.","isTrick":false},{"cost":"+2 PM","effect":"muda a execução para ação de movimento.","isTrick":false},{"cost":"+3 PM","effect":"aumenta o bônus nos testes de ataque em +1.","isTrick":false},{"cost":"+5 PM","effect":"aumenta o dano da arma em mais um passo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Arsenal de Allihanna', 'Divina', 1, 'Transmutação', 'padrão', 'pessoal', 'cena', '', '', '', 'Outrora chamada Armamento de Allihanna, esta magia recentemente recebeu um novo nome — com implicações curiosas. Utilizada pela primeira vez por Lisandra de Galrasia, diz-se que a verdadeira origem da magia estaria relacionada a seu pai, Arsenal, então mortal.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Assobio Perigoso', 'Arcana', 1, 'Convocação', 'padrão', 'pessoal', 'especial', '', '', '', 'Esta estranha magia conjura um grupo de criaturas agressivas que imediatamente atacam quem está por perto… Inclusive o conjurador e seus aliados!
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Aviso', 'Universal', 1, 'Adivinhação', 'movimento', 'longo', 'instantânea', '', '', '', 'Envia um aviso telepático para uma criatura, mesmo que não possa vê-la nem tenha linha de efeito.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Bênção', 'Divina', 1, 'Encantamento', 'padrão', 'curto', 'cena', '', '', '', 'Abençoa seus aliados, que recebem +1 em testes de ataque e rolagens de dano. Bênção anula Perdição.', '[{"cost":"+1 PM","effect":"muda o alvo para 1 cadáver e a duração para 1 semana. O cadáver não se decompõe nem pode ser transformado em morto-vivo.","isTrick":false},{"cost":"+2 PM","effect":"aumenta os bônus em +1, limitado pelo círculo máximo de magia que você pode lançar.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Bofetada de Nimb', 'Divina', 1, 'Evocação', 'padrão', 'curto', 'instantânea', '', 'Vontade parcial', '', 'Uma mão mágica surge diante do alvo e o esbofeteia na face, ou em outra parte vulnerável, desaparecendo em seguida. O golpe não causa dano, mas é bastante humilhante. Se o alvo falhar na resistência, fica desprevenido por 1 rodada e vulnerável; se passar, fica apenas vulnerável por 1 rodada.', '[{"cost":"+1 PM","effect":"alvos que falhem na resistência ficam vulneráveis pela cena.","isTrick":false},{"cost":"+2 PM","effect":"muda o alvo para 1 criatura.","isTrick":false},{"cost":"+2 PM","effect":"em vez do normal, a mão dá leves tapinhas que acalmam os alvos e anulam uma condição entre abalado, alquebrado, apavorado e frustrado. Requer 2° círculo.","isTrick":false},{"cost":"+3 PM","effect":"alvos que falhem na resistência ficam desprevenidos por 1d4+1 rodadas, em vez de apenas 1.","isTrick":false},{"cost":"+5 PM","effect":"(Apenas Devotos de Nimb): afeta todos os alvos válidos a sua escolha dentro do alcance.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Caminhos da Natureza', 'Divina', 1, 'Convocação', 'padrão', 'curto', '1 dia', '', '', '', 'Você invoca espíritos da natureza, pedindo que eles abram seu caminho. As criaturas afetadas recebem deslocamento +3m e ignoram penalidades por terreno difícil em terrenos naturais.', '[{"cost":"Truque","effect":"muda o alcance para pessoal e o alvo para você. Em vez do normal, você sabe onde fica o norte e recebe +5 em testes de Sobrevivência para se orientar.","isTrick":true},{"cost":"+1 PM","effect":"além do normal, a CD para rastrear os alvos em terreno natural aumenta em +10.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o bônus de deslocamento em +3m.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Comando', 'Divina', 1, 'Encantamento', 'padrão', 'curto', '1 rodada', '', 'Vontade anula', '', 'Você dá uma ordem irresistível, que o alvo deve ser capaz de ouvir (mas não precisa entender). Se falhar na resistência, ele deve obedecer ao comando em seu próprio turno da melhor maneira possível. Escolha um dos efeitos.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Compreensão', 'Universal', 1, 'Adivinhação', 'padrão', 'toque', 'cena', '', 'Vontade anula (veja descrição)', '', 'Essa magia lhe confere compreensão sobrenatural. Você pode tocar um texto e entender as palavras mesmo que não conheça o idioma. Se tocar numa criatura inteligente, pode se comunicar com ela mesmo que não tenham um idioma em comum. Se tocar uma criatura não inteligente, como um animal, pode perceber seus sentimentos.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Concentração de Combate', 'Arcana', 1, 'Adivinhação', 'livre', 'pessoal', '1 rodada', '', '', '', 'Você amplia sua percepção, antecipando movimentos dos inimigos e achando brechas em sua defesa. Quando faz um teste de ataque, você rola dois dados e usa o melhor resultado', '[{"cost":"+2 PM","effect":"muda a execução para padrão e a duração para cena. Requer 2º círculo.","isTrick":false},{"cost":"+5 PM","effect":"além do normal, ao atacar você, um inimigo deve rolar dois dados e usar o pior resultado. Requer 3º círculo.","isTrick":false},{"cost":"+9 PM","effect":"muda a execução para padrão, o alcance para curto, o alvo para criaturas escolhidas e a duração para cena. Requer 4º círculo.","isTrick":false},{"cost":"+14 PM","effect":"muda a execução para padrão e a duração para 1 dia. Além do normal, você recebe um sexto sentido que o avisa de qualquer perigo ou ameaça. Você fica imune às condições surpreendido e desprevenido e recebe +10 em Defesa e Reflexos. Requer 5º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Conjurar Monstro', 'Arcana', 1, 'Convocação', 'completa', 'curto', 'sustentada', '', '', '', '
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Consagrar', 'Divina', 1, 'Evocação', 'padrão', 'longo', '1 dia', 'esfera com 9m de raio', '', '', 'Você enche a área com energia positiva. Pontos de vida curados por efeitos de luz são maximizados dentro da área. Isso também afeta dano causado em mortos-vivos por esses efeitos.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Controlar Plantas', 'Divina', 1, 'Transmutação', 'padrão', 'curto', 'cena', 'quadrado com 9m de lado', 'Reflexos anula', '', 'Esta magia só pode ser lançada em uma área com vegetação. As plantas se enroscam nas criaturas da área. Aquelas que falharem na resistência ficam Enredado. Uma vítima pode se libertar com uma ação padrão e um teste de Acrobacia ou Atletismo. Além disso, a área é considerada terreno difícil. No início de seus turnos, a vegetação tenta enredar novamente qualquer criatura na área, exigindo um novo teste de Reflexos.', '[{"cost":"Truque","effect":"muda a área para alvo de 1 planta e a resistência para nenhuma. Em vez do normal, você pode fazer a planta se mover como se fosse animada. Ela não pode causar dano ou atrapalhar a concentração de um conjurador.","isTrick":true},{"cost":"+1 PM","effect":"muda a duração para instantânea. Em vez do normal, as plantas na área diminuem, como se tivessem sido podadas. Terreno difícil muda para terreno normal e não oferece camuflagem. Esse efeito dissipa o uso normal de Controlar Plantas.","isTrick":false},{"cost":"+1 PM","effect":"além do normal, criaturas que falhem na resistência também ficam imóveis.","isTrick":false},{"cost":"+2 PM","effect":"muda o alcance para pessoal, a área para alvo (você) e a resistência para nenhuma. Em vez do normal, você consegue se comunicar com plantas, que começam com atitude prestativa em relação a você. Além disso, você pode fazer testes de Diplomacia com plantas. Em geral, plantas têm uma percepção limitada de seus arredores e normalmente fornecem respostas simplórias.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Criar Elementos', 'Divina', 1, 'Convocação', 'padrão', 'curto', 'instantânea', '', '', '', 'Você cria uma pequena porção de um elemento, a sua escolha. Os elementos criados são reais, não mágicos. Elementos físicos devem surgir em uma superfície. Em vez de um cubo, pode-se criar objetos simples (sem partes móveis) feitos de gelo, terra ou pedra.Água: enche um recipiente de tamanho Minúsculo (como um odre) com água potável ou cria um cubo de gelo de tamanho Minúsculo.Ar: cria um vento fraco em um quadrado de 1,5m. Isso purifica a área de qualquer gás ou fumaça, ou remove névoa por uma rodada.Fogo: cria uma chama que ilumina como uma tocha. Você pode segurá-la na palma de sua mão sem se queimar, ou fazê-la surgir em um quadrado de 1,5m. Se uma criatura ou objeto estiver no quadrado, sofre 1d6 pontos de dano de fogo; se falhar num teste de Reflexos, pega fogo.Terra: cria um cubo de tamanho Minúsculo feito de terra, argila ou pedra.', '[{"cost":"+1 PM","effect":"aumenta a quantidade do elemento em um passo (uma categoria de tamanho para água ou terra, +1 quadrado de 1,5m para ar e fogo).","isTrick":false},{"cost":"+1 PM","effect":"muda o efeito para alvo 1 criatura ou objeto e a resistência para Reflexos reduz à metade. Se escolher água ou terra, você arremessa o cubo ou objeto criado no alvo, causando 2d4 pontos de dano de impacto. Para cada categoria de tamanho acima de Minúsculo, o dano aumenta em um passo. O cubo se desfaz em seguida.","isTrick":false},{"cost":"+1 PM","effect":"se escolheu fogo, aumenta o dano inicial de cada chama em +1d6.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Criar Ilusão', 'Arcana', 1, 'Ilusão', 'padrão', 'médio', 'cena', '', 'Vontade desacredita', '', 'Esta magia cria uma ilusão visual (uma criatura, uma parede...) ou sonora (um grito de socorro, um uivo assustador...). A magia cria apenas imagens ou sons simples, com volume equivalente ao tom de voz normal para cada cubo de 1,5m no efeito. Não é possível criar cheiros, texturas ou temperaturas, nem sons complexos, como uma música ou diálogo. Criaturas e objetos atravessam uma ilusão sem sofrer dano, mas a magia pode, por exemplo, esconder uma armadilha ou inimigo. A magia é dissipada se você sair do alcance.', '[{"cost":"+1 PM","effect":"muda a duração para sustentada. A cada rodada você pode gastar uma ação livre para mover a imagem ou alterar levemente o som, como aumentar o volume ou fazer com que pareça se afastar ou se aproximar, ainda dentro dos limites do efeito. Você pode, por exemplo, criar a ilusão de um fantasma que anda pela sala, controlando seus movimentos. Quando você para de sustentar a magia, a imagem ou som persistem por mais uma rodada antes de a magia se dissipar.","isTrick":false},{"cost":"+1 PM","effect":"aumenta o efeito da ilusão em +1 cubo de 1,5m.","isTrick":false},{"cost":"+1 PM","effect":"também pode criar ilusões de imagem e sons combinados.","isTrick":false},{"cost":"+1 PM","effect":"também pode criar sons complexos com volume máximo equivalente ao que cinco pessoas podem produzir para cada cubo de 1,5m no efeito. Com uma ação livre, você pode alterar o volume do som ou fazê-lo se aproximar ou se afastar dentro do alcance.","isTrick":false},{"cost":"+2 PM","effect":"também pode criar odores e sensações térmicas, que são percebidos a uma distância igual ao dobro do tamanho máximo do efeito. Por exemplo, uma miragem de uma fogueira com 4 cubos de 1,5m poderia emanar calor e cheiro de queimado a até 12m.","isTrick":false},{"cost":"+2 PM","effect":"muda o alcance para longo e o efeito para esfera de 30m de raio. Em vez do normal, você cria um som muito alto, equivalente a uma multidão. Criaturas na área lançam magias como se estivessem em uma condição ruim e a CD de testes de Percepção para ouvir aumenta em +10. Requer 2º círculo.","isTrick":false},{"cost":"+2 PM","effect":"também criar sensações táteis, como texturas; criaturas que não saibam que é uma ilusão não conseguem atravessá-la sem passar em um teste de Vontade (objetos ainda a atravessam). A ilusão ainda é incapaz de causar ou sofrer dano. Requer 2º círculo.","isTrick":false},{"cost":"+5 PM","effect":"muda a duração para sustentada. Além do normal, você pode gastar uma ação livre para modificar livremente a ilusão (mas não pode acrescentar novos aprimoramentos após lançá-la). Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Curar Ferimentos', 'Divina', 1, 'Evocação', 'padrão', 'toque', 'instantânea', '', '', '', 'Você canaliza energia positiva que recupera 2d8+2 pontos de vida na criatura tocada. Curar Ferimentos anula Infligir Ferimentos.', '[{"cost":"Truque","effect":"muda o alvo para 1 morto-vivo. Em vez do normal, causa 1d8 pontos de dano de luz (Vontade reduz à metade).","isTrick":true},{"cost":"+1 PM","effect":"aumenta a cura em +1d8+1.","isTrick":false},{"cost":"+2 PM","effect":"também remove uma condição de cansaço do alvo.","isTrick":false},{"cost":"+2 PM","effect":"muda o alcance para curto.","isTrick":false},{"cost":"+5 PM","effect":"muda o alcance para curto e o alvo para criaturas escolhidas.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Dardo Gélido', 'Arcana', 1, 'Evocação', 'padrão', 'curto', 'instantânea', '', 'Fortitude parcial', '', 'Você dispara um dardo de gelo contra o alvo, que sofre 2d6 pontos de dano de frio e fica lento por 1 rodada. Passar no teste de resistência reduz o dano à metade e evita a condição.', '[{"cost":"+1 PM","effect":"aumenta o dano em +1d6.","isTrick":false},{"cost":"+1 PM","effect":"aumenta o número de alvos em +1 (total de alvos limitado pelo círculo máximo de magia que você pode lançar).","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Descobrir Fraqueza', 'Arcana', 1, 'Adivinhação', 'movimento', 'curto', 'instantânea', '', 'Vontade evita', '', 'Você analisa uma criatura em busca de pontos fracos e outras características. Para isso, como parte do efeito da magia, você faz um teste de Misticismo para identificar criatura contra o alvo (independente do tipo dele) com um bônus de +10.', '[{"cost":"+1 PM","effect":"aumenta o bônus no teste em +5.","isTrick":false},{"cost":"+1 PM","effect":"além do normal, sua próxima rolagem de dano contra a criatura nessa cena ignora 10 pontos da redução de dano dela. Requer 2° círculo.","isTrick":false},{"cost":"+2 PM","effect":"além do normal, você recebe +2 em testes contra a criatura até o fim da cena. Requer 2° círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Despedaçar', 'Divina', 1, 'Evocação', 'padrão', 'curto', 'instantânea', '', 'Fortitude parcial', '', 'Esta magia emite um som alto e agudo. O alvo sofre 1d8+2 pontos de dano de impacto (ou o dobro disso e ignora RD se for um construto ou objeto mundano) e fica Atordoado por uma rodada (apenas uma vez por cena). Um teste de Fortitude reduz o dano à metade e evita o atordoamento. Despedaçar anula Transmutar Objetos.', '[{"cost":"+2 PM","effect":"aumenta o dano em +1d8+2.","isTrick":false},{"cost":"+2 PM","effect":"muda o alvo para objeto mundano Médio. Requer 2º círculo.","isTrick":false},{"cost":"+5 PM","effect":"muda o alvo para objeto mundano Grande. Requer 3º círculo.","isTrick":false},{"cost":"+9 PM","effect":"muda o alvo para objeto mundano Enorme. Requer 4º círculo.","isTrick":false},{"cost":"+14 PM","effect":"muda o alvo para objeto mundano Colossal. Requer 5º círculo.","isTrick":false},{"cost":"+5 PM","effect":"muda o alcance para pessoal e a área para esfera de 6m de raio. Todas as criaturas e objetos na área são afetados.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Detectar Ameaças', 'Divina', 1, 'Adivinhação', 'padrão', 'pessoal', 'Cena, até ser descarregada', 'Esfera de 18m de raio', '', '', 'Você recebe uma intuição aguçada sobre perigos ao seu redor. Quando uma criatura hostil ou armadilha entra na área do efeito, você faz um teste de Percepção (CD determinada pelo mestre de acordo com a situação). Se passar, sabe a origem (criatura ou armadilha), direção e distância do perigo. Se falhar, sabe apenas que o perigo existe.', '[{"cost":"+1 PM","effect":"você descobre também a raça ou espécie e o poder da criatura detectada (determinado pela aura dela). Criaturas de 1º a 6º nível geram aura tênue, criaturas de 7º a 12º nível geram aura moderada e criaturas de 13º ao 20º nível geram aura poderosa.\nCriaturas acima do 20º nível geram aura avassaladora.","isTrick":false},{"cost":"+2 PM","effect":"além do normal, você não fica surpreso e desprevenido contra perigos detectados com sucesso e recebe +5 em testes de resistência contra armadilhas. Requer 2º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Discrição', 'Universal', 1, 'Encantamento', 'padrão', 'pessoal ou toque', 'cena', '', 'Vontade anula', '', 'Esta magia torna a aparência do alvo desinteressante, como se ele fosse parte da paisagem, algo perdido na bagunça ou mais um na multidão. O alvo não se torna invisível, ainda é percebido como uma criatura ou objeto; o encantamento apenas desvia a atenção dos observadores para outras pessoas ou elementos ao redor. Testes de Investigação e Percepção contra o alvo sofrem uma penalidade de –10.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Disfarce Ilusório', 'Arcana', 1, 'Ilusão', 'padrão', 'pessoal', 'cena', '', 'Vontade desacredita', '', 'Você muda a aparência do alvo, incluindo seu equipamento. Isso inclui altura, peso, tom de pele, cor de cabelo, timbre de voz etc. O alvo recebe +10 em testes de Enganação para disfarce. O alvo não recebe novas habilidades (você pode ficar parecido com outra raça, mas não ganhará as habilidades dela), nem modifica o equipamento (uma espada longa disfarçada de bordão continua funcionando e causando dano como uma espada).', '[{"cost":"Truque","effect":"muda o alcance para toque, o alvo para 1 criatura e a duração para 1 semana. Em vez do normal, você faz uma pequena alteração na aparência do alvo, como deixar o nariz vermelho ou fazer brotar um gerânio no alto da cabeça. A mudança é inofensiva, mas persistente — se a flor for arrancada, por exemplo, outra nascerá no local.","isTrick":true},{"cost":"+1 PM","effect":"muda o alcance para curto e o alvo para 1 objeto. Você pode, por exemplo, transformar pedaços de ferro em moedas de ouro. Você recebe +10 em testes de Enganação para falsificação.","isTrick":false},{"cost":"+2 PM","effect":"muda o alcance para curto e o alvo para 1 criatura. Uma criatura involuntária pode anular o efeito com um teste de Vontade.","isTrick":false},{"cost":"+2 PM","effect":"a ilusão inclui odores e sensações. Isso muda o bônus em testes de Enganação para disfarce para +20.","isTrick":false},{"cost":"+3 PM","effect":"muda o alcance para curto e o alvo para criaturas escolhidas. Cada criatura pode ter uma aparência diferente. Criaturas involuntárias podem anular o efeito com um teste de Vontade. Requer 2º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Distração Fugaz', 'Arcana', 1, 'Ilusão', 'padrão', 'curto', 'instantânea', '', 'Vontade anula', '', 'Esta magia busca algo de grande interesse pessoal (uma pessoa, um item, uma lembrança...) na memória do alvo e produz uma breve ilusão disso, visível a todos os presentes. Não é necessário que você conheça o interesse do alvo, a própria magia faz essa revelação. A magia, entretanto, não é capaz de revelar detalhes minuciosos (como o nome de uma pessoa ou item desejado), produzindo uma versão “genérica” do objeto de interesse.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Enfeitiçar', 'Arcana', 1, 'Encantamento', 'padrão', 'curto', 'cena', '', 'Vontade anula', '', 'O alvo fica enfeitiçado (veja a página 394). Um alvo hostil ou que esteja envolvido em um combate recebe +5 em seu teste de resistência. Se você ou seus aliados tomarem qualquer ação hostil contra o alvo, a magia é dissipada e o alvo retorna à atitude que tinha antes (ou piorada, de acordo com o mestre).', '[{"cost":"+2 PM","effect":"em vez do normal, você sugere uma ação para o alvo e ele obedece. A sugestão deve ser feita de modo que pareça aceitável, a critério do mestre. Pedir ao alvo que pule de um precipício, por exemplo, dissipa a magia. Já sugerir a um guarda que descanse um pouco, de modo que você e seus aliados passem por ele, é aceitável. Quando o alvo executa a ação, a magia termina. Você pode determinar uma condição específica para a sugestão: por exemplo, que um rico mercador doe suas moedas para o primeiro mendigo que encontrar.","isTrick":false},{"cost":"+5 PM","effect":"muda o alvo para 1 espírito ou monstro. Requer 3º círculo.","isTrick":false},{"cost":"+5 PM","effect":"afeta todos os alvos dentro do alcance.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Escapatória de Hyninn', 'Divina', 1, 'Abjuração', 'reação', 'pessoal', 'instantânea', '', '', '', 'Por um breve instante, você adquire uma agilidade espantosa para se esquivar de algum perigo súbito. Você recebe +5 em um teste de Ladinagem para desarmar armadilhas ou de Reflexos.', '[{"cost":"+2 PM","effect":"muda o alcance para curto e o alvo para 1 criatura. Requer 2º círculo.","isTrick":false},{"cost":"+5 PM","effect":"muda a execução para padrão e a duração para cena. Em vez do normal, o bônus se aplica a todos os testes destas perícias pela duração. Requer 3º círculo.","isTrick":false},{"cost":"+3 PM","effect":"(Apenas Devotos de Hyninn): além do normal, o alvo pode usar Evasão (Tormenta20, p. 73).","isTrick":false},{"cost":"+7 PM","effect":"(Apenas Devotos de Hyninn): além do normal, o alvo pode usar Evasão Aprimorada (Tormenta20, p. 75). Requer 4° círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Escudo da Fé', 'Divina', 1, 'Abjuração', 'reação', 'curto', '1 turno', '', '', '', 'Um escudo místico se manifesta momentaneamente para bloquear um golpe. O alvo recebe +2 na Defesa.', '[{"cost":"+1 PM","effect":"muda a execução para ação padrão, o alcance para toque e a duração para cena.","isTrick":false},{"cost":"+1 PM","effect":"também fornece ao alvo camuflagem leve contra ataques à distância.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o bônus na Defesa em +1.","isTrick":false},{"cost":"+2 PM","effect":"muda a execução para ação padrão, o alcance para toque e a duração para cena. A magia cria uma conexão mística entre você e o alvo. Além do efeito normal, o alvo sofre metade do dano por ataques e efeitos; a outra metade do dano é transferida a você. Se o alvo sair de alcance curto de você, a magia é dissipada. Requer 2º círculo.","isTrick":false},{"cost":"+3 PM","effect":"muda a duração para 1 dia. Requer 2º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Escuridão', 'Universal', 1, 'Necromancia', 'padrão', 'curto', 'cena', '', 'Vontade anula (veja texto)', '', 'O alvo emana sombras em uma área com 6m de raio. Criaturas dentro da área recebem camuflagem leve por escuridão leve. As sombras não podem ser iluminadas por nenhuma fonte de luz natural. O objeto pode ser guardado (em um bolso, por exemplo) para interromper a escuridão, que voltará a funcionar caso o objeto seja revelado. Se lançar a magia num objeto de uma criatura involuntária, ela tem direito a um teste de Vontade para anulá-la. Escuridão anula Luz.', '[{"cost":"+1 PM","effect":"aumenta a área da escuridão em +1,5m de raio.","isTrick":false},{"cost":"+2 PM","effect":"muda o efeito para fornecer camuflagem total por escuridão total. As sombras bloqueiam a visão na área e através dela.","isTrick":false},{"cost":"+2 PM","effect":"muda o alvo para 1 criatura e a resistência para Fortitude parcial. Você lança a magia nos olhos do alvo, que fica cego pela cena. Se passar na resistência, fica cego por 1 rodada. Requer 2º círculo.","isTrick":false},{"cost":"+3 PM","effect":"muda a duração para 1 dia.","isTrick":false},{"cost":"+5 PM","effect":"muda o alcance para pessoal e o alvo para você. Em vez do normal, você é coberto por sombras, recebendo +10 em testes de Furtividade e camuflagem leve. Requer 2º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Espírito Balístico', 'Arcana', 1, 'Convocação', 'padrão', 'curto', 'sustentada', '', '', '', 'Esta magia invoca um pequeno espírito feito de energia com aparência a sua escolha em um espaço desocupado. O espírito é fixo, permanecendo no lugar onde foi invocado. No começo dos seus turnos, o espírito dispara um projétil mágico contra o inimigo mais próximo em alcance médio, causando 1d6+1 pontos de dano de perfuração. O espírito não realiza outras ações e dispara projéteis a cada rodada, até que a magia termine, não existam mais inimigos no alcance ou o espírito seja destruído.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Euforia de Valkaria', 'Divina', 1, 'Encantamento', 'padrão', 'pessoal', 'cena', '', '', '', 'Esta magia enche o alvo de disposição, apagando o medo (e bom senso) em seu coração e impedindo-o de ser intimidado por desafios árduos.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Execução de Thwor', 'Divina', 1, 'Necromancia', 'movimento', 'curto', '1 rodada', '', 'Vontade anula', '', 'Se acertar seu próximo ataque no alvo, ele se torna um acerto crítico. Se for um crítico naturalmente, em vez disso seu multiplicador aumenta em +1.', '[{"cost":"+2 PM","effect":"muda o alvo para 1 criatura. Requer 2º círculo.","isTrick":false},{"cost":"+5 PM","effect":"em vez do normal, a magia afeta 1 alvo sob efeito de uma condição mental. Requer 3º círculo.","isTrick":false},{"cost":"+7 PM","effect":"(Apenas Devotos de Thwor): se o ataque for um acerto crítico naturalmente, em vez do normal ele causa o efeito de um golpe de misericórdia (Tormenta20, p. 235). Requer 5º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Explosão de Chamas', 'Arcana', 1, 'Evocação', 'padrão', 'pessoal', 'instantânea', 'Cone de 6m', 'Reflexos reduz à metade', '', 'Um leque de chamas irrompe de suas mãos, causando 2d6 pontos de dano de fogo às criaturas na área.', '[{"cost":"Truque","effect":"muda o alcance para curto, a área para alvo de 1 objeto e a resistência para Reflexos anula. Você gera uma pequena explosão que não causa dano mas pode acender uma vela, tocha ou fogueira. Também pode fazer um objeto inflamável com RD 0 (como uma corda ou pergaminho) ficar em chamas. Uma criatura em posse de um objeto pode evitar esse efeito se passar no teste de resistência.","isTrick":true},{"cost":"+1 PM","effect":"aumenta o dano em +1d6.","isTrick":false},{"cost":"+1 PM","effect":"muda a resistência para Reflexos parcial. Se passar, a criatura reduz o dano à metade; se falhar, fica em chamas (veja Condições, no Apêndice).","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Farejar Fortuna', 'Arcana', 1, 'Adivinhação', 'padrão', 'pessoal', 'cena', '', '', '', 'Ao lançar esta magia, você descobre se existe algum tesouro em alcance longo. Para este efeito, “tesouro” é qualquer acúmulo de itens valiosos (acima do dinheiro inicial de um personagem do seu nível) que não estejam sendo carregados ou vestidos por uma criatura inteligente.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Flecha de Luz', 'Universal', 1, 'Evocação', 'padrão', 'médio', 'instantânea', '', 'Reflexos parcial', '', 'Esta magia lança uma flecha luminosa contra o alvo, que sofre 2d8+2 pontos de dano de luz e fica ofuscado por 1 rodada. Passar no teste de resistência reduz o dano à metade e evita a condição.', '[{"cost":"+1 PM","effect":"muda o alvo para uma criatura que tenha causado dano a você ou a seus aliados na última rodada e os dados de dano da magia para d10.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o dano em +1d8+1.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o número de alvos em +1 (número de alvos adicionais limitado pelo círculo máximo de magia que você pode lançar).","isTrick":false},{"cost":"+2 PM","effect":"(Apenas Arcanos): alvos que falhem na resistência ficam cegos por 1 rodada e então ofuscados. Requer 2º círculo.","isTrick":false},{"cost":"+3 PM","effect":"(Apenas Arqueiros de Lenórienn): muda o alcance para pessoal, o alvo para seu arco arcano, a duração para sustentada e a resistência para nenhuma. Em vez do normal, o alvo emite luz como uma tocha e causa +2d8+2 pontos de dano de luz. Criaturas que sofram dano do arco ficam ofuscadas (veja Arqueiro de Lenórienn em Heróis de Arton).","isTrick":false},{"cost":"+1 PM","effect":"(Apenas Elfos): muda o alvo para 1 duyshidakk ou 1 devoto de Aharadak, Tauron ou Thwor. Muda os dados de dano para d10.","isTrick":false},{"cost":"+2 PM","effect":"(Apenas Divinos): além do normal, para cada alvo que falhar na resistência, o próximo aliado que causar dano a ele recebe uma quantidade de PV temporários igual à metade do dano causado pela magia. Requer 2º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Frescor de Lena', 'Divina', 1, 'Abjuração', 'padrão', 'pessoal', 'instantânea', 'raio de 9m', '', '', 'Você emana uma aura refrescante, que envolve você e aliados na área. A aura purifica o ar ao redor, eliminando todo tipo de fumaça, poeira, gás nocivo, nuvem ácida ou veneno de inalação, exceto se forem gerados por magias de 2º círculo ou maior.', '[{"cost":"+2 PM","effect":"aumenta em 1 o círculo de magia afetado (limitado pelo círculo máximo de magia que você pode lançar).","isTrick":false},{"cost":"+2 PM","effect":"muda o alcance para toque, a área para alvo (1 criatura) e a duração para 1 dia. Em vez do normal, suprime uma doença do alvo. Requer 2° círculo.","isTrick":false},{"cost":"+3 PM","effect":"(Apenas Devotos de Lena): como acima, mas quando faz o teste da doença nesse dia, o alvo recebe um bônus de +5. Requer 3° círculo.","isTrick":false},{"cost":"+9 PM","effect":"(Apenas Devotos de Lena): muda o alcance para toque, a área para alvo (1 criatura) e adiciona componente material (ervas no valor de T$ 1.000). O alvo recupera 1 ponto de atributo perdido por uma doença. Requer 4° círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Fúria dos Antepassados', 'Divina', 1, 'Evocação', 'padrão', 'curto', 'instantânea', '', 'Vontade parcial', '', 'Para aqueles devotados a Lin-Wu, respeito aos ancestrais é algo levado muito a sério — pois no além-vida, eles podem julgar suas ações e trazer fortuna ou desgraça. Esta magia invoca a alma de um antepassado da vítima para acusá-la de erros passados e trazer punição. O alvo sofre 1d6 pontos de dano psíquico e 1d6 pontos de dano de luz e fica pasmo por 1 rodada (apenas na primeira vez que é alvo desta magia na cena). Se passar no teste de resistência, sofre apenas metade do dano e evita a condição.', '[{"cost":"+2 PM","effect":"aumenta o número de alvos em +1. Requer 2° círculo.","isTrick":false},{"cost":"+4 PM","effect":"aumenta o dano psíquico e de luz em +1d6 cada.","isTrick":false},{"cost":"+0 PM","effect":"(Apenas Devotos de Lin-Wu): muda o alvo para 1 criatura inteligente (Int –3 ou maior).","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Futuro Melhor', 'Divina', 1, 'Adivinhação', 'reação', 'pessoal', 'instantânea', '', '', '', 'Esta magia permite enxergar todas as possibilidades e consequências de um evento muito recente, ainda a tempo de escolher o melhor caminho. O alvo recebe +2 em um teste cujo dado já rolou, mas cujo resultado o mestre ainda não tenha declarado.', '[{"cost":"+2 PM","effect":"muda o alcance para curto e o alvo para 1 criatura. Requer 2º círculo.","isTrick":false},{"cost":"+2 PM","effect":"(Apenas Devotos de Thyatis): muda o bônus para 1d4+2.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Hipnotismo', 'Arcana', 1, 'Encantamento', 'padrão', 'curto', '1d4 Rodadas', '', 'Vontade anula', '', 'Suas palavras e movimentos ritmados deixam o alvo fascinado. Esta magia só afeta criaturas que possam perceber você. Se usar esta magia em combate, o alvo recebe +5 em seu teste de resistência. Se a criatura passar, fica imune a este efeito por um dia.', '[{"cost":"Truque","effect":"muda a duração para 1 rodada. Em vez de fascinado, o alvo fica pasmo. (apenas uma vez por cena)","isTrick":true},{"cost":"+1 PM","effect":"como o normal, mas alvos que passarem na resistência não sabem que foram vítimas de uma magia.","isTrick":false},{"cost":"+2 PM","effect":"muda o alvo para animais ou humanoides escolhidos.","isTrick":false},{"cost":"+2 PM","effect":"muda a duração para sustentada.","isTrick":false},{"cost":"+2 PM","effect":"também afeta espíritos e monstros na área. Requer 2º círculo.","isTrick":false},{"cost":"+5 PM","effect":"também afeta construtos, espíritos, monstros e mortos-vivos na área. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Imagem Espelhada', 'Arcana', 1, 'Ilusão', 'padrão', 'pessoal', 'cena', '', '', '', 'Três cópias ilusórias suas aparecem. As duplicatas ficam ao seu redor e imitam suas ações, tornando difícil para um inimigo saber quem atacar. Você recebe +6 na Defesa. Cada vez que um ataque contra você erra, uma das imagens desaparece e o bônus na Defesa diminui em 2. Um oponente deve ver as cópias para ser confundido. Se você estiver invisível, ou o atacante fechar os olhos, você não recebe o bônus (mas o atacante ainda sofre penalidades normais por não enxergar).', '[{"cost":"+2 PM","effect":"aumenta o número de cópias em +1 (e o bônus na Defesa em +2).","isTrick":false},{"cost":"+2 PM","effect":"além do normal, toda vez que uma cópia é destruída, emite um clarão de luz. A criatura que destruiu a cópia fica ofuscada por uma rodada. Requer 2º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Infligir Ferimentos', 'Divina', 1, 'Necromancia', 'padrão', 'toque', 'instantânea', '', 'Fortitude reduz à metade', '', 'Você canaliza energia negativa contra um alvo, causando 2d8+2 pontos de dano de trevas (ou curando 2d8+2 PV, se for um morto-vivo). Infligir Ferimentos anula Curar Ferimentos.', '[{"cost":"+1 PM","effect":"além do normal, se falhar na resistência, o alvo fica fraco pela cena (passar no teste de resistência evita).","isTrick":false},{"cost":"+2 PM","effect":"aumenta o dano em 1d8+1.","isTrick":false},{"cost":"+2 PM","effect":"muda a resistência para nenhum. Como parte da execução da magia, você pode fazer um ataque corpo a corpo contra o alvo. Se acertar, causa o dano do ataque e o efeito da magia.","isTrick":false},{"cost":"+5 PM","effect":"muda o alcance para curto e o alvo para criaturas escolhidas.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Infortúnio de Sszzaas', 'Divina', 1, 'Necromancia', 'padrão', 'curto', 'cena', '', 'Vontade anula', '', 'Esta maldição menor reduz a resiliência da vítima, tornando-a mais suscetível a efeitos nocivos. O alvo sofre –2 em testes de sua resistência originalmente mais baixa.', '[{"cost":"+1 PM","effect":"além do normal, a vítima perde imunidade a venenos até o fim da próxima rodada. Requer 2° círculo.","isTrick":false},{"cost":"+2 PM","effect":"aumenta a penalidade em –1 (penalidade máxima limitada pelo círculo máximo de magia que você pode lançar).","isTrick":false},{"cost":"+3 PM","effect":"(Apenas Devotos de Sszzaas): além do normal, quando o alvo morre, deixa para trás um pequeno cristal com memórias e segredos. Ao resolver uma busca (Tormenta20, p. 278), um personagem pode quebrar um desses cristais para receber +2 em um teste de perícia. Requer 3° círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Instante Estoico', 'Divina', 1, 'Abjuração', 'reação', 'pessoal', 'instantânea', '', '', '', 'Invocando a proteção de Khalmyr, você resiste a agressões potencialmente perigosas. Quando sofre dano não mágico, você recebe RD 10 contra esse dano.', '[{"cost":"+1 PM","effect":"muda a RD para 20. Requer 2° círculo.","isTrick":false},{"cost":"+2 PM","effect":"além do normal, para cada 10 pontos de dano que a magia reduzir em um turno, sua próxima rolagem de dano feita até a próxima rodada causa +1d6 pontos de dano de essência.","isTrick":false},{"cost":"+1 PM","effect":"(Apenas Devotos de Khalmyr): muda a execução para padrão e a duração para cena, até ser descarregada. Em vez do normal, quando sofre dano não mágico, você pode receber RD 10 contra esse dano. A magia é descarregada após você usar este efeito pela terceira vez. Requer 3º círculo.","isTrick":false},{"cost":"+2 PM","effect":"(Apenas Devotos de Khalmyr): muda o alcance para toque e o alvo para 1 criatura.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Jato Corrosivo', 'Arcana', 1, 'Evocação', 'padrão', 'pessoal', 'instantânea', 'linha de 9m', 'Reflexos reduz à metade', '', 'Você dispara um jato, que causa 2d6 pontos de dano de ácido às criaturas na área. Contra construtos e objetos soltos, a magia causa +1 ponto de dano por dado.', '[{"cost":"+1 PM","effect":"aumenta o dano em +1d6.","isTrick":false},{"cost":"+1 PM","effect":"muda a resistência para Reflexos parcial. Se passar, a criatura reduz o dano à metade; se falhar, fica vulnerável.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Leque Cromático', 'Arcana', 1, 'Ilusão', 'padrão', 'pessoal', 'instantânea', 'cone de 4,5m', 'Vontade parcial', '', 'Um cone de luzes brilhantes surge das suas mãos, deixando os animais e humanoides na área atordoados por 1 rodada (apenas uma vez por cena, Vontade anula) e ofuscados pela cena.', '[{"cost":"+2 PM","effect":"além do normal, as criaturas afetadas ficam vulneráveis pela cena.","isTrick":false},{"cost":"+2 PM","effect":"também afeta espíritos e monstros na área. Requer 2º círculo.","isTrick":false},{"cost":"+5 PM","effect":"também afeta construtos, espíritos, monstros e mortos-vivos na área. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Luz', 'Universal', 1, 'Evocação', 'padrão', 'curto', 'cena', '', 'Vontade anula (veja texto)', '', 'O alvo emite luz (mas não produz calor) em uma área com 6m de raio. O objeto pode ser guardado (em um bolso, por exemplo) para interromper a luz, que voltará a funcionar caso o objeto seja revelado. Se lançar a magia num objeto de uma criatura involuntária, ela tem direito a um teste de Vontade para anulá-la. Luz anula Escuridão.', '[{"cost":"+1 PM","effect":"aumenta a área iluminada em +3m de raio.","isTrick":false},{"cost":"+2 PM","effect":"muda a duração para 1 dia.","isTrick":false},{"cost":"+2 PM","effect":"muda a duração para permanente e adiciona componente material (pó de rubi no valor de T$ 50). Não pode ser usado em conjunto com outros aprimoramentos. Requer 2º círculo.","isTrick":false},{"cost":"+0 PM","effect":"(Apenas Arcanos): muda o alvo para 1 criatura. Você lança a magia nos olhos do alvo, que fica ofuscado pela cena. Não afeta criaturas cegas.","isTrick":false},{"cost":"+2 PM","effect":"(Apenas Arcanos): muda o alcance para longo e o efeito para cria 4 pequenos globos flutuantes de pura luz. Você pode posicionar os globos onde quiser dentro do alcance. Você pode enviar um à frente, outra para trás, outra para cima e manter um perto de você, por exemplo. Uma vez por rodada, você pode mover os globos com uma ação livre. Cada um ilumina como uma tocha, mas não produz calor. Se um globo ocupar o espaço de uma criatura, ela fica ofuscada e sua silhueta pode ser vista claramente (ela não recebe camuflagem por escuridão ou invisibilidade). Requer 2º círculo.","isTrick":false},{"cost":"+2 PM","effect":"(Apenas Divinos): a luz é cálida como a do sol. Criaturas que sofrem penalidades e dano pela luz solar sofrem seus efeitos como se estivessem expostos à luz solar real. Seus aliados na área estabilizam automaticamente e ficam imunes à condição sangrando, e seus inimigos ficam ofuscados. Requer 2º círculo.","isTrick":false},{"cost":"+5 PM","effect":"(Apenas Divinos): muda o alcance para toque e o alvo para 1 criatura. Em vez do normal, o alvo é envolto por um halo de luz, recebendo +10 em testes de Diplomacia e resistência a trevas 10. Requer 2º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Maaais Klunc', 'Arcana', 1, 'Transmutação', 'padrão', 'pessoal', 'cena', '', '', '', 'Esta magia surgiu com o objetivo de invocar a força estupenda e estapafúrdia de certo bárbaro lendário, capaz de alcançar dimensões colossais. Infelizmente (ou talvez felizmente) seus efeitos reais são muito mais brandos, pouco se aproximando do poder descomunal e descabido do bruto em questão. Melhor assim.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Magia Dadivosa', 'Divina', 1, 'Transmutação', 'movimento', 'pessoal', 'cena, até ser descarregada', '', '', '', 'Não é comum descrever uma divindade maior do Panteão como “maluquinha”. Contudo, há ocasiões em que Wynna faz por merecer — como quando oferece estas dádivas caóticas. No início de seu turno, role 1d4. Em um resultado 4, você recebe 1 PM temporário que só pode ser gasto em aprimoramentos de magias. A magia é descarregada quando você recebe um total de 4 PM temporários. Você só pode lançar esta magia uma vez por cena.', '[{"cost":"+1 PM","effect":"muda o alcance para curto e o alvo para 1 criatura. Requer 3° círculo.","isTrick":false},{"cost":"+0 PM","effect":"(Apenas Devotos de Wynna): muda a execução para padrão, o ganho para +2 PM temporários e o limite para descarregar para +8 PM.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Névoa', 'Universal', 1, 'Convocação', 'padrão', 'curto', 'cena', '', '', '', 'Uma névoa espessa eleva-se de um ponto a sua escolha, obscurecendo toda a visão — criaturas a até 1,5m têm camuflagem e criaturas a partir de 3m têm camuflagem total. Um vento forte dispersa a névoa em 4 rodadas e um vendaval a dispersa em 1 rodada. Esta magia não funciona sob a água.', '[{"cost":"+1 PM","effect":"a magia também funciona sob a água, criando uma nuvem de tinta.","isTrick":false},{"cost":"+2 PM","effect":"você pode escolher criaturas no alcance ao lançar a magia; elas enxergam através do efeito. Requer 2º círculo.","isTrick":false},{"cost":"+2 PM","effect":"a nuvem tem um cheiro horrível. No início de seus turnos, qualquer criatura dentro dela, ou qualquer criatura com faro em alcance curto da nuvem, deve fazer um teste de Fortitude. Se falhar, fica enjoada por uma rodada.","isTrick":false},{"cost":"+2 PM","effect":"a nuvem tem um tom esverdeado e se torna cáustica. No início de seus turnos, criaturas dentro dela sofrem 2d4 pontos de dano de ácido.","isTrick":false},{"cost":"+3 PM","effect":"aumenta o dano de ácido em +2d4.","isTrick":false},{"cost":"+5 PM","effect":"além do normal, a nuvem fica espessa, quase sólida. Qualquer criatura dentro dela tem seu deslocamento reduzido para 3m (independentemente de seu deslocamento normal) e sofre –2 em testes de ataque e rolagens de dano.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Orbe do Oceano', 'Divina', 1, 'Abjuração', 'padrão', 'pessoal', 'sustentada', '', '', '', 'O suposto desaparecimento do Oceano se mostra particularmente misterioso pelo fato de que seus devotos ainda podem lançar magias. Você cria um globo protetor de água salgada que ocupa 1 quadrado e o acompanha, fornecendo a você camuflagem leve e cobertura leve.', '[{"cost":"+4 PM","effect":"muda a duração para cena. Requer 3º círculo.","isTrick":false},{"cost":"+2 PM","effect":"(Apenas Devotos de Oceano): além do normal, você é considerado submerso. Isso exige que você prenda a respiração (a menos que possa respirar debaixo d’água), mas faz com que sofra apenas a metade do dano de armas de corte e impacto que não sejam armas naturais e é considerado submerso para benefícios de suas habilidades que dependam dessa situação.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Orientação', 'Divina', 1, 'Adivinhação', 'padrão', 'curto', '1 rodada', '', '', '', 'Em seu próximo teste de perícia, o alvo pode rolar dois dados e ficar com o melhor resultado', '[{"cost":"+2 PM","effect":"muda a duração para cena. Em vez do normal, escolha um atributo. Sempre que o alvo fizer um teste de perícia baseado no atributo escolhido, pode rolar dois dados e ficar com o melhor resultado. Não se aplica a testes de ataque ou resistência.\nRequer 2º círculo.","isTrick":false},{"cost":"+5 PM","effect":"muda a duração para cena. Escolha entre atributos físicos (Força, Destreza e Constituição) ou mentais (Inteligência, Sabedoria e Carisma). Sempre que o alvo fizer um teste de perícia, pode rolar dois dados e ficar com o melhor resultado. Não se aplica a testes de ataque ou resistência. Requer 3º círculo.","isTrick":false},{"cost":"+5 PM","effect":"muda o alvo para criaturas escolhidas. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Ossos de Adamante', 'Arcana', 1, 'Transmutação', 'padrão', 'pessoal', 'cena', '', '', '', 'Esta magia confere resistência extraordinária ao esqueleto, evitando ataques que causam fraturas graves. O alvo recebe redução de impacto 5 e fortificação 25%.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Paixão de Marah', 'Divina', 1, 'Encantamento', 'padrão', 'pessoal', 'cena', '', '', '', 'Você é cercado por uma aura de magnetismo pessoal que o torna mais interessante e atraente aos olhos dos demais. Você recebe +2 em perícias originalmente baseadas em Carisma (exceto Intimidação).', '[{"cost":"+2 PM","effect":"muda o alcance para curto e o alvo para 1 criatura.","isTrick":false},{"cost":"+1 PM","effect":"(Apenas Devotos de Marah): além do normal, o alvo recebe +1 em Carisma. Esse aumento não oferece PV ou PM adicionais.","isTrick":false},{"cost":"+3 PM","effect":"(Apenas Devotos de Marah): muda a duração para 1 dia. Requer 2º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Percepção Rubra', 'Universal', 1, 'Adivinhação', 'padrão', 'pessoal', 'cena', '', '', '', 'Esta magia faz o conjurador adquirir, por algum tempo, a estranha percepção de tempo dos lefeu — que permite ver alguns momentos no futuro. O alvo recebe +1 em testes de ataque, em Reflexos e na Defesa.', '[{"cost":"+1 PM","effect":"muda o alcance para curto e o alvo para 1 criatura.","isTrick":false},{"cost":"+2 PM","effect":"(Apenas Devotos de Aharadak): aumenta o bônus em +1 (bônus máximo limitado pelo círculo máximo de magia que você pode lançar).","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Perdição', 'Divina', 1, 'Necromancia', 'padrão', 'curto', 'cena', '', 'nenhuma', '', 'Amaldiçoa os alvos, que recebem –1 em testes de ataque e rolagens de dano. Perdição anula Bênção.', '[{"cost":"+2 PM","effect":"aumenta as penalidades em –1, limitado pelo círculo máximo de magia que você pode lançar.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Perturbação Sombria', 'Divina', 1, 'Ilusão', 'padrão', 'pessoal', 'cena', '', '', '', 'Com a proteção de Tenebra, você emana uma aura de sombras com 6m de raio. As sombras se movem de formas estranhas, com rangidos e gemidos sem explicação, vultos fugidios nas janelas e faces macabras urrando para sumir no instante seguinte. As demais criaturas na área sofrem –5 em testes de Percepção. Medo.', '[{"cost":"+2 PM","effect":"muda o efeito para aura de 9m.","isTrick":false},{"cost":"+5 PM","effect":"muda o alcance para toque e o alvo para 1 criatura ou objeto. O alvo emana a aura.","isTrick":false},{"cost":"+5 PM","effect":"você pode escolher quais criaturas são afetadas pela aura. Requer 2º círculo.","isTrick":false},{"cost":"+9 PM","effect":"muda o alcance para curto, o alvo para área (esfera de 6m de raio), a execução para 1 hora, a duração para permanente e adiciona componente material (incenso e óleos no valor de T$ 1.000). Requer 5° círculo.","isTrick":false},{"cost":"+2 PM","effect":"(Apenas Devotos de Tenebra): adiciona resistência (Vontade parcial). Além do normal, criaturas que comecem seu turno dentro da área ficam abaladas. Passar no teste de resistência evita a condição e impede que a criatura seja abalada por esta magia até o fim da cena. Requer 2° círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Poder de Kallyadranoch', 'Divina', 1, 'Evocação', 'movimento', 'pessoal', '1 turno', '', '', '', 'Por um breve momento, você manifesta uma pequena parte da força e majestade das grandes feras dracônicas: a capacidade de criar elementos em sua forma mais pura. Até o fim do seu turno, a CD para resistir às suas habilidades mágicas que causam dano de ácido, eletricidade, fogo ou frio aumenta em +2.', '[{"cost":"+2 PM","effect":"aumenta a CD em +1 (bônus máximo limitado pelo círculo máximo de magias que você pode lançar). Requer 3° círculo.","isTrick":false},{"cost":"+1 PM","effect":"(Apenas Devotos de Kallyadranoch): além do normal, criaturas que falhem nos testes de resistência contra suas habilidades mágicas sofrem uma condição baseada no tipo de dano. Ácido: vulnerável até o fim da cena. Eletricidade: atordoado por 1 rodada (apenas uma vez por cena). Fogo: em chamas e vulnerável enquanto estiver em chamas. Frio: lento até o fim da cena. Requer 2° círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Posse de Arsenal', 'Divina', 1, 'Convocação', 'padrão', 'pessoal', '1 dia', '', '', '', 'Esta magia cria um vínculo poderoso entre você e seus pertences, dificultando sua perda ou roubo. Você recebe +5 em testes contra as manobras desarmar e quebrar, e de Percepção contra punga (veja Ladinagem) para roubá-lo. Além disso, se tiver o item tirado de você involuntariamente e ele estiver em alcance curto, você pode invocá-lo às suas mãos com uma ação livre.', '[{"cost":"+2 PM","effect":"(Apenas Devotos de Arsenal): além do normal, você também pode convocar uma arma à sua mão mesmo se ela tiver sido arremessada voluntariamente.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Primor Atlético', 'Arcana', 1, 'Transmutação', 'padrão', 'toque', 'cena', '', '', '', 'Você modifica os limites físicos do alvo, que recebe deslocamento +9m e +10 em testes de Atletismo.', '[{"cost":"+1 PM","effect":"além do normal, o alvo recebe um bônus adicional de +20 em testes de Atletismo para saltar (para um bônus total de +30).","isTrick":false},{"cost":"+1 PM","effect":"além do normal, o alvo pode escalar paredes e tetos sem precisar fazer testes de Atletismo. Para isso, precisa estar com as mãos livres, mas pode usar uma única mão se ficar parado no lugar. O alvo não fica desprevenido enquanto escala.","isTrick":false},{"cost":"+1 PM","effect":"muda a execução para ação de movimento, o alcance para pessoal, o alvo para você e a duração para instantânea. Você salta muito alto e pousa em alcance corpo a corpo de uma criatura em alcance curto. Se fizer um ataque corpo a corpo contra essa criatura neste turno, recebe os benefícios e penalidades de uma investida e sua arma causa um dado extra de dano do mesmo tipo durante este ataque.","isTrick":false},{"cost":"+3 PM","effect":"além do normal, ao fazer testes de perícias baseadas em Força, Destreza ou Constituição, o alvo pode rolar dois dados e escolher o melhor. Não afeta testes de ataque ou resistência. Requer 2º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Profanar', 'Divina', 1, 'Necromancia', 'padrão', 'longo', '1 dia', 'esfera com 9m de raio', '', '', 'Você enche a área com energia negativa. Dano causado por efeitos de trevas é maximizado dentro da área. Isso também afeta PV curados em mortos-vivos por esses efeitos. Esta magia não pode ser lançada em uma área contendo um símbolo visível dedicado a uma divindade que não a sua. Profanar anula Consagrar.', '[{"cost":"+1 PM","effect":"além do normal, mortos-vivos na área recebem +2 na Defesa e +2 em todos os testes.","isTrick":false},{"cost":"+2 PM","effect":"aumenta os bônus para mortos-vivos em +1.","isTrick":false},{"cost":"+9 PM","effect":"muda a execução para 1 hora, a duração para permanente e adiciona componente material (incenso e óleos no valor de T$ 1.000). Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Proteção de Tauron', 'Divina', 1, 'Abjuração', 'movimento', 'curto', 'cena', '', '', '', 'Esta antiga magia ofertada pelo Deus da Força ainda pode ser lançada mesmo após sua morte, preservada por divindades simpatizantes em honra a seu aspecto como protetor dos fracos. Quando a magia é lançada, luz sagrada envolve o alvo, que se torna um “protegido”; ele recebe +2 na Defesa e, quando se move em sua direção, o deslocamento dele é dobrado. Além disso, você sabe a direção e distância do alvo, e também se ele está ferido ou afetado por qualquer condição, independentemente da distância. Você não pode lançar esta magia enquanto for o “protegido” de outra criatura.', '[{"cost":"+2 PM","effect":"além do normal, você pode usar habilidades mágicas com alcance de toque no alvo como se elas tivessem alcance curto.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o bônus na Defesa em +2 (bônus máximo limitado ao dobro do círculo máximo de magia que você pode lançar). Requer 2º círculo.","isTrick":false},{"cost":"+2 PM","effect":"(Apenas Minotauros): além do normal, uma vez por rodada, quando uma criatura faz uma ação hostil contra o protegido, você pode gastar 1 PM para fazer um ataque corpo a corpo contra ela, desde que ela esteja em seu alcance pessoal.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Proteção Divina', 'Divina', 1, 'Abjuração', 'padrão', 'toque', 'cena', '', '', '', 'Esta magia cria uma barreira mística invisível que fornece ao alvo +2 em testes de resistência.', '[{"cost":"+2 PM","effect":"aumenta o bônus concedido em +1.","isTrick":false},{"cost":"+2 PM","effect":"muda a execução para reação, o alcance para curto e a duração para 1 rodada. Em vez do normal, o alvo recebe +5 no próximo teste de resistência que fizer (cumulativo com o efeito básico desta magia).","isTrick":false},{"cost":"+2 PM","effect":"muda o alvo para área de esfera com 3m de raio. Todos os aliados dentro da esfera recebem o bônus da magia. Requer 2º círculo.","isTrick":false},{"cost":"+5 PM","effect":"também torna o alvo imune a efeitos mentais e de medo. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Punho de Mitral', 'Arcana', 1, 'Transmutação', 'padrão', 'pessoal', 'cena', '', '', '', 'Esta magia transforma uma de suas mãos em mitral, tornando-a prateada como esse metal. A mão continua capaz de realizar movimentos normais e segurar objetos — mas também pode golpear ou esmagar. Se não estiver segurando nada com essa mão, você recebe +1 em testes de ataque e na margem de ameaça com ataques desarmados, e pode causar dano letal ou não letal com eles. Por fim, você pode manipular venenos com essa mão sem chance de se envenenar acidentalmente.', '[{"cost":"+2 PM","effect":"muda o bônus em testes de ataque e na margem de ameaça para +2.","isTrick":false},{"cost":"+2 PM","effect":"muda o alcance para toque e o alvo para 1 criatura. Requer 2º círculo.","isTrick":false},{"cost":"+5 PM","effect":"além do normal, se você estiver empunhando uma arma ou um item esotérico com essa mão, ele recebe os benefícios do material especial mitral (mesmo que já possua outro material especial). Requer 2° círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Queda Suave', 'Arcana', 1, 'Transmutação', 'reação', 'curto', 'até chegar ao solo ou cena, o que vier primeiro', '', '', '', 'O alvo cai lentamente. A velocidade da queda é reduzida para 18m por rodada — o suficiente para não causar dano.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Raio do Enfraquecimento', 'Arcana', 1, 'Necromancia', 'padrão', 'curto', 'cena', '', 'Fortitude parcial', '', 'Você dispara um raio púrpura que drena as forças do alvo. Se falhar na resistência, o alvo fica Fatigado Se passar, fica Vulnerável.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Resistência à Energia', 'Universal', 1, 'Abjuração', 'padrão', 'toque', 'cena', '', '', '', 'Ao lançar esta magia, escolha entre ácido, eletricidade, fogo, frio, luz ou trevas. O alvo recebe redução de dano 10 contra o tipo de dano escolhido.', '[{"cost":"+2 PM","effect":"aumenta a redução de dano em +5.","isTrick":false},{"cost":"+2 PM","effect":"muda a duração para 1 dia. Requer 2º círculo.","isTrick":false},{"cost":"+5 PM","effect":"muda o alcance para curto e o alvo para criaturas escolhidas. Requer 3º círculo.","isTrick":false},{"cost":"+5 PM","effect":"muda o efeito para redução de dano contra todos os tipos listados na magia. Requer 3º círculo.","isTrick":false},{"cost":"+9 PM","effect":"muda o efeito para imunidade a um tipo listado na magia. Requer 4º círculo","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Santuário', 'Divina', 1, 'Abjuração', 'padrão', 'toque', 'cena', '', 'Vontade anula', '', 'Qualquer criatura que tente fazer uma ação hostil contra o alvo deve fazer um teste de Vontade. Se falhar, não consegue, perde a ação e não pode tentar novamente enquanto a magia durar. Santuário não protege o alvo de efeitos de área. Além disso, o próprio alvo também não pode fazer ações hostis (incluindo forçar outras criaturas a atacá-lo), ou a magia é dissipada — mas pode usar habilidades e magias de cura e suporte, como Curar Ferimentos e Bênção.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Seta Infalível de Talude', 'Arcana', 1, 'Evocação', 'padrão', 'médio', 'instantânea', '', '', '', 'Favorita entre arcanistas iniciantes, esta magia lança duas setas de energia que causam 1d4+1 pontos de dano de essência cada. Você pode lançar as setas em alvos diferentes ou concentrá-las num mesmo alvo. Caso você possua um bônus no dano de magias, como pelo poder Arcano de Batalha, ele é aplicado em apenas uma seta (o bônus vale para a magia, não cada alvo).', '[{"cost":"+2 PM","effect":"muda as setas para lanças de energia que surgem e caem do céu. Cada lança causa 1d8+1 pontos de dano de essência. Requer 2º círculo.","isTrick":false},{"cost":"+2 PM","effect":"muda o número de setas/lanças para três.","isTrick":false},{"cost":"+4 PM","effect":"muda o número de setas/lanças para cinco. Requer 2º círculo.","isTrick":false},{"cost":"+9 PM","effect":"muda o número de setas/lanças para dez. Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Sigilo de Sszzaas', 'Divina', 1, 'Abjuração', 'padrão', 'pessoal', '1 dia', '', '', '', 'Ofertada pelo Deus dos Segredos, esta magia é utilizada por todos que buscam preservar a própria privacidade. Pela duração da magia, quaisquer criaturas que fizerem testes de perícia para obter alguma informação a seu respeito sofrem –5 nesses testes. Isso inclui testes de Percepção para notá- -lo, Conhecimento e Investigação para descobrir algo sobre você, Intuição para discernir suas mentiras e disfarces, e assim por diante.', '[{"cost":"+2 PM","effect":"muda o alcance para toque e o alvo para 1 criatura. Requer 2º círculo.","isTrick":false},{"cost":"+2 PM","effect":"adiciona resistência (Vontade evita). Além do normal, criaturas que usem habilidades mágicas de detecção, como a magia Vidência, devem fazer um teste de Vontade. Se falharem, a habilidade não funciona e, pela duração da magia, novas tentativas de usar a mesma habilidade feitas pela mesma criatura falham automaticamente. Requer 2º círculo.","isTrick":false},{"cost":"+2 PM","effect":"(Apenas Devotos de Sszzaas): muda a penalidade para –10.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Siroco de Azgher', 'Divina', 1, 'Evocação', 'padrão', 'curto', 'instantânea', '', 'Reflexos reduz à metade', '', 'Invocando a fúria do Deus-Sol, você cria uma breve e focada tempestade de areia, capaz de esfolar a carne dos ossos! Criaturas afetadas sofrem dano de corte conforme seu grau de proteção: 3d6 se estiverem sem armadura, 2d6 se estiverem com armadura leve e 1d6 se estiveren com armadura pesada.', '[{"cost":"+1 PM","effect":"aumenta o dano em +1d6.","isTrick":false},{"cost":"+1 PM","effect":"muda o tipo de dano para luz.","isTrick":false},{"cost":"+1 PM","effect":"muda o alcance para pessoal e o alvo para área (cone de 9m). Requer 2° círculo.","isTrick":false},{"cost":"+1 PM","effect":"(Apenas Devotos de Azgher): além do normal, criaturas que falhem na resistência ficam em chamas e sangrando.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Sono', 'Arcana', 1, 'Encantamento', 'padrão', 'curto', 'cena', '', 'Vontade parcial', '', 'Um cansaço místico recai sobre o alvo. Se falhar na resistência, ele fica inconsciente e caído ou, se estiver envolvido em combate ou outra situação perigosa, fica Exausto por 1 rodada, depois fatigado. Em ambos os casos, se passar, o alvo fica Fatigado por 1d4 rodadas.', '[{"cost":"+2 PM","effect":"alvos que falhem na resistência ficam exaustos por 1d4+1 rodadas, em vez de apenas 1.","isTrick":false},{"cost":"+2 PM","effect":"muda o alvo para criatura.","isTrick":false},{"cost":"+5 PM","effect":"afeta todos os alvos válidos a sua escolha dentro do alcance.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Sorriso da Fortuna', 'Divina', 1, 'Evocação', 'padrão', 'pessoal', '1 dia, até ser descarregada', '', '', '', 'Variantes desta magia, com diferentes nomes, são concedidas por Nimb, Hyninn, Sszzaas, Valkaria e até Thyatis. O objetivo, contudo, é sempre o mesmo: trapacear em jogos. Sorriso da Fortuna permite manipular os resultados de um jogo de azar. Quando fizer um teste de Jogatina (ou relacionado a algum jogo, a critério do mestre) você pode rolar dois dados e usar o melhor resultado. A magia é descarregada após você usar esse efeito três vezes.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Suporte Ambiental', 'Divina', 1, 'Abjuração', 'padrão', 'toque', '1 dia', '', '', '', 'Esta magia garante a sobrevivência em ambientes hostis. O alvo fica imune aos efeitos de calor e frio extremos, pode respirar na água se respirar ar (ou vice-versa) e não sufoca em fumaça densa.', '[{"cost":"+5 PM","effect":"muda o alcance para curto e o alvo para criaturas escolhidas.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Teia', 'Arcana', 1, 'Convocação', 'padrão', 'curto', 'cena', 'cubo com 6m de lado', 'Reflexos anula', '', 'Teia cria várias camadas de fibras entrelaçadas e pegajosas na área. Qualquer criatura na área que falhar na resistência fica Enredado. Uma vítima pode se libertar com uma ação padrão e um teste de Acrobacia ou Atletismo. A área ocupada por Teia é terreno difícil.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Toque Chocante', 'Arcana', 1, 'Evocação', 'padrão', 'toque', 'instantânea', '', 'Fortitude reduz à metade', '', 'Arcos elétricos envolvem sua mão, causando 2d8+2 pontos de dano de eletricidade. Se o alvo usa armadura de metal (ou carrega muito metal, a critério do mestre), sofre uma penalidade de –5 no teste de resistência.', '[{"cost":"+1 PM","effect":"aumenta o dano em 1d8+1.","isTrick":false},{"cost":"+2 PM","effect":"muda a resistências para nenhum. Como parte da execução da magia, você faz um ataque corpo a corpo contra o alvo. Se acertar, causa o dano do ataque e da magia.","isTrick":false},{"cost":"+2 PM","effect":"muda o alcance para pessoal e o alvo para área: esfera com 6m de raio. Você dispara raios pelas pontas dos dedos que afetam todas as criaturas na área.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Toque de Megalokk', 'Divina', 1, 'Transmutação', 'padrão', 'pessoal', 'cena', '', '', '', 'Criaturas de Allihanna seguem leis naturais. Monstros existem para violar essas leis. Após deformações horrendas, você se transforma em uma criatura do tipo monstro. Nessa forma, você recebe +5 em Intimidação, mas sofre –5 nas demais perícias baseadas em Carisma. Além disso, recebe uma arma natural de um tipo a sua escolha entre chifre, ferrão e mordida (dano 1d6, crítico x2, perfuração). Uma vez por rodada, quando usa a ação agredir para atacar com outra arma, pode gastar 1 PM para fazer um ataque corpo a corpo extra com essa arma natural.', '[{"cost":"+1 PM","effect":"a margem de ameaça de suas armas naturais aumenta em +1.","isTrick":false},{"cost":"+2 PM","effect":"o dano de suas armas naturais aumenta em um passo. Requer 3° círculo.","isTrick":false},{"cost":"+5 PM","effect":"(Apenas Devotos de Megalokk): além do normal, você recebe redução de dano 5.Requer 2º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Toque do Horizonte', 'Arcana', 1, 'Transmutação', 'padrão', 'toque', 'cena', '', '', '', 'A magia melhora a precisão da arma, aumentando seu alcance em um passo (de curto para médio e de médio para longo). Se o alcance da arma já é longo, ele é dobrado. Os efeitos desta magia contam como um bônus de encanto.', '[{"cost":"+1 PM","effect":"a arma ignora camuflagem leve e penalidades por cobertura leve.","isTrick":false},{"cost":"+1 PM","effect":"além do normal, a arma fornece +1 em testes de ataque e rolagens de dano feitos dentro do seu alcance original.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o bônus do aprimoramento acima em +1 (bônus máximo limitado pelo círculo máximo de magia que você pode lançar).","isTrick":false},{"cost":"+2 PM","effect":"a margem de ameaça da arma aumenta em +1. Requer 2° círculo.","isTrick":false},{"cost":"+5 PM","effect":"muda o alvo para uma arma de arremesso e a duração para sustentada. Em vez do normal, a arma recebe o benefício do encanto dançarina. Requer 3° círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Tranca Arcana', 'Arcana', 1, 'Abjuração', 'padrão', 'toque', 'permanente', '', '', '', 'Esta magia tranca uma porta ou outro item que possa ser aberto ou fechado (como um baú, caixa etc.), aumentando a CD de testes de Força ou Ladinagem para abri-lo em +10. Você pode abrir livremente sua própria tranca sem problemas.Componente material: chave de bronze no valor de T$ 25.', '[{"cost":"Truque","effect":"muda o alcance para curto. Em vez do normal, pode abrir ou fechar um objeto de tamanho Médio ou menor, como uma porta ou baú. Não afeta objetos trancados.","isTrick":true},{"cost":"+1 PM","effect":"muda o alcance para curto e a duração para instantânea. Em vez do normal, a magia abre portas, baús e janelas trancadas, presas, barradas ou protegidas por Tranca Arcana (o efeito é dissipado) a sua escolha. Ela também afrouxa grilhões e solta correntes.","isTrick":false},{"cost":"+5 PM","effect":"aumenta a CD para abrir o alvo em +5.","isTrick":false},{"cost":"+5 PM","effect":"muda o alvo para 1 objeto de qualquer tamanho, podendo afetar até mesmo os portões de um castelo. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Tranquilidade', 'Divina', 1, 'Encantamento', 'padrão', 'curto', 'cena', '', 'Vontade parcial', '', 'Você emana ondas de serenidade. Se falhar na resistência, o alvo tem sua atitude mudada para indiferente (veja a página 259) e não pode atacar ou realizar qualquer ação agressiva. Se passar, sofre –2 em testes de ataque. Qualquer ação hostil contra o alvo ou seus aliados dissipa a magia e faz ele retornar à atitude que tinha antes (ou pior, de acordo com o mestre).', '[{"cost":"+1 PM","effect":"muda o alvo para 1 criatura.","isTrick":false},{"cost":"+1 PM","effect":"aumenta o número de alvos em +1.","isTrick":false},{"cost":"+5 PM","effect":"muda o alcance para médio e o alvo para criaturas escolhidas. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Transmutar Objetos', 'Arcana', 1, 'Transmutação', 'padrão', 'toque', 'cena', '', '', '', 'A magia transforma matéria bruta para moldar um novo objeto. Você pode usar matéria-prima mundana para criar um objeto de tamanho Pequeno ou menor e preço máximo de T$ 25, como um balde ou uma espada. O objeto reverte à matéria-prima no final da cena, ou se for tocado por um objeto feito de chumbo. Esta magia não pode ser usada para criar objetos consumíveis, como alimentos ou itens alquímicos, nem objetos com mecanismos complexos, como bestas ou armas de fogo.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Visão Mística', 'Universal', 1, 'Adivinhação', 'padrão', 'pessoal', 'cena', '', '', '', 'Seus olhos brilham com uma luz azul e passam a enxergar auras mágicas. Este efeito é similar ao uso de Misticismo para detectar magia, mas você detecta todas as auras mágicas em alcance médio e recebe todas as informações sobre elas sem gastar ações. Além disso, você pode gastar uma ação de movimento para descobrir se uma criatura que possa perceber em alcance médio é capaz de lançar magias e qual a aura gerada pelas magias de círculo mais alto que ela pode lançar.', '[{"cost":"+1 PM","effect":"recebe visão no escuro.","isTrick":false},{"cost":"+2 PM","effect":"muda a duração para 1 dia.","isTrick":false},{"cost":"+2 PM","effect":"também pode enxergar objetos e criaturas invisíveis. Eles aparecem como formas translúcidas.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Vitalidade Fantasma', 'Arcana', 1, 'Necromancia', 'padrão', 'pessoal', 'instantânea', '', '', '', 'Você suga energia vital da terra, recebendo 2d10 pontos de vida temporários. Os PV temporários desaparecem ao final da cena.', '[{"cost":"+2 PM","effect":"aumenta os PV temporários recebidos em +1d10. Caso a magia cause dano, em vez disso aumenta o dano causado em +1d10.","isTrick":false},{"cost":"+5 PM","effect":"muda o alvo para área: esfera com 6m de raio centrada em você e a resistência para Fortitude reduz à metade. Em vez do normal, você suga energia das criaturas vivas na área, causando 1d10 pontos de dano de trevas e recebendo PV temporários iguais ao dano total causado. Os PV temporários desaparecem ao final da cena. Requer 2º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Voz da Razão', 'Divina', 1, 'Encantamento', 'padrão', 'pessoal', 'cena', '', '', '', 'Iluminada por Tanna-Toh, sua mente transborda de argumentos e informações. Você recebe +5 em Conhecimento, Diplomacia e Intimidação.', '[{"cost":"+2 PM","effect":"muda o bônus para +10. Requer 2º círculo.","isTrick":false},{"cost":"+2 PM","effect":"(Apenas Devotos de Tanna-Toh): além do normal, você recebe +5 em Intuição e em testes de Investigação para interrogar.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Área Escorregadia', 'Arcana', 1, 'Convocação', 'padrão', 'curto', 'cena', 'Quadrado de 3m ou 1 objeto', 'Reflexos (veja texto)', '', 'Esta magia recobre uma superfície com uma substância gordurosa e escorregadia. Criaturas na área devem passar na resistência para não cair. Nas rodadas seguintes, criaturas que tentem movimentar-se pela área devem fazer testes de Acrobacia para equilíbrio (CD 10).
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Aliado Animal', 'Divina', 2, 'Encantamento', 'padrão', 'curto', '0 dia', '', '', '', 'Você cria um vínculo mental com um animal prestativo em relação a você. O Aliado Animal obedece a você no melhor de suas capacidades, mesmo que isso arrisque a vida dele. Ele funciona como um parceiro veterano, de um tipo a sua escolha entre ajudante, combatente, fortão, guardião, montaria ou perseguidor.', '[{"cost":"+1 PM","effect":"muda o alvo para 1 animal Minúsculo e a duração para 1 semana. Em vez do normal, o animal se desloca no melhor de suas capacidades até um local designado por você — em geral, para levar um item, carta ou similar. Quando o animal chega ao destino, fica esperando até o fim da magia, permitindo apenas que uma ou mais criaturas escolhidas por você se aproximem e peguem o que ele estiver carregando.","isTrick":false},{"cost":"+7 PM","effect":"muda o parceiro para mestre. Requer 3º círculo.","isTrick":false},{"cost":"+12 PM","effect":"muda o alvo para 2 animais prestativos. Cada animal funciona como um parceiro de um tipo diferente, e você pode receber a ajuda de ambos (mas ainda precisa seguir o limite de parceiros de acordo com o seu nível de personagem). Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Alterar Tamanho', 'Arcana', 2, 'Transmutação', 'padrão', 'curto', '1 dia', '', '', '', 'Esta magia aumenta ou diminui o tamanho de um item mundano em até três categorias (um objeto Enorme vira Pequeno, por exemplo). Você também pode mudar a consistência do item, deixando-o rígido como pedra ou flexível como seda (isso não altera sua RD ou PV, apenas suas propriedades físicas). Se lançar a magia num objeto de uma criatura involuntária, ela pode fazer um teste de Vontade para anulá-la.', '[{"cost":"+1 PM","effect":"aumenta o número de alvos em +1.","isTrick":false},{"cost":"+2 PM","effect":"muda o alcance para toque e o alvo para 1 criatura. Em vez do normal, o alvo aumenta uma categoria de tamanho (seu equipamento se ajusta ao novo tamanho). O alvo também recebe Força +2. Um alvo involuntário pode fazer um teste de Fortitude para negar o efeito.","isTrick":false},{"cost":"+3 PM","effect":"muda o alcance para toque e o alvo para 1 criatura. Em vez do normal, o alvo diminui uma categoria de tamanho (seu equipamento se ajusta ao novo tamanho). O alvo também recebe Destreza +2. Um alvo involuntário pode fazer um teste de Fortitude para negar o efeito. Requer 3º círculo.","isTrick":false},{"cost":"+7 PM","effect":"muda o alcance para toque, o alvo para 1 criatura, a duração para permanente e a resistência para Fortitude anula. Em vez do normal, se falhar na resistência o alvo e seu equipamento têm seu tamanho mudado para Minúsculo. O alvo também tem seu valor de Força reduzido a 1 e suas formas de deslocamento reduzidas a 3m. Requer 4o círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Amarras Etéreas', 'Arcana', 2, 'Convocação', 'padrão', 'médio', 'cena', '', 'Reflexos anula', '', 'Três laços de energia surgem e se enroscam no alvo, deixando-o agarrado. A vítima pode tentar se livrar, gastando uma ação padrão para fazer um teste de Atletismo (CD igual à da magia). Se passar, destrói um laço, mais um laço adicional para cada 5 pontos pelos quais superou a CD. Os laços também podem ser atacados e destruídos: cada um tem Defesa 10, 10 PV, RD 5 e imunidade a dano mágico. Se todos os laços forem destruídos, a magia é dissipada. Por serem feitos de energia, os laços afetam criaturas incorpóreas.', '[{"cost":"+2 PM","effect":"aumenta o número de alvos em +1.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o número de laços em um alvo a sua escolha em +1. (bônus máximo limitado pelo círculo máximo de magia que você pode lançar)","isTrick":false},{"cost":"+3 PM","effect":"em vez do normal, cada laço é destruído automaticamente com um único ataque bem-sucedido; porém, cada laço destruído libera um choque de energia que causa 1d8+1 pontos de dano de essência na criatura amarrada. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Aparência Perfeita', 'Arcana', 2, 'Ilusão', 'padrão', 'pessoal', 'cena', '', '', '', 'Esta magia lhe concede um rosto idealizado, porte físico garboso, voz melodiosa e olhar sedutor. Enquanto a magia estiver ativa, seu Carisma torna-se 5 (ou recebe um bônus de +2, caso seja 5 ou maior) e você recebe +5 nos testes de Diplomacia e Enganação. Quando a magia acaba, quaisquer observadores percebem a mudança e tendem a suspeitar de você. Da mesma maneira, pessoas que o viram sob o efeito da magia sentirão que “algo está errado” ao vê-lo em condições normais. Quando a cena acabar, você pode gastar os PM da magia novamente como uma ação livre para mantê-la ativa. Este efeito não fornece PV ou PM adicionais.', '[{"cost":"+1 PM","effect":"muda o alcance para toque e o alvo para 1 humanoide","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Augúrio', 'Divina', 2, 'Adivinhação', 'completa', 'pessoal', 'instantânea', '', '', '', 'Esta magia diz se uma ação que você tomará em breve — no máximo uma hora no futuro — trará resultados bons ou ruins. O mestre rola 1d6 em segredo; com um resultado de 2 a 6, a magia funciona e você recebe uma das seguintes respostas: “felicidade” (a ação trará bons resultados); “miséria” (a ação trará maus resultados); “felicidade e miséria” (para ambos) ou “nada” (para ações que não trarão resultados bons ou ruins).
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Aura de Morte', 'Arcana', 2, 'Necromancia', 'padrão', 'pessoal', 'cena', 'esfera com 6m de raio', '', '', 'Uma aura de frio necrótico emana a partir do seu corpo, alimentando-se de sua própria força vital. Quando você lança a magia, e no início de cada um dos seus turnos, você perde 1d6 pontos de vida e cada outra criatura na área perde 2d8 pontos de vida.', '[{"cost":"+1 PM","effect":"aumenta a perda de vida para outras criaturas em +1d8 (número de dados de perda de vida máximos limitados pelo círculo máximo de magia que você pode lançar). Requer 3º círculo.","isTrick":false},{"cost":"+3 PM","effect":"adiciona resistência (Fortitude parcial). Além do normal, outras criaturas que percam pontos de vida pela magia devem fazer um teste de Fortitude. Se falharem, não podem recuperar PV por 1 rodada. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Bola de Fogo', 'Arcana', 2, 'Evocação', 'padrão', 'médio', 'instantânea', 'esfera com 6m de raio', 'Reflexos reduz à metade', '', 'Esta famosa magia de ataque cria uma poderosa explosão, causando 6d6 pontos de dano de fogo em todas as criaturas e objetos livres na área.', '[{"cost":"+2 PM","effect":"aumenta o dano em +2d6.","isTrick":false},{"cost":"+2 PM","effect":"muda a área para efeito de esfera flamejante com tamanho Médio e a duração para cena. Em vez do normal, cria uma esfera flamejante com 1,5m de diâmetro que causa 3d6 pontos de dano a qualquer criatura no mesmo espaço. Você pode gastar uma ação de movimento para fazer a esfera voar 9m em qualquer direção. Ela é imune a dano, mas pode ser apagada com água. Uma criatura só pode sofrer dano da esfera uma vez por rodada.","isTrick":false},{"cost":"+3 PM","effect":"muda a duração para 1 dia ou até ser descarregada. Em vez do normal, você cria uma pequena pedra flamejante, que pode detonar como uma reação, descarregando a magia. A pedra pode ser usada como uma arma de arremesso com alcance curto. Uma vez detonada, causa o dano da magia numa área de esfera de 6m com raio.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Campo de Força', 'Arcana', 2, 'Abjuração', 'padrão', 'pessoal', 'cena', '', '', '', 'Esta magia cria uma película protetora sobre você. Você recebe 30 pontos de vida temporários.', '[{"cost":"+1 PM","effect":"muda a execução para reação e a duração para instantânea. Em vez do normal, você recebe redução 30 contra o próximo dano que sofrer.","isTrick":false},{"cost":"+3 PM","effect":"muda os PV temporários ou a RD para 50. Requer 3º círculo.","isTrick":false},{"cost":"+7 PM","effect":"muda o alcance para curto, o alvo para outra criatura ou objeto Enorme ou menor e a duração para sustentada. Em vez do normal, cria uma esfera imóvel e tremeluzente ao redor do alvo. Nenhuma criatura, objeto ou efeito de dano pode passar pela esfera, embora criaturas possam respirar normalmente. Criaturas na área podem fazer um teste de Reflexos para evitar serem aprisionadas e sempre que você se concentrar. Requer 4º círculo.","isTrick":false},{"cost":"+7 PM","effect":"muda os PV temporários ou a RD para 70. Requer 4º círculo.","isTrick":false},{"cost":"+9 PM","effect":"como o aprimoramento acima, mas tudo dentro da esfera fica praticamente sem peso. Uma vez por rodada, você pode gastar uma ação livre para flutuar a esfera e seu conteúdo 9m em uma direção. Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Camuflagem Ilusória', 'Arcana', 2, 'Ilusão', 'padrão', 'toque', 'cena', '', '', '', 'O alvo fica com sua imagem nublada, como se vista através de um líquido, recebendo os efeitos de camuflagem leve.', '[{"cost":"+3 PM","effect":"muda a duração para sustentada. A imagem do alvo fica mais distorcida, aumentando a chance de falha da camuflagem leve para 50%.","isTrick":false},{"cost":"+7 PM","effect":"muda o alcance para curto e o alvo para criaturas escolhidas. Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Condição', 'Divina', 2, 'Adivinhação', 'padrão', 'curto', 'cena', '', '', '', 'Pela duração da magia, você sabe a posição e status (PV atuais, se estão sob efeito de magia...) dos alvos. Depois de lançada, a distância entre você e os alvos não importa — a magia só deixa de detectar um alvo se ele morrer ou for para outro plano.', '[{"cost":"+1 PM","effect":"aumenta o número de alvos em +1.","isTrick":false},{"cost":"+1 PM","effect":"aumenta a duração para 1 dia.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Conjurar Armadilha', 'Arcana', 2, 'Transmutação', 'completa', 'curto', 'permanente', '', '', '', 'Esta magia modifica o terreno e/ou a arquitetura de um ponto no alcance, transformando-o em uma armadilha de caçador (Tormenta20, p. 50) a sua escolha. A armadilha criada segue as mesmas regras de armadilhas, mas a CD dos testes para encontrá-la e resistir a ela é a da magia.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Conjurar Mortos-Vivos', 'Universal', 2, 'Necromancia', 'completa', 'curto', 'sustentada', '', '', '', 'Você conjura seis esqueletos capangas de tamanho Médio feitos de energia negativa em espaços desocupados dentro do alcance. Você pode gastar uma ação de movimento para fazer os mortos-vivos andarem (eles têm deslocamento 9m) ou uma ação padrão para fazê-los causar dano a criaturas adjacentes (1d6+2 pontos de dano de trevas cada). Os esqueletos têm For 2, Des 2, Defesa 18 e todos os outros atributos nulos; eles têm 1 PV e falham automaticamente em qualquer teste de resistência ou oposto, mas são imunes a atordoamento, cansaço, dano não letal, doença, encantamento, fadiga, frio, ilusão, paralisia, sono e veneno. Eles desaparecem quando são reduzidos a 0 PV ou no fim da cena. Os mortos- -vivos não agem sem receber uma ordem. Usos criativos para capangas fora de combate ficam a critério do mestre.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Controlar Fogo', 'Divina', 2, 'Evocação', 'padrão', 'curto', 'cena', '', '', '', 'Você pode criar, moldar, mover ou extinguir chamas e emanações de calor. Ao lançar a magia, escolha um dos efeitos.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Controlar Madeira', 'Divina', 2, 'Transmutação', 'padrão', 'médio', 'cena', '', '', '', 'Você molda, retorce, altera ou repele madeira. Se lançar esta magia num objeto de uma criatura involuntária, ela tem direito a um teste de Vontade para anulá-la. Ao lançar a magia, escolha.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Couraça de Allihanna', 'Divina', 2, 'Abjuração', 'padrão', 'toque', 'cena', '', '', '', 'Lisandra de Galrasia foi a primeira a manifestar uma armadura fibrosa, mas hoje outros podem fazer o mesmo. Esta magia transforma o alvo em uma couraça arbórea. Se for uma armadura, seu bônus na Defesa aumenta em +2 e se for um vestuário, passa a fornecer +2 na Defesa (não cumulativo com armadura). Os efeitos desta magia contam como um bônus de encanto e ela só pode ser lançada em terrenos naturais. Dahllan recebem 1 PM para usar em aprimoramentos ao lançá-la.', '[{"cost":"+1 PM","effect":"aumenta a Defesa em +1 (bônus máximo limitado pelo círculo máximo de magia que você pode lançar).","isTrick":false},{"cost":"+2 PM","effect":"além do normal, suas magias de evocação e transmutação custam –1 PM.","isTrick":false},{"cost":"+2 PM","effect":"o alvo é recoberto por folhas e galhos. Você recebe +5 em testes de Furtividade e pode se esconder mesmo sem camuflagem ou cobertura disponível.","isTrick":false},{"cost":"+2 PM","effect":"além do normal, o alvo fornece o mesmo bônus em testes de resistência. Requer 3° círculo.","isTrick":false},{"cost":"+3 PM","effect":"além do normal, o alvo é recoberto esporos de cogumelo. Quando uma criatura faz um ataque corpo a corpo contra você, ela deve fazer um teste de Fortitude (CD da magia). Se falhar, fica paralisada por 1 rodada (apenas uma vez por cena) e lenta. Se passar, fica lenta por 1 rodada. Requer 3° círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Crânio Voador de Vladislav', 'Arcana', 2, 'Necromancia', 'padrão', 'médio', 'instantânea', '', 'Fortitude parcial', '', 'Esta magia cria um crânio envolto em energia negativa. Quando atinge o alvo, causa 4d8+4 pontos de dano de trevas e se desfaz emitindo um som horrendo, deixando abalado o alvo e todos os inimigos num raio de 3m dele (criaturas já abaladas ficam apavoradas por 1d4 rodadas). Passar no teste de resistência diminui o dano à metade e evita a condição (as demais criaturas na área também tem direito ao teste de resistência, para evitar a condição).
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Círculo da Justiça', 'Divina', 2, 'Abjuração', 'completa', 'curto', '1 dia', 'esfera com 9m de raio;', 'Vontade parcial', '', 'Também conhecida como Lágrimas do Deus da Trapaça, esta magia é usada em tribunais e para proteger áreas sensíveis. Criaturas na área sofrem –10 em testes de Acrobacia, Enganação, Furtividade e Ladinagem e não podem mentir deliberadamente — mas podem tentar evitar perguntas que normalmente responderiam com uma mentira (sendo evasivas ou cometendo omissões, por exemplo). Uma criatura que passe na resistência tem as penalidades reduzidas para –5 e pode mentir.', '[{"cost":"+1 PM","effect":"muda a execução para ação padrão, o alcance para pessoal, o alvo para você, a duração para cena e a resistência para nenhuma. Em vez do normal, qualquer criatura ou objeto invisível em alcance curto se torna visível. Isso não dissipa o efeito mágico; se sair do seu alcance, a criatura ou objeto voltam a ficar invisíveis.","isTrick":false},{"cost":"+3 PM","effect":"muda a penalidade nas perícias para –10 (se passar na resistência) e –20 (se falhar). Requer 4º círculo.","isTrick":false},{"cost":"+7 PM","effect":"muda a duração para permanente e adiciona componente material (balança de prata no valor de T$ 5.000).","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Desafio Corajoso', 'Arcana', 2, 'Encantamento', 'padrão', 'curto', 'sustentada', '', 'Vontade anula', '', 'Esta magia cria uma aura de influência de 9m ao redor do alvo. Outras criaturas que iniciarem seus turnos dentro da aura devem fazer um teste de Vontade. Se falharem, quaisquer ações hostis nesse turno devem ser feitas contra o alvo.', '[{"cost":"+3 PM","effect":"muda o alvo para 1 criatura ou objeto. Requer 4° círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Desespero Esmagador', 'Arcana', 2, 'Encantamento', 'padrão', 'pessoal', 'cena', 'Cone de 6m', 'Vontade parcial', '', 'Humanoides na área são acometidos de grande tristeza, adquirindo as condições Fraco e Frustrado. Se passarem na resistência, adquirem essas condições por uma rodada.', '[{"cost":"+2 PM","effect":"em vez do normal, as condições adquiridas são debilitado e esmorecido.","isTrick":false},{"cost":"+3 PM","effect":"em vez do normal, afeta qualquer tipo de criatura.","isTrick":false},{"cost":"+3 PM","effect":"além do normal, criaturas que falhem na resistência ficam aos prantos (em termos de jogo, adquirem a condição pasmo) por 1 rodada (apenas uma vez por cena). Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Desfazer Engenhoca', 'Universal', 2, 'Abjuração', 'padrão', 'médio', 'instantânea', 'esfera com 3m de raio', '', '', 'Você desfaz os efeitos ativos de engenhocas, como se sua duração tivesse acabado (efeitos instantâneos não podem ser dissipados). Se lançar esta magia em uma criatura ou área, faça um teste de Misticismo; você dissipa os efeitos ativos de engenhocas com CD igual ou menor que o resultado do teste. Lançada diretamente contra uma engenhoca, aumenta a CD para ativá-la em +10 até o fim da cena. Lançada contra um construto, o teste é oposto à Vontade do alvo. Se você vencer, além do normal, o construto fica fraco e vulnerável (mesmo que seja imune a essas condições). A critério do mestre, esta magia pode afetar outras habilidades e itens similares a engenhocas.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Dissipar Magia', 'Universal', 2, 'Abjuração', 'padrão', 'médio', 'instantânea', 'ou esfera com 3m de raio', '', '', 'Você dissipa outras magias que estejam ativas, como se sua duração tivesse acabado. Note que efeitos de magias instantâneas não podem ser dissipados (não se pode dissipar uma Bola de Fogo ou Relâmpago depois que já causaram dano...). Se lançar essa magia em uma criatura ou área, faça um teste de Misticismo; você dissipa as magias com CD igual ou menor que o resultado do teste. Se lançada contra um item mágico, o transforma em um item mundano por 1d6 rodadas (Vontade anula).', '[{"cost":"+12 PM","effect":"muda a área para esfera com 9m de raio. Em vez do normal, cria um efeito de disjunção. Todas as magias na área são automaticamente dissipadas e todos os itens mágicos na área, exceto aqueles que você estiver carregando, viram itens mundanos por uma cena (com direito a um teste de resistência para evitar esse efeito). Requer 5º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Emular Magia', 'Universal', 2, 'Evocação', 'movimento', 'pessoal', 'cena', '', '', '', 'Pela duração de Emular Magia, você pode lançar uma única magia que tenha visto ser lançada em alcance curto desde sua última rodada. A magia deve ser de um tipo (arcana ou divina) e de um círculo a que você tenha acesso.', '[{"cost":"+1 PM","effect":"a magia emulada pode ser de qualquer tipo, arcana ou divina.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Enxame de Pestes', 'Divina', 2, 'Convocação', 'completa', 'médio', 'sustentada', '', 'Fortitude reduz à metade', '', 'Você conjura um enxame de criaturas a sua escolha, como besouros, gafanhotos, ratos, morcegos ou serpentes. O enxame pode passar pelo espaço de outras criaturas e não impede que outras criaturas entrem no espaço dele. No final de seus turnos, o enxame causa 2d12 pontos de dano de corte a qualquer criatura em seu espaço (Fortitude reduz à metade). Você pode gastar uma ação de movimento para mover o enxame 12m.', '[{"cost":"+2 PM","effect":"aumenta o dano em +1d12.","isTrick":false},{"cost":"+3 PM","effect":"muda a resistência para Reflexos reduz à metade e o enxame para criaturas maiores, como gatos, guaxinins, compsognatos ou kobolds. Ele causa 3d12 pontos de dano (a sua escolha entre corte, impacto ou perfuração). O resto da magia segue normal.","isTrick":false},{"cost":"+5 PM","effect":"aumenta o número de enxames em +1. Eles não podem ocupar o mesmo espaço. Requer 3º círculo.","isTrick":false},{"cost":"+7 PM","effect":"muda a resistência para Reflexos reduz à metade e o enxame para criaturas elementais. Ele causa 5d12 pontos do dano (a sua escolha entre ácido, eletricidade, fogo ou frio). O resto da magia segue normal. Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Esculpir Sons', 'Arcana', 2, 'Ilusão', 'padrão', 'médio', 'cena', '', 'Vontade anula', '', 'Esta magia altera os sons emitidos pelo alvo. Ela não é capaz de criar sons, mas pode omiti-los (como fazer uma carroça ficar silenciosa) ou transformá-los (como fazer uma pessoa ficar com voz de passarinho). Você não pode criar sons que não conhece (não pode fazer uma criatura falar num idioma que não conheça). Uma vez que escolha a alteração, ela não pode ser mudada. Um conjurador que tenha a voz modificada drasticamente não poderá lançar magias.', '[{"cost":"+2 PM","effect":"aumenta o número de alvos em +1. Todas as criaturas e objetos devem ser afetadas da mesma forma.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Flecha Ácida', 'Arcana', 2, 'Evocação', 'padrão', 'médio', 'instantânea', '', 'Reflexos parcial', '', 'Você dispara um projétil que causa 4d6 pontos de dano de ácido. Se falhar no teste de resistência, o alvo também fica coberto por um muco corrosivo, sofrendo mais 2d6 de dano de ácido no início de seus dois próximos turnos. Se lançada contra um objeto que não esteja em posse de uma criatura a magia causa dano dobrado e ignora a RD do objeto.', '[{"cost":"+1 PM","effect":"além do normal, se o alvo coberto pelo muco ácido estiver usando armadura ou escudo, o item é corroído. Isso reduz o bônus na Defesa do item em 1 ponto permanentemente. O item pode ser consertado, restaurando seu bônus (veja Ofício, na página 121).","isTrick":false},{"cost":"+2 PM","effect":"aumenta a redução na Defesa em +1.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o dano inicial e o dano por rodada em +1d6.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Físico Divino', 'Divina', 2, 'Transmutação', 'padrão', 'toque', 'cena', '', '', '', 'Você fortalece o corpo do alvo. Ele recebe +2 em Força, Destreza ou Constituição, a sua escolha. Esse aumento não oferece PV ou PM adicionais.', '[{"cost":"+3 PM","effect":"muda o alcance para curto e o alvo para criaturas escolhidas.","isTrick":false},{"cost":"+3 PM","effect":"em vez do normal, o alvo recebe +2 nos três atributos físicos. Requer 3º círculo.","isTrick":false},{"cost":"+7 PM","effect":"em vez do normal, o alvo recebe +4 no atributo escolhido. Requer 4º círculo.","isTrick":false},{"cost":"+12 PM","effect":"em vez do normal, o alvo recebe +4 nos três atributos físicos. Requer 5º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Globo da Verdade de Gwen', 'Divina', 2, 'Adivinhação', 'padrão', 'curto', 'cena', '', '', '', 'Cria um globo flutuante e intangível, com 50cm de diâmetro. O globo mostra uma cena vista até uma semana atrás por você ou por uma criatura que você toque ao lançar a magia (mediante uma pergunta; a criatura pode fazer um teste de Vontade para anular o efeito), permitindo que outras pessoas a vejam.', '[{"cost":"+1 PM","effect":"o globo mostra uma cena vista até um mês atrás.","isTrick":false},{"cost":"+2 PM","effect":"o globo mostra uma cena vista até um ano atrás.","isTrick":false},{"cost":"+2 PM","effect":"ao lançar a magia, você pode tocar um cadáver. O globo mostra a última cena vista por essa criatura.","isTrick":false},{"cost":"+4 PM","effect":"muda o alcance para longo e o efeito para 10 globos. Todos mostram a mesma cena.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Invisibilidade', 'Arcana', 2, 'Ilusão', 'livre', 'pessoal', '1 rodada', '', '', '', 'O alvo fica invisível (incluindo seu equipamento). Um personagem invisível recebe camuflagem total, +10 em testes de Furtividade contra ouvir e criaturas que não possam percebê-lo ficam desprevenidas contra seus ataques.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Invocar Fagulha Elemental', 'Arcana', 2, 'Convocação', 'completa', 'curto', 'sustentada', '', '', '', 'Você transforma uma porção de um elemento inerte em uma criatura elemental Pequena do tipo do elemento alvo. Por exemplo, lançar esta magia em um copo de água cria um elemental da água. Você pode criar elementais do ar, da água, do fogo e da terra com esta magia. O elemental obedece a todos os seus comandos e funciona como um familiar comum (veja Familiares, em Tormenta20, p. 38) ou elemental (veja Elementais). O elemental auxilia apenas você e não conta em seu limite de parceiros.', '[{"cost":"+1 PM","effect":"além do normal, o elemental fornece redução 10 contra o dano correspondente a seu tipo.","isTrick":false},{"cost":"+2 PM","effect":"em vez do normal, o elemental recebe a habilidade de dois familiares, um comum e um elemental.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Ligação Telepática', 'Arcana', 2, 'Adivinhação', 'padrão', 'toque', '1 dia', '', '', '', 'Você cria um elo mental entre duas criaturas com Inteligência -3 ou maior (você pode ser uma delas). As criaturas podem se comunicar independente de idioma ou distância, mas não em mundos diferentes.', '[{"cost":"+2 PM","effect":"aumenta o número de alvos em +1.","isTrick":false},{"cost":"+3 PM","effect":"muda o alvo para 1 criatura. Em vez do normal, você cria um elo mental que permite que você veja e ouça pelos sentidos da criatura, se gastar uma ação de movimento. Uma criatura involuntária pode fazer um teste de Vontade para suprimir a magia por uma hora. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Localização', 'Arcana', 2, 'Adivinhação', 'padrão', 'pessoal', 'cena', 'esfera com 90m de raio', '', '', 'Esta magia pode encontrar uma criatura ou objeto a sua escolha. Você pode pensar em termos gerais (“um elfo”, “algo de metal”) ou específicos (“Gwen, a elfa”, “uma espada longa”). A magia indica a direção e distância da criatura ou objeto mais próximo desse tipo, caso esteja ao alcance. Você pode movimentar-se para continuar procurando. Procurar algo muito específico (“a espada longa encantada do Barão Rulyn”) exige que você tenha em mente uma imagem precisa do objeto; caso a imagem não seja muito próxima da verdade, a magia falha, mas você gasta os PM mesmo assim. Esta magia pode ser bloqueada por uma fina camada de chumbo.', '[{"cost":"Truque","effect":"muda a área para alvo você. Em vez do normal, você sabe onde fica o norte e recebe +5 em testes de Sobrevivência para se orientar.","isTrick":true},{"cost":"+5 PM","effect":"aumenta a área em um fator de 10 (90m para 900m, 900m para 9km e assim por diante).","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Mapear', 'Arcana', 2, 'Adivinhação', 'padrão', 'toque', 'cena', '', '', '', 'Uma fagulha percorre a superfície afetada, queimando-a enquanto esboça um mapa da região onde o conjurador está. Se você conhece o lugar, o mapa será completo. Caso contrário, apresentará apenas um esboço geral, além de um ponto de referência (para possibilitar localização) e um lugar de interesse, ambos definidos pelo mestre. A região representada no mapa tem tamanho máximo de um quadrado de 10km de lado. Caso você esteja dentro de uma construção, o mapa mostrará o andar no qual você se encontra.', '[{"cost":"+3 PM","effect":"muda o alvo para 1 criatura e a duração para 1 hora. Em vez do normal, a criatura tocada descobre o caminho mais direto para entrar ou sair de um lugar. Assim, a magia pode ser usada para descobrir a rota até o relicário de uma catedral ou a saída mais próxima de uma masmorra (mas não para encontrar a localização de uma criatura ou objeto; a magia funciona apenas em relação a lugares). Caso a criatura demore mais de uma hora para percorrer o caminho, o conhecimento se perde.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Máquina de Combate', 'Arcana', 2, 'Transmutação', 'padrão', 'toque', 'cena', '', '', '', 'Esta magia energiza a fonte de energia de um golem ou outro construto, sobrecarregando-a temporariamente. O alvo recebe +5 em Atletismo e Luta, mas perde 1d4 pontos de vida no fim de cada turno em que executar uma ação padrão.', '[{"cost":"+2 PM","effect":"além do normal, os ataques corpo a corpo do alvo causam +1d6 pontos de dano.","isTrick":false},{"cost":"+2 PM","effect":"além do normal, o alvo recebe +2 na Defesa.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o bônus na Defesa em +1.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Marca da Obediência', 'Universal', 2, 'Encantamento', 'padrão', 'toque', 'cena', '', 'Vontade anula', '', 'Você toca uma criatura, gravando uma marca mística no corpo dela enquanto profere uma ordem, como “não ataque a mim ou meus aliados”, “siga-me” ou “não saia desta sala”. A criatura deve seguir essa ordem, gastando todas as ações de seu turno para isso. A ordem não pode ser genérica demais (como “ajude-me”, por exemplo), nem forçar o alvo a atos suicidas. A cada rodada, o alvo pode fazer um teste de Vontade. Se passar, a magia é dissipada.', '[{"cost":"+3 PM","effect":"muda a duração para 1 dia. Se não estiver em combate, a criatura só pode fazer o teste de Vontade a cada hora. Requer 3º círculo.","isTrick":false},{"cost":"+3 PM","effect":"sempre que o alvo fizer o teste de Vontade e falhar, a marca causa 3d6 pontos de dano psíquico. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Mente Divina', 'Divina', 2, 'Adivinhação', 'padrão', 'toque', 'cena', '', '', '', 'Você fortalece a mente do alvo. Ele recebe +2 em Inteligência, Sabedoria ou Carisma, a sua escolha. Esse aumento não oferece PV, PM ou perícias adicionais.', '[{"cost":"+3 PM","effect":"em vez do normal, o alvo recebe +2 nos três atributos mentais. Requer 3º círculo.","isTrick":false},{"cost":"+3 PM","effect":"muda o alcance para curto e o alvo para criaturas escolhidas.","isTrick":false},{"cost":"+7 PM","effect":"em vez do normal, o alvo recebe +4 no atributo escolhido. Requer 4º círculo.","isTrick":false},{"cost":"+12 PM","effect":"em vez do normal, o alvo recebe +4 nos três atributos mentais. Requer 5º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Metamorfose', 'Arcana', 2, 'Transmutação', 'padrão', 'pessoal', 'cena', '', '', '', 'Você muda sua aparência e forma — incluindo seu equipamento — para qualquer outra criatura, existente ou imaginada. Independentemente da forma escolhida, você recebe +20 em testes de Enganação para disfarce. Características não mencionadas não mudam.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Miasma Mefítico', 'Divina', 2, 'Necromancia', 'padrão', 'médio', 'instantânea', 'nuvem com 6m de raio', 'Fortitude (veja texto)', '', 'A área é coberta por emanações letais. Criaturas na área sofrem 5d6 pontos de dano de ácido e ficam Enjoado por 1 rodada. Se passarem na resistência, sofrem metade do dano e não ficam enjoadas.', '[{"cost":"Truque","effect":"muda o alcance para toque, a área para alvo (1 criatura com 0 PV ou menos), a duração para instantânea e a resistência para Fortitude anula. e adiciona componente material (pó de ônix no valor de T$ 10). Em vez do normal, você canaliza o Miasma contra uma vítima. Se falhar na resistência, ela morre e você recebe +2 na CD de suas magias por 1 dia. Se passar, fica imune a este truque por um dia.","isTrick":true},{"cost":"+2 PM","effect":"aumenta o dano em +1d6.","isTrick":false},{"cost":"+3 PM","effect":"muda o tipo do dano para trevas.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Momento de Tormenta', 'Universal', 2, 'Convocação', 'completa', 'pessoal', 'sustentada', 'cubo de 30m', 'veja texto', '', 'Uma nuvem rubra surge acima do conjurador. Uma vez por turno, você pode gastar uma ação de movimento para fazer a nuvem manifestar um dos fenômenos a seguir.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Montaria Arcana', 'Arcana', 2, 'Convocação', 'padrão', 'curto', '1 dia', '', '', '', 'Esta magia convoca um parceiro cavalo (ou pônei) de guerra veterano. Sua aparência é de um animal negro com crina e cauda cinzentas e cascos feitos de fumaça, mas você pode mudá-la se quiser. Além dos benefícios normais, a Montaria Arcana pode atravessar terreno difícil sem redução em seu deslocamento. Você pode usar Misticismo no lugar de Cavalgar para efeitos desta montaria (incluindo ser considerado treinado).', '[{"cost":"+1 PM","effect":"além do normal, criaturas do tipo animal em alcance curto da montaria devem fazer um teste de Vontade. Se passarem, ficam abaladas pela cena; se falharem, ficam apavoradas por 1d4 rodadas, depois abaladas pela cena.","isTrick":false},{"cost":"+3 PM","effect":"muda a duração para permanente e adiciona penalidade de -3 PM.","isTrick":false},{"cost":"+3 PM","effect":"aumenta o tamanho da montaria em uma categoria. Isso também aumenta o número de criaturas que ela pode carregar — duas para uma criatura Enorme, seis para Colossal. Uma única criatura controla a montaria; as outras apenas são deslocadas.","isTrick":false},{"cost":"+3 PM","effect":"muda o nível do aliado para mestre. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Oração', 'Divina', 2, 'Encantamento', 'padrão', 'curto', 'sustentada', '', '', '', 'Você e todos os seus aliados no alcance recebem +2 em testes de perícia e rolagens de dano, e todos os seus inimigos no alcance sofrem –2 em testes de perícia e rolagens de dano. Esse efeito é cumulativo com outras magias.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Piscar', 'Arcana', 2, 'Transmutação', 'padrão', 'pessoal', 'cena', '', '', '', 'Pela duração da magia, você fica “piscando” entre o Plano material e o etéreo. Para quem o observa, é como se você ficasse visível e invisível várias vezes por segundo.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Poção Explosiva', 'Arcana', 2, 'Transmutação', 'padrão', 'curto', 'cena', '', '', '', 'Esta magia transforma o conteúdo de uma poção em uma substância volátil e explosiva. Quando é usada, em vez de ter seu efeito normal, a poção causa 2d6 pontos de dano de essência por círculo da magia que ela continha (outras características da magia, como alvos, área e testes de resistência, se mantêm). Se a poção for ingerida, ela causa dano máximo à criatura que a ingeriu, sem direito a teste de resistência.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Punição do Profano', 'Divina', 2, 'Evocação', 'padrão', 'curto', 'instantânea', '', 'Vontade reduz à metade', '', 'Por meio de um brado poderoso, entoando um dogma de sua religião, você inflige dano a devotos de divindades adversárias.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Purificação', 'Divina', 2, 'Evocação', 'padrão', 'toque', 'instantânea', '', '', '', 'Você purifica a criatura tocada, removendo uma condição dela entre abalado, Apavorado, Alquebrado, Atordoado, Cego, Confuso, Debilitado}, Surdo.', '[{"cost":"+2 PM","effect":"também cura todos os PV perdidos por veneno.","isTrick":false},{"cost":"+2 PM","effect":"em vez de uma, remove todas as condições listadas.","isTrick":false},{"cost":"+3 PM","effect":"também permite que o alvo solte qualquer item amaldiçoado que esteja segurando (mas não remove a maldição do item em si).","isTrick":false},{"cost":"+7 PM","effect":"também dissipa magias e efeitos prejudiciais de encantamento, necromancia e transmutação afetando o alvo. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Raio Solar', 'Divina', 2, 'Evocação', 'padrão', 'médio', 'instantânea', 'linha', 'Reflexos (veja texto)', '', 'Você canaliza uma poderosa rajada de energia positiva que ilumina o campo de batalha. Criaturas na área sofrem 4d8 pontos de dano de luz (ou 4d12, se forem mortos-vivos) e ficam Ofuscado por uma rodada. Se passarem na resistência, sofrem metade do dano e não ficam ofuscadas.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Refúgio', 'Arcana', 2, 'Abjuração', 'completa', 'curto', '1 dia', '', '', '', 'Esta magia cria um domo imóvel e quase opaco por fora, mas transparente pelo lado de dentro. Ele protege contra calor, frio e forças pequenas, mas não contra qualquer coisa capaz de causar dano. Assim, o domo protege contra neve e vento comuns, mas não contra uma flecha ou Bola de Fogo. Porém, como o domo é quase opaco, qualquer criatura dentro dele tem camuflagem total contra ataques vindos de fora. Criaturas podem entrar e sair do domo livremente. Descansar dentro do Refúgio concede recuperação normal de PV e PM.', '[{"cost":"+1 PM","effect":"além do normal, os limites do domo são envoltos por uma fumaça escura e espessa, que impede criaturas do lado de fora de enxergar ou ouvir o que está dentro. Criaturas do lado de dentro enxergam e ouvem normalmente o que está do lado de fora. A fumaça também bloqueia magias de adivinhação.","isTrick":false},{"cost":"+3 PM","effect":"em vez do normal, cria uma cabana que comporta até 10 criaturas Médias. Descansar nesse espaço concede recuperação confortável (recupera PV e PM igual ao dobro do nível). Para todos os efeitos é uma cabana normal, com paredes de madeira, telhado, uma porta, duas janelas e alguma mobília (camas, uma mesa com bancos e uma lareira). A porta e as janelas têm 15 PV, RD 5 e são protegidas por um efeito idêntico à magia Tranca Arcana. As paredes têm 200 PV e RD 5.","isTrick":false},{"cost":"+3 PM","effect":"em vez do normal, cria um espaço extradimensional, similar a uma caverna vazia e escura, que comporta até 10 criaturas Médias. A entrada para o espaço precisa estar desenhada em um objeto fixo como uma grande pedra ou árvore. Qualquer criatura que atravesse a entrada consegue entrar no espaço. Nenhum efeito a partir do mundo real afeta o espaço e vice-versa, mas aqueles que estiverem dentro podem observar o mundo real como se uma janela de 1m estivesse centrada na entrada. Qualquer coisa que esteja no espaço extradimensional surge no mundo real na área vazia mais próxima da entrada quando a duração da magia acaba. Requer 3º círculo.","isTrick":false},{"cost":"+9 PM","effect":"em vez do normal, cria uma mansão extradimensional que comporta até 100 criaturas Médias, com quartos luxuosos, comida e bebida e dez servos fantasmagóricos (como na magia Servos Invisíveis). Descansar na mansão concede recuperação luxuosa (recupera PV e PM igual ao triplo do nível). A mansão tem uma única entrada, uma porta feita de luz. Você pode deixá-la visível ou invisível como uma ação livre e apenas criaturas escolhidas por você podem passar. Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Relâmpago', 'Arcana', 2, 'Evocação', 'padrão', 'médio', 'instantânea', 'linha', 'Reflexos reduz à metade', '', 'Você dispara um poderoso raio que causa 6d6 pontos de dano de eletricidade em todas as criaturas e objetos livres na área.', '[{"cost":"+2 PM","effect":"aumenta o dano em +2d6.","isTrick":false},{"cost":"+3 PM","effect":"muda o alcance para médio e a área para alvo (criaturas escolhidas). Em vez do normal, você dispara vários relâmpagos, um para cada alvo escolhido, causando 6d6 pontos de dano de eletricidade. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Rogar Maldição', 'Divina', 2, 'Necromancia', 'padrão', 'curto', 'sustentada', '', 'Fortitude anula', '', 'Você entoa cânticos maléficos que amaldiçoam uma vítima, criando efeitos variados. Ao lançar a magia, escolha entre os seguintes.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Runa de Proteção', 'Universal', 2, 'Abjuração', '1 hora', 'toque', 'permanente até ser descarregada', '', 'varia (veja o texto)', '', 'Você escreve uma runa pessoal em uma superfície fixa, como uma parede ou o chão, que protege uma pequena área ao redor. Quando uma criatura entra na área afetada a runa explode, causando 6d6 pontos de dano em todos os alvos a até 6m. A criatura que ativa a runa não tem direito a teste de resistência; outras criaturas na área têm direito a um teste de Reflexos para reduzir o dano à metade. Quando lança a magia, você escolhe o tipo de dano, entre ácido, eletricidade, fogo, frio, luz ou trevas.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Salto Dimensional', 'Arcana', 2, 'Convocação', 'padrão', 'curto', 'instantânea', '', '', '', 'Esta magia transporta você para outro lugar dentro do alcance. Você não precisa perceber nem ter linha de efeito ao seu destino, podendo simplesmente imaginá-lo. Por exemplo, pode se transportar 3m adiante para ultrapassar uma porta fechada. Uma vez transportadas, criaturas não podem agir até a rodada seguinte. Esta magia não permite que você apareça dentro de um corpo sólido; se o ponto de chegada não tem espaço livre, você ressurge na área vazia mais próxima.', '[{"cost":"+1 PM","effect":"muda o alcance para médio.","isTrick":false},{"cost":"+1 PM","effect":"muda o alvo para você e uma criatura voluntária. Você pode escolher este aprimoramento mais vezes para aumentar o número de alvos adicionais em +1, mas deve estar tocando todos os alvos.","isTrick":false},{"cost":"+2 PM","effect":"muda a execução para reação. Em vez do normal, você recebe +5 na Defesa e em testes de Reflexos contra um ataque ou efeito que esteja prestes a atingi-lo. Após a resolução do efeito, salta para um espaço adjacente (1,5m).","isTrick":false},{"cost":"+3 PM","effect":"muda o alcance para longo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Servos Invisíveis', 'Arcana', 2, 'Convocação', 'padrão', 'longo', 'cena', '', '', '', 'Você cria até três servos invisíveis e silenciosos, capazes de realizar tarefas simples como apanhar lenha, colher frutos, varrer o chão ou alimentar um cavalo. Os servos podem ser usados para manter arrumada e organizada uma mansão ou pequena torre ou para preparar um acampamento nos ermos para você e seus aliados (veja a perícia Sobrevivência, na página 123).
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Silêncio', 'Divina', 2, 'Ilusão', 'padrão', 'médio', 'sustentada', 'esfera com 6m de raio', '', '', 'Um silêncio sepulcral recai sobre a área e nenhum som é produzido nela. Enquanto estiverem na área, todas as criaturas ficam Surdo. Além disso, como lançar magias exige palavras mágicas, normalmente nenhuma magia pode ser lançada dentro da área.', '[{"cost":"+1 PM","effect":"muda a área para alvo de 1 objeto. Em vez do normal, o alvo emana uma área de silêncio com 3m de raio. Se lançar a magia num objeto de uma criatura involuntária, ela tem direito a um teste de Vontade para anulá-la.","isTrick":false},{"cost":"+2 PM","effect":"muda a duração para cena. Em vez do normal, nenhum som pode deixar a área, mas criaturas dentro da área podem falar, ouvir e lançar magias com palavras mágicas normalmente.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Soco de Arsenal', 'Divina', 2, 'Convocação', 'padrão', 'médio', 'instantânea', '', 'Fortitude parcial', '', 'Ninguém sabe se Mestre Arsenal foi realmente o criador desta magia — mas ele foi o primeiro a utilizá-la. Você fecha o punho e gesticula como se estivesse golpeando o alvo, causando dano de impacto igual a 4d6 + sua Força. A vítima é empurrada 3m na direção oposta à sua. Passar no teste de resistência reduz o dano à metade e evita o empurrão.', '[{"cost":"+1 PM","effect":"muda o alcance para pessoal, o alvo para você, a duração para cena e a resistência para nenhuma. Em vez do normal, seus ataques corpo a corpo passam a acertar inimigos distantes. Seu alcance natural aumenta em 3m; uma criatura Média pode atacar adversários a até 4,5m, por exemplo.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o dano em +1d6.","isTrick":false},{"cost":"+4 PM","effect":"aumenta o empurrão em +3m.","isTrick":false},{"cost":"+5 PM","effect":"muda o tipo do dano para essência.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Sopro das Uivantes', 'Arcana', 2, 'Evocação', 'padrão', 'pessoal', 'instantânea', 'cone de 9m', 'Fortitude parcial', '', 'Você sopra ar gélido que causa 4d6 pontos de dano de frio (Fortitude reduz à metade). Criaturas de tamanho Médio ou menor que falhem na resistência ficam caídas e são empurradas 6m na direção oposta. Se houver uma parede ou outro objeto sólido (mas não uma criatura) no caminho, a criatura para de se mover, mas sofre +2d6 pontos de dano de impacto.', '[{"cost":"+2 PM","effect":"aumenta o dano de frio em +2d6.","isTrick":false},{"cost":"+3 PM","effect":"aumenta o tamanho máximo das criaturas afetadas em uma categoria. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Sussurros Insanos', 'Arcana', 2, 'Encantamento', 'padrão', 'curto', 'cena', '', 'Vontade anula', '', 'Você murmura palavras desconexas que afetam a mente do alvo. O alvo fica Confuso.', '[{"cost":"+2 PM","effect":"aumenta o número de alvos em +1.","isTrick":false},{"cost":"+3 PM","effect":"muda o alvo para 1 criatura.","isTrick":false},{"cost":"+12 PM","effect":"muda o alvo para criaturas escolhidas. Requer 5º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Tempestade Divina', 'Divina', 2, 'Evocação', 'completa', 'longo', 'sustentada', 'cilindro com 15m de raio e 15m de altura', '', '', 'Esta magia só pode ser usada em ambientes abertos. A área fica sujeita a um vendaval — ataques à distância sofrem penalidade de –5, chamas são apagadas e névoas são dissipadas. Você também pode gerar chuva (–5 em testes de Percepção), neve (como chuva, e a área se torna terreno difícil) ou granizo (como chuva, mais 1 ponto de dano de impacto por rodada, no início de seus turnos).', '[{"cost":"+1 PM","effect":"além do normal, uma vez por rodada você pode gastar uma ação padrão para fazer um raio cair sobre um alvo na área, causando 3d8 pontos de dano de eletricidade (Reflexos reduz à metade).","isTrick":false},{"cost":"+2 PM","effect":"aumenta o dano de raios (veja acima) em +1d8.","isTrick":false},{"cost":"+3 PM","effect":"se escolheu causar chuva, ela se torna mais grossa, revelando a silhueta de criaturas invisíveis na área. Criaturas Médias ou menores ficam lentas e criaturas voadoras precisam passar num teste de Atletismo (CD da magia) por rodada ou caem ao solo (mas podem fazer testes de Acrobacia para reduzir o dano de queda, como o normal).","isTrick":false},{"cost":"+3 PM","effect":"se escolheu causar granizo, muda o dano para 2d6 por rodada.","isTrick":false},{"cost":"+3 PM","effect":"se escolheu causar neve, criaturas na área sofrem 2d6 pontos de dano de frio no início de seus turnos.","isTrick":false},{"cost":"+3 PM","effect":"muda a área para cilindro com 90m de raio e 90m de altura.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Toque Vampírico', 'Arcana', 2, 'Necromancia', 'padrão', 'toque', 'instantânea', '', 'Fortitude reduz à metade', '', 'Sua mão brilha com energia sombria, causando 6d6 pontos de dano de trevas. Você recupera pontos de vida iguais à metade do dano causado (se causou algum dano).', '[{"cost":"+2 PM","effect":"muda a resistência para nenhum. Como parte da execução da magia, você pode fazer um ataque corpo a corpo contra o alvo. Se acertar, causa o dano do ataque e da magia, e recupera pontos de vida iguais à metade do dano da magia.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o dano em +2d6.","isTrick":false},{"cost":"+2 PM","effect":"muda o alcance para pessoal, o alvo para você e a duração para cena. Em vez do normal, a cada rodada você pode gastar uma ação padrão para tocar 1 criatura e causar 3d6 pontos de dano. Você recupera pontos de vida iguais à metade do dano causado. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Traição da Lâmina', 'Divina', 2, 'Abjuração', 'padrão', 'curto', 'cena, até ser descarregada', '', 'Vontade (veja texto)', '', 'Provavelmente ofertada por Sszzaas, esta magia amaldiçoa uma arma contra seu usuário. Quando faz um ataque com a arma, o usuário deve passar em um teste de Vontade. Se falhar, a arma se retorce como uma serpente, ou muda sua trajetória em pleno voo; o agressor se torna o alvo do próprio ataque! Após esse ataque, bem- -sucedido ou não, a magia descarrega e a arma volta ao normal.', '[{"cost":"+1 PM","effect":"em vez do usuário, a arma se volta para outra criatura em alcance curto que você possa perceber, a sua escolha.","isTrick":false},{"cost":"+1 PM","effect":"muda o alvo para 1 arma e a duração para 1 dia, até ser descarregada. Requer 3° círculo.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o número de alvos em +1.","isTrick":false},{"cost":"+2 PM","effect":"adiciona componente material (uma dose de veneno). Além do normal, o ataque envenena o usuário com o veneno utilizado como componente (a CD desse veneno é a CD da própria magia).","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Traição Mágica', 'Universal', 2, 'Abjuração', 'padrão', 'curto', 'instantânea', '', 'Vontade reduz à metade', '', 'Esta magia desestabiliza outras magias ativas no alvo, fazendo com que elas causem uma súbita descarga de energia mística. Para cada círculo das magias afetando o alvo, ele sofre 1d8 pontos de dano de essência. Um alvo sob efeito de Velocidade e Voo (2º e 3º círculos) sofre 5d8 pontos de dano.', '[{"cost":"+3 PM","effect":"muda o alvo para criaturas escolhidas. Requer 3º círculo.","isTrick":false},{"cost":"+3 PM","effect":"muda a resistência para nenhuma. Requer 3º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Transposição', 'Arcana', 2, 'Convocação', 'padrão', 'curto', 'instantânea', '', '', '', 'Esta magia teletransporta duas criaturas, incluindo seu equipamento, fazendo com que troquem de lugar imediatamente.', '[{"cost":"+2 PM","effect":"aumenta o número de alvos em +2. Você determina com quais criaturas cada alvo troca de lugar.","isTrick":false},{"cost":"+5 PM","effect":"a troca não exige linha de efeito, mas os alvos ainda devem estar dentro do alcance. Requer 3º círculo.","isTrick":false},{"cost":"+5 PM","effect":"muda o alvo para 2 criaturas do tipo lacaio e adiciona resistência (Vontade anula). Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Velocidade', 'Arcana', 2, 'Transmutação', 'padrão', 'curto', 'sustentada', '', '', '', 'O alvo pode realizar uma ação padrão ou de movimento adicional por turno. Esta ação não pode ser usada para lançar magias e ativar engenhocas.', '[{"cost":"+0 PM","effect":"muda a duração para cena. A ação adicional que você pode fazer é apenas de movimento. Uma criatura só pode receber uma ação adicional por turno como efeito de Velocidade.","isTrick":false},{"cost":"+7 PM","effect":"muda o alvo para criaturas escolhidas no alcance. Requer 4º círculo.","isTrick":false},{"cost":"+7 PM","effect":"muda o alcance para pessoal e o alvo para você. Você acelera sua mente, além de seu corpo. A ação adicional pode ser usada para lançar magias e ativar engenhocas. Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Vestimenta da Fé', 'Divina', 2, 'Abjuração', 'padrão', 'toque', '1 dia', '', '', '', 'Você fortalece um item, aumentando o bônus de Defesa de uma armadura ou escudo em +2. No caso de um vestuário, ele passa a oferecer +2 na Defesa (não cumulativo com armadura). Os efeitos desta magia contam como um bônus de encanto.', '[{"cost":"+3 PM","effect":"o objeto oferece o mesmo bônus em testes de resistência. Requer 3º círculo.","isTrick":false},{"cost":"+4 PM","effect":"aumenta o bônus em +1.","isTrick":false},{"cost":"+7 PM","effect":"o objeto também oferece resistência a dano 5. Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Viagem Onírica', 'Arcana', 2, 'Adivinhação', 'padrão', 'pessoal', 'cena', '', '', '', 'Lançar esta magia faz você adormecer e abandonar seu corpo físico. Você se torna um espírito incorpóreo com deslocamento de voo 18m. Você pode ver e ouvir, mas não falar ou emitir qualquer som — nem realizar ataques, lançar magias ou interagir de qualquer forma com criaturas e objetos materiais. Você ainda pode ser visto, em forma translúcida, e pode ser afetado por qualquer efeito que afete criaturas incorpóreas.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Voz Divina', 'Divina', 2, 'Adivinhação', 'padrão', 'pessoal', 'cena', '', '', '', 'Você pode conversar com criaturas de qualquer raça e tipo: animal, construto, espírito, humanoide, monstro ou morto-vivo. Pode fazer perguntas e entende suas respostas, mesmo sem um idioma em comum ou se a criatura não for capaz de falar, mas respeitando os limites da Inteligência dela. A atitude dessas criaturas não é alterada, mas você pode usar a perícia Diplomacia para tentar mudar sua atitude.', '[{"cost":"+1 PM","effect":"você concede um pouco de vida a um cadáver, suficiente para que ele responda a suas perguntas. O conhecimento do corpo é limitado ao que ele tinha enquanto vivo e suas respostas são curtas e enigmáticas. Um corpo só pode ser alvo desta magia uma vez. Ela também não funciona em um corpo cuja cabeça tenha sido destruída.","isTrick":false},{"cost":"+1 PM","effect":"você pode falar com plantas (normais ou monstruosas) e rochas. Plantas e rochas têm percepção limitada de seus arredores e normalmente fornecem respostas simplórias.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Anular a Luz', 'Divina', 3, 'Necromancia', 'padrão', 'pessoal', 'cena', 'esfera de 6m de raio', '', '', 'Esta magia cria uma onda de escuridão que causa diversos efeitos. Todas as magias de 3º círculo ou menor ativas na área são dissipadas se você passar num teste de Religião contra a CD de cada magia. Seus aliados na área são protegidos por uma aura sombria e recebem +4 na Defesa até o fim da cena. Inimigos na área ficam Enjoadopor 1d4 rodadas (apenas uma vez por cena). Anular a Luz anula Dispersar as Trevas (este efeito tem duração instantânea).', '[{"cost":"+2 PM","effect":"aumenta o bônus na Defesa em +1.","isTrick":false},{"cost":"+4 PM","effect":"muda o círculo máximo de magias dissipadas para 4º. Requer 4º Círculo.","isTrick":false},{"cost":"+9 PM","effect":"muda o círculo máximo de magias dissipadas para 5º. Requer 5º Círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Banimento', 'Divina', 3, 'Abjuração', '1d3+1 rodadas', 'curto', 'instantânea', '', 'Vontade parcial', '', 'Você expulsa uma criatura não nativa de Arton. Um alvo nativo de outro mundo (como muitos espíritos), é teletransportado de volta para um lugar aleatório de seu mundo de origem. Já um alvo morto-vivo tem sua conexão com as energias negativas rompidas, sendo reduzido a 0 PV. Se passar na resistência, em vez dos efeitos acima, o alvo fica enjoado por 1d4 rodadas.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Coluna de Chamas', 'Divina', 3, 'Evocação', 'padrão', 'longo', 'instantânea', 'cilindro com 3m de raio e 30m de altura', 'Reflexos reduz à metade', '', 'Um pilar de fogo sagrado desce dos céus, causando 6d6 pontos de dano de fogo mais 6d6 pontos de dano de luz nas criaturas e objetos livres na área.', '[{"cost":"+1 PM","effect":"aumenta o dano de fogo em +1d6.","isTrick":false},{"cost":"+1 PM","effect":"aumenta o dano de luz em +1d6.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Comunhão com a Natureza', 'Divina', 3, 'Adivinhação', 'completa', 'pessoal', '1 dia', '', '', '', 'Após uma breve união com a natureza local, você obtém informações e intuições sobre a região em que está, numa distância equivalente a um dia de viagem. Você recebe 6d4 dados de auxílio. 
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Contato Extraplanar', 'Arcana', 3, 'Adivinhação', 'completa', 'pessoal', '1 dia', '', '', '', 'Sua mente viaja até outro plano de existência, onde entra em contato com seres extraplanares como gênios e demônios. Você firma um contrato com uma dessas entidades para que o auxilie durante o dia, em troca de se alimentar de seu mana. Quando a magia é lançada, você recebe 6d6 dados de auxílio. Enquanto a magia durar, sempre que for realizar um teste de perícia, você pode gastar 1d6 (mais 1d6 para cada círculo de magias acima do 3º que puder lançar) e adicionar o resultado como bônus no teste. No entanto, sempre que rolar um “6” num desses dados, a entidade “suga” 1 PM de você. A magia termina se você gastar todos os dados, ficar sem PM ou no fim do dia (o que acontecer primeiro).', '[{"cost":"+2 PM","effect":"aumenta o número de dados de auxílio em +1.","isTrick":false},{"cost":"+8 PM","effect":"Muda os dados de auxílio para d12. Sempre que rolar um resultado 12 num desses d12, a entidade “suga” 2 PM de você. Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Controlar Terra', 'Divina', 3, 'Transmutação', 'padrão', 'longo', '', '9 cubos com 1,5m de lado', 'Veja texto', '', 'Você manipula a densidade e a forma de toda terra, pedra, lama, argila ou areia na área. Ao lançar a magia, escolha.Amolecer: se afetar o teto, uma coluna ou suporte, provoca um desabamento que causa 10d6 pontos de dano de impacto às criaturas na área (Reflexos reduz à metade). Se afetar um piso de terra ou pedra, cria terreno difícil de areia ou argila, respectivamente.Modelar: pode usar pedra ou argila para criar um ou mais objetos simples de tamanho Enorme ou menor (sem mecanismos ou partes móveis). Por exemplo, pode transformar um tijolo em uma maça, criar uma passagem onde antes havia apenas uma parede ou levantar uma ou mais paredes que oferecem cobertura total (RD 8 e 50 PV para cada 3m).Solidificar: transforma lama ou areia em terra ou pedra. Criaturas com os pés na superfície ficam agarradas. Elas podem se soltar com uma ação padrão e um teste de Acrobacia ou Atletismo.', '[{"cost":"+1 PM","effect":"aumenta o número de cubos de 1,5m em +2.","isTrick":false},{"cost":"+1 PM","effect":"muda o alcance para pessoal, o alvo para você e a duração para 1 dia. Você e seu equipamento fundem-se a uma superfície ou objeto adjacente feito de pedra, terra, argila ou areia que possa acomodá-lo. Você pode voltar ao espaço adjacente como uma ação livre, dissipando a magia. Enquanto mesclado, você não pode falar ou fazer ações físicas, mas consegue perceber seus arredores normalmente. Pequenos danos não o afetam, mas se o objeto (ou o trecho onde você está imerso) for destruído, a magia é dissipada, você volta a um espaço livre adjacente e sofre 10d6 pontos de dano de impacto.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Controlar Água', 'Divina', 3, 'Transmutação', 'padrão', 'longo', 'cena', 'esfera com 30m de raio', 'Veja texto', '', 'Você controla os movimentos e comportamentos da água. Ao lançar a magia, escolha um dos efeitos abaixo.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Convocação Instantânea', 'Arcana', 3, 'Convocação', 'padrão', 'ilimitado (veja texto)', 'instantânea', '', '', '', 'Você invoca um objeto de qualquer lugar para sua mão. O item deve ter sido previamente preparado com uma runa ou marca pessoal sua (ao custo de T$ 5). A magia não funciona se o objeto estiver com outra criatura, mas você saberá onde ele está e quem o está carregando (ou sua descrição física, caso não conheça a criatura).', '[{"cost":"+1 PM","effect":"além do normal, até 1 hora após ter lançado a magia, você pode gastar uma ação de movimento para enviar o objeto de volta para o local em que ele estava antes.","isTrick":false},{"cost":"+1 PM","effect":"muda o alvo para um baú Médio, a duração para permanente e adiciona sacrifício de 1 PM. Em vez do normal, você esconde o baú alvo no Etér Entre Mundos, com até 20 espaços de equipamento. A magia faz com que qualquer objeto caiba no baú, independentemente do seu tamanho. Uma vez escondido, você pode convocar o baú para um espaço livre adjacente, ou de volta para o Etér, com uma ação padrão. Componente material: baú construído com matéria-prima da melhor qualidade (T$ 1.000). Você deve ter em mãos uma miniatura do baú, no valor de T$ 100, para invocar o baú verdadeiro.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o número de alvos em +1.","isTrick":false},{"cost":"+2 PM","effect":"muda o alvo para 1 objeto de até 10 espaços. Um objeto muito grande ou pesado para aparecer em suas mãos surge em um espaço adjacente a sua escolha.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Coração Imortal', 'Universal', 3, 'Necromancia', 'padrão', 'pessoal', 'cena', '', '', '', 'Manipulando energias necromânticas, você concentra sua força vital em uma parte específica do seu corpo. Você recebe fortificação 100% e imunidade a sangramento.', '[{"cost":"+2 PM","effect":"muda a duração para 1 dia.","isTrick":false},{"cost":"+2 PM","effect":"aumenta a cura do aprimoramento abaixo para +10 PV.","isTrick":false},{"cost":"+4 PM","effect":"adiciona componente material (um coração de pedra no valor de T$ 100). Além do normal, quando seus pontos de vida são reduzidos a 0 ou menos, você cura 30 PV e a magia se encerra. Você só pode ser curado por este aprimoramento uma vez por dia.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Despertar Consciência', 'Divina', 3, 'Encantamento', 'completa', 'toque', '1 dia', '', '', '', 'Você desperta a consciência de um animal ou planta. O alvo se torna um parceiro veterano de um tipo a sua escolha entre ajudante, combatente, fortão, guardião, médico, perseguidor ou vigilante. Se usar esta magia em um parceiro que já possua, o nível de poder de um de seus tipos aumenta em um passo (iniciante para veterano, veterano para mestre). Se já for um parceiro mestre, recebe o bônus de outro tipo de parceiro iniciante (entre as escolhas acima). O alvo se torna uma criatura racional, com Inteligência –1, e pode falar', '[{"cost":"+4 PM","effect":"muda o alvo para 1 escultura mundana inanimada. Além do normal, o alvo tem as mesmas características de um construto.","isTrick":false},{"cost":"+4 PM","effect":"muda a duração para permanente e adiciona penalidade de -3 PM.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Dificultar Detecção', 'Arcana', 3, 'Abjuração', 'padrão', 'toque', '1 dia', '', '', '', 'Esta magia oculta a presença do alvo contra qualquer meio mágico de detecção, inclusive detectar magia. Um conjurador que lance uma magia de adivinhação para detectar a presença ou localização do alvo deve fazer um teste de Vontade. Se falhar, a magia não funciona, mas os PM são gastos mesmo assim. Se for lançada sobre uma criatura, Dificultar Detecção protege tanto a criatura quanto seu equipamento.', '[{"cost":"+4 PM","effect":"muda o alvo para área de cubo de 9m. Qualquer criatura ou objeto na área recebe o efeito da magia enquanto estiver dentro dela.","isTrick":false},{"cost":"+4 PM","effect":"muda a duração para 1 semana.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Dispersar as Trevas', 'Divina', 3, 'Evocação', 'padrão', 'pessoal', 'veja texto', 'Esfera de 6m de raio', '', '', 'Esta magia cria um forte brilho (multicolorido ou de uma cor que remeta a sua divindade) que causa diversos efeitos. Todas as magias de 3º círculo ou menor ativas na área são dissipadas se você passar num teste de Religião contra a CD de cada magia. Seus aliados na área recebem +4 em testes de resistência e redução de trevas 10 até o fim da cena, protegidos por uma aura sutil da mesma cor. Inimigos na área ficam Cego por 1d4 rodadas (apenas uma vez pela magia). Dispersar as Trevas anula Anular a Luz (este efeito tem duração instantânea).', '[{"cost":"+2 PM","effect":"aumenta o bônus nas resistências em +1.","isTrick":false},{"cost":"+4 PM","effect":"muda o alcance para curto, a área para alvo 1 criatura e a duração para cena. O alvo fica imune a efeitos de necromancia e trevas.","isTrick":false},{"cost":"+4 PM","effect":"muda o círculo máximo de magias dissipadas para 4º. Requer 4º círculo.","isTrick":false},{"cost":"+9 PM","effect":"muda o círculo máximo de magias dissipadas para 5º. Requer 5º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Enxame Rubro de Ichabod', 'Arcana', 3, 'Convocação', 'padrão', 'médio', 'sustentada', '', 'Reflexos reduz à metade', '', 'Você conjura um enxame de pequenas criaturas da Tormenta. O enxame pode passar pelo espaço de outras criaturas e não impede que outras criaturas entrem no espaço dele. No final de cada um de seus turnos, o enxame causa 4d12 pontos de dano de ácido a qualquer criatura em seu espaço (Reflexos reduz à metade). Você pode gastar uma ação de movimento para mover o enxame com deslocamento de 12m.', '[{"cost":"+1 PM","effect":"além do normal, uma criatura que falhe no teste de Reflexos fica agarrada (o enxame escala e cobre o corpo dela). A criatura pode gastar uma ação padrão e fazer um teste de Acrobacia ou Atletismo para escapar. Se você mover o enxame, a criatura fica livre.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o dano em +1d12.","isTrick":false},{"cost":"+2 PM","effect":"muda o dano para trevas.","isTrick":false},{"cost":"+3 PM","effect":"o enxame vira Enorme (quadrado de 6m de lado).","isTrick":false},{"cost":"+3 PM","effect":"o enxame ganha deslocamento de voo 18m e passa a ocupar um cubo ao invés de um quadrado.","isTrick":false},{"cost":"+4 PM","effect":"o enxame inclui parasitas inchados que explodem e criam novos enxames. No início de cada um de seus turnos, role 1d6. Em um resultado 5 ou 6, um novo enxame surge adjacente a um já existente à sua escolha. Você pode mover todos os enxames com uma única ação de movimento, mas eles não podem ocupar o mesmo espaço. Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Erupção Glacial', 'Arcana', 3, 'Evocação', 'padrão', 'médio', 'instantânea', 'quadrado de 6m de lado', 'Relfexos parcial', '', 'Estacas de gelo irrompem do chão. Criaturas na área sofrem 4d6 de dano de corte, 4d6 de dano de frio e ficam caídas. Passar no teste de Reflexos evita o dano de corte e a queda. As estacas duram pela cena, o que torna a área afetada terreno difícil, e concedem cobertura leve para criaturas dentro da área ou atrás dela. As estacas são destruídas caso sofram qualquer quantidade de dano por fogo mágico.', '[{"cost":"+3 PM","effect":"aumenta o dano de frio em +2d6 e o dano de corte em +2d6.","isTrick":false},{"cost":"+4 PM","effect":"muda a área para cilindro com 6m de raio e 6m de altura e a duração para sustentada. Em vez do normal, a magia cria uma tempestade de granizo que causa 3d6 pontos de dano de impacto e 3d6 pontos de dano de frio em todas as criaturas na área (sem teste de resistência). A tempestade fornece camuflagem leve as criaturas dentro dela e deixa o piso escorregadio. Piso escorregadio conta como terreno difícil e obriga criaturas na área a fazer testes de Acrobacia para equilíbrio (veja o Capítulo 2). Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Ferver Sangue', 'Arcana', 3, 'Necromancia', 'padrão', 'curto', 'sustentada', '', 'Fortitude parcial', '', 'O sangue do alvo aquece rapidamente até entrar em ebulição. Quando a magia é lançada, e no início de cada um de seus turnos, o alvo sofre 4d8 pontos de dano de fogo e fica Enjoado por uma rodada (Fortitude reduz o dano à metade e evita a condição). Se o alvo passar em dois testes de Fortitude seguidos, dissipa a magia. Se o alvo for reduzido a 0 PV pelo dano desta magia, seu corpo explode, matando-o e causando 6d6 pontos de dano de fogo em todas as criaturas a até 3m (Reflexos reduz à metade). Essa magia não afeta criaturas sem sangue, como construtos ou mortos-vivos.', '[{"cost":"+2 PM","effect":"aumenta o dano em +1d8.","isTrick":false},{"cost":"+9 PM","effect":"muda alvo para criaturas escolhidas. Requer 5º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Globo de Invulnerabilidade', 'Arcana', 3, 'Abjuração', 'padrão', 'pessoal', 'sustentada', '', '', '', 'Você é envolto por uma esfera mágica brilhante com 3m de raio, que detém qualquer magia de 2º círculo ou menor. Nenhuma magia pode ser lançada contra um alvo dentro do globo e magias de área não têm efeito dentro dele. No entanto, magias ainda podem ser lançadas de dentro para fora.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Heroísmo', 'Divina', 3, 'Encantamento', 'padrão', 'toque', 'cena', '', '', '', 'Esta magia imbui uma criatura com coragem e valentia. O alvo fica imune a medo e recebe 40 PV temporários e +4 em testes de ataque e rolagens de dano contra o inimigo de maior ND na cena.', '[{"cost":"+2 PM","effect":"muda o bônus para +6.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Ilusão Lacerante', 'Arcana', 3, 'Ilusão', 'padrão', 'médio', 'sustentada', 'cubo de 9m', 'Vontade anula', '', 'Você cria uma ilusão de algum perigo mortal. Quando a magia é lançada, criaturas na área devem fazer um teste de Vontade; uma falha significa que a criatura acredita que a ilusão é real e sofre 3d6 pontos de dano psíquico não letal. Sempre que uma criatura iniciar seu turno dentro da área, deve repetir o teste de Vontade. Se falhar, sofre o dano novamente. Somente criaturas que falham veem a ilusão, e racionalizam o efeito sempre que falham no teste (por exemplo, acredita que o mesmo teto pode cair sobre ela várias vezes).', '[{"cost":"+3 PM","effect":"aumenta o dano em +2d6.","isTrick":false},{"cost":"+4 PM","effect":"muda a área para um cubo de 90m. Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Imobilizar', 'Universal', 3, 'Encantamento', 'padrão', 'curto', 'cena', '', 'Vontade parcial', '', 'O alvo fica Paralisado; se passar na resistência, em vez disso fica Lento. A cada rodada, pode gastar uma ação completa para fazer um novo teste de Vontade. Se passar, se liberta do efeito.', '[{"cost":"+1 PM","effect":"muda o alvo para 1 espírito.","isTrick":false},{"cost":"+2 PM","effect":"aumenta o número de alvos em +1.","isTrick":false},{"cost":"+3 PM","effect":"muda o alvo para 1 criatura. Requer 4º círculo","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Lança Ígnea de Aleph', 'Arcana', 3, 'Evocação', 'padrão', 'médio', 'instantânea', '', 'Reflexos parcial', '', 'Esta magia foi desenvolvida pelo mago imortal Aleph Olhos Vermelhos, um entusiasta dos estudos vulcânicos. Ela dispara um projétil de magma contra o alvo, que sofre 4d6 pontos de dano de fogo e 4d6 pontos de dano de perfuração e fica em chamas. As chamas causam 2d6 pontos de dano por rodada, em vez do dano normal. Se passar no teste de resistência, o alvo sofre metade do dano e não fica em chamas.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Lendas e Histórias', 'Universal', 3, 'Adivinhação', 'padrão', 'toque', 'sustentada', '', '', '', 'Você descobre informações sobre uma criatura, objeto ou local que esteja tocando. O que exatamente você descobre depende do mestre: talvez você não descubra tudo que há para saber, mas ganhe pistas para continuar a investigação. A cada rodada que mantiver a magia, você descobre:
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Manto de Sombras', 'Universal', 3, 'Ilusão', 'padrão', 'pessoal', 'sustentada', '', '', '', 'Você fica coberto por um manto de energia sombria. Nesta forma, torna-se incorpóreo (inclui seu equipamento): só pode ser afetado por armas mágicas,  ou por outras criaturas incorpóreas e pode atravessar objetos sólidos, mas não manipulá-los. Também não pode atacar criaturas normais (mas ainda pode lançar magias nelas). Além disso, se torna vulnerável à luz direta: se exposto a uma fonte de luz, sofre 1 ponto de dano por rodada.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Miragem', 'Arcana', 3, 'Ilusão', 'padrão', 'longo', '1 dia', 'cubo de até 90m de lado', 'Vontade desacredita', '', 'Você faz um terreno parecer outro, incluindo sons e cheiros. Uma planície pode parecer um pântano, uma floresta pode parecer uma montanha etc. Esta magia pode ser usada para criar armadilhas: areia movediça pode parecer terra firme ou um precipício pode parecer um lago. Você pode alterar, incluir e esconder estruturas dentro da área, mas não criaturas (embora elas possam se esconder nas estruturas ilusórias).', '[{"cost":"+4 PM","effect":"além do normal, pode alterar a aparência de criaturas escolhidas na área, como se usando Disfarce Ilusório.","isTrick":false},{"cost":"+9 PM","effect":"muda a duração para permanente e adiciona componente material (pó de diamante no valor de T$ 1.000). Requer 5º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Missão Divina', 'Divina', 3, 'Encantamento', 'padrão', 'curto', '1 semana ou até ser descarregada', '', 'Vontade anula (veja texto)', '', 'Esta magia obriga o alvo a cumprir uma tarefa a sua escolha. Ela dura uma semana ou até o alvo cumprir a tarefa, o que vier primeiro. O alvo pode recusar a missão — mas, no fim de cada dia em que não se esforçar para cumprir a tarefa, deve fazer um teste de Vontade; se falhar, sofre uma penalidade cumulativa de –2 em todos os testes e rolagens.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Muralha Elemental', 'Arcana', 3, 'Evocação', 'padrão', 'médio', 'cena', '', 'veja texto', '', 'Cria uma muralha de um elemento a sua escolha. A muralha pode ser um muro de até 30m de comprimento e 3m de altura (ou o contrário) ou uma cúpula de 3m de raio. Os efeitos variam conforme o elemento escolhido.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Pele de Pedra', 'Universal', 3, 'Transmutação', 'padrão', 'pessoal', 'cena', '', '', '', 'Sua pele ganha aspecto e dureza de rocha. Você recebe redução de dano 5.', '[{"cost":"+1 PM","effect":"muda o alcance para toque e o alvo para 1 criatura.","isTrick":false},{"cost":"+4 PM","effect":"muda a duração para 1 dia.","isTrick":false},{"cost":"+4 PM","effect":"sua pele ganha aspecto e dureza de aço. Você recebe resistência a dano 10. Requer 4º círculo.","isTrick":false},{"cost":"+4 PM","effect":"muda o alcance para toque, o alvo para 1 criatura, a duração para 1d4 rodadas e adiciona Resistência: Fortitude anula. Em vez do efeito normal, a magia transforma o alvo e seu equipamento em uma estátua inerte e sem consciência. A estátua possui os mesmos PV da criatura e resistência a dano 8; se for quebrada, a criatura morrerá. Requer 4º círculo.","isTrick":false},{"cost":"+9 PM","effect":"como acima, mas com duração permanente. Requer 5º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Poeira da Podridão', 'Divina', 3, 'Necromancia', 'padrão', 'médio', 'cena', 'nuvem com 6m de raio', 'Fortitude (veja texto)', '', 'Você manifesta uma nuvem de poeira carregada de energia negativa, que apodrece lentamente as criaturas na área. Ao lançar a magia, e no início de seus turnos, criaturas na área sofrem 2d8+8 pontos de dano de trevas (Fortitude reduz à metade). Alvos que falharem no teste não podem recuperar PV por uma rodada.', '[{"cost":"+2 PM","effect":"aumenta o dano em 1d8+4.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Potência Divina', 'Divina', 3, 'Transmutação', 'padrão', 'pessoal', 'sustentada', '', '', '', 'Você canaliza o poder de sua divindade. Você aumenta uma categoria de tamanho (seu equipamento muda de acordo) e recebe Força +4 e RD 10. Você não pode lançar magias enquanto estiver sob efeito de Potência Divina.', '[{"cost":"+2 PM","effect":"aumenta o bônus de Força em +1.","isTrick":false},{"cost":"+5 PM","effect":"aumenta a resistência a dano em +5.","isTrick":false},{"cost":"+2 PM","effect":"muda o alcance para toque e o alvo para 1 criatura. A magia falha se você e o alvo não forem devotos da mesma divindade.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Proteção Contra Magia', 'Divina', 3, 'Abjuração', 'padrão', 'toque', 'cena', '', '', '', 'Você protege o alvo contra efeitos mágicos nocivos. O alvo recebe +5 em testes de resistência contra magias.', '[{"cost":"+4 PM","effect":"muda o bônus para +10. Requer 4º círculo.","isTrick":false},{"cost":"+4 PM","effect":"em vez do normal, o alvo fica imune a uma escola de magia a sua escolha. Requer 4º Círculo.","isTrick":false},{"cost":"+9 PM","effect":"em vez do normal, o alvo fica imune a duas escolas de magia a sua escolha. Requer 5º Círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Selo de Mana', 'Universal', 3, 'Encantamento', 'padrão', 'toque', 'cena', '', 'Vontade Parcial', '', 'Seu toque manifesta um selo mágico na pele do alvo, que atrapalha o fluxo de mana. Pela duração da magia, sempre que o alvo realizar qualquer ação que gaste PM, deve fazer um teste de Vontade; se passar, faz a ação normalmente. Se falhar, a ação não tem efeito (mas os PM são gastos mesmo assim).', '[{"cost":"+4 PM","effect":"muda o alcance para curto e o alvo para criaturas escolhidas dentro do alcance. Requer 4º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Servo Divino', 'Divina', 3, 'Convocação', 'padrão', 'curto', 'Cena ou até ser descarregada', '', '', '', 'Você pede a sua divindade que envie um espírito para ajudá-lo. Esse espírito realiza uma tarefa a sua escolha que possa ser cumprida em até uma hora — desde algo simples como “use suas asas para nos levar até o topo da montanha” até algo complexo como “escolte esses camponeses até o castelo”. A magia é descarregada quando a criatura cumpre a tarefa, retornando a seu plano natal. O tipo de criatura é escolhido pelo mestre, de acordo com as necessidades da tarefa.Componente material: um pagamento de T$ 100 ao espírito. A forma de pagamento varia — doações a um templo, um item mágico ou mesmo dinheiro.', '[{"cost":"+4 PM","effect":"muda a duração para 1 dia ou até ser descarregada. O espírito realiza uma tarefa a sua escolha que exija até um dia. O custo do pagamento aumenta para T$ 500. O resto segue normal.","isTrick":false},{"cost":"+9 PM","effect":"muda a duração para 1 semana ou até ser descarregada. O espírito realiza uma tarefa que exija até uma semana. O custo do pagamento aumenta para T$ 1.000. O resto segue normal.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Servo Morto-Vivo', 'Universal', 3, 'Necromancia', 'completa', 'toque', 'instantânea', '', '', '', 'Esta magia transforma o cadáver de um humanoide, animal ou monstro em um esqueleto ou zumbi (conforme o estado de conservação do corpo). O morto-vivo então obedece a todos os seus comandos, mesmo suicidas. Se quiser que o morto-vivo o acompanhe, ele funciona como um aliado iniciante, de um tipo a sua escolha entre ajudante, atirador, combatente, fortão, guardião ou montaria.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Sopro da Salvação', 'Divina', 3, 'Evocação', 'padrão', 'pessoal', 'instantânea', 'cone de 9m', '', '', 'Você enche seus pulmões de luz e energia positiva e sopra um cone de poeira reluzente. O sopro afeta apenas seus aliados na área, curando 2d8+4 pontos de vida e removendo uma das seguintes condições de todos os alvos: abalado, atordoado, apavorado, alquebrado, cego, confuso, debilitado, enfeitiçado, enjoado, esmorecido, exausto, fascinado, fatigado, fraco, frustrado, lento, paralisado, pasmo e surdo.', '[{"cost":"+2 PM","effect":"aumenta a quantidade de cura em 1d8+2.","isTrick":false},{"cost":"+4 PM","effect":"além do normal, se um aliado estiver com PV negativos, seus PV são levados a 0 e então a cura é aplicada.","isTrick":false},{"cost":"+4 PM","effect":"remove todas as condições listadas, em vez de apenas uma.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Telecinésia', 'Arcana', 3, 'Transmutação', 'padrão', 'médio', 'sustentada ou instantânea (veja texto)', '', '', '', 'Você move objetos ou criaturas se concentrando. Ao lançar a magia, escolha uma das opções a seguir.Força Contínua: você move uma criatura Média ou menor, ou objeto de até 10 espaços, a até 6m por rodada. Uma criatura pode anular o efeito sobre ela, ou sobre um objeto que possua, passando num teste de Vontade. O alvo pode ser movido em qualquer direção dentro do alcance. Ele cai no chão se sair do alcance ou a magia terminar. Duração: sustentada.Empurrão Violento: nesta versão a energia mágica é expelida de uma única vez e arremessa até 10 objetos (no máximo 10 espaços). Os objetos devem estar a até 3m uns dos outros e podem ser arremessados até o alcance da magia.Objetos arremessados podem atingir criaturas em seu caminho, causando de 1 ponto de dano de impacto por espaço (objetos macios, sem pontas ou sem fio) até 1d6 pontos de dano por espaço (objetos duros, pontudos ou afiados). Criaturas atingidas têm direito a um teste de Reflexos para reduzir o dano à metade.Criaturas médias ou menores podem ser arremessadas, mas têm direito a um teste de Vontade para evitar o efeito (em si mesmas ou em objetos que estejam segurando). Uma criatura arremessada contra uma superfície sólida sofre 1d6 pontos de dano de impacto para cada 3m que “voou” no deslocamento (incluindo outras criaturas; nesse caso, ambas sofrem o dano). Duração: instantânea.', '[{"cost":"+3 PM","effect":"aumenta o tamanho máximo da criatura em uma categoria (para Grande, Enorme e Colossal) ou dobra a quantidade de espaços do objeto.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Teletransporte', 'Arcana', 3, 'Convocação', 'padrão', 'toque', 'instantânea', '', '', '', 'Esta magia transporta os alvos para um lugar a sua escolha a até 1.000km. Você precisa fazer um teste de Misticismo, com dificuldade que depende de seu conhecimento sobre o local de destino.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Tentáculos de Trevas', 'Arcana', 3, 'Necromancia', 'padrão', 'médio', 'cena', 'esfera com 6m de raio', '', '', 'Um círculo de energias sombrias se abre no chão, de onde surgem tentáculos feitos de treva viscosa. Ao lançar a magia e no início de cada um de seus turnos, você faz um teste da manobra agarrar (usando seu bônus de Misticismo) contra cada criatura na área. Se você passar, a criatura é agarrada; se a vítima já está agarrada, é esmagada, sofrendo 4d6 pontos de dano de trevas. A área conta como terreno difícil. Os tentáculos são imunes a dano.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Transformação de Guerra', 'Arcana', 3, 'Transmutação', 'padrão', 'pessoal', 'sustentada', '', '', '', 'Você se torna uma máquina de combate, ficando mais forte, rápido e resistente. Você recebe +6 na Defesa, testes de ataque e rolagens de dano corpo a corpo, e 30 PV temporários. Durante a Transformação de Guerra você não pode lançar magias, mas se torna proficiente em todas as armas.', '[{"cost":"+2 PM","effect":"aumenta os bônus na Defesa, testes de ataque e rolagens de dano corpo a corpo em +1, e os PV temporários em +10.","isTrick":false},{"cost":"+2 PM","effect":"adiciona componente material (uma barra de adamante no valor de T$ 100). Sua forma de combate ganha um aspecto metálico e sem expressões. Além do normal, você recebe resistência a dano 10 e imunidade a atordoamento e efeitos de cansaço, encantamento, metabolismo, trevas e veneno, e não precisa respirar.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Viagem Arbórea', 'Divina', 3, 'Convocação', 'completa', 'pessoal', 'cena', '', '', '', 'Como parte da execução, você entra em uma árvore adjacente que seja maior do que você. Você pode permanecer dentro da árvore, percebendo os arredores de forma normal (mas sem poder fazer ações). Você pode gastar uma ação de movimento para sair da mesma árvore, ou de qualquer outra dentro de 1km. Se estiver dentro de uma árvore que seja destruída, a magia termina e você sofre 10d6 pontos de dano de impacto. Enquanto a magia durar você pode gastar uma ação de movimento e 1 PM para entrar em outras árvores.', '[{"cost":"+2 PM","effect":"muda o alcance para toque, o alvo para até cinco criaturas e a duração para instantânea. Os alvos entram em uma planta (de tamanho Médio ou maior) e saem em outra planta do mesmo tamanho a até 100km de distância, especificada em direção e distância aproximadas (como “50km ao norte”).","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Vidência', 'Universal', 3, 'Adivinhação', 'completa', 'ilimitado (veja texto)', 'sustentada', '', 'Vontade anula', '', 'Através de uma superfície reflexiva (bacia de água benta para clérigos, lago para druidas, bola de cristal para magos, espelho para feiticeiros etc.) você pode ver e ouvir uma criatura escolhida e seus arredores (cerca de 6m em qualquer direção), mesmo que ela se mova. O alvo pode estar a qualquer distância, mas se passar em um teste de Vontade, a magia falha. A vítima recebe bônus ou penalidades em seu teste de resistência, dependendo do conhecimento que você tiver dela.Não conhece o alvo: +10.Ouviu falar do alvo: +5.O alvo está em outro plano ou mundo: +5.Já encontrou o alvo pessoalmente: +0.Tem uma pintura, escultura ou outra representação do alvo: –2.Conhece bem o alvo: –5.Tem um pertence pessoal ou peça de roupa do alvo: –5.Tem uma parte do corpo do alvo (unhas, cabelos...): –10.', '[]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Voo', 'Arcana', 3, 'Transmutação', 'padrão', 'pessoal', 'cena', '', '', '', 'Você recebe deslocamento de voo 12m. Voar por meio desta magia é simples como andar — você pode atacar e lançar magias normalmente enquanto voa. Quando a magia termina, você desce lentamente até o chão, como se estivesse sob efeito de Queda Suave.', '[{"cost":"+1 PM","effect":"muda o alcance para toque e o alvo para 1 criatura.","isTrick":false},{"cost":"+4 PM","effect":"muda a duração para 1 dia. Requer 4º círculo.","isTrick":false},{"cost":"+4 PM","effect":"muda o alcance para curto e o alvo para até 10 criaturas. Requer 4° círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Âncora Dimensional', 'Arcana', 3, 'Abjuração', 'padrão', 'curto', 'cena', '', '', '', 'O alvo é envolvido por um campo de força cor de esmeralda que impede qualquer movimento planar. Isso inclui magias de convocação (como Salto Dimensional e Teletransporte), viagens astrais e a habilidade incorpóreo.', '[{"cost":"+2 PM","effect":"muda o alcance para médio, a área para esfera com 3m de raio e o alvo para criaturas escolhidas.","isTrick":false},{"cost":"+2 PM","effect":"muda o efeito para criar um fio de energia cor de esmeralda que prende o alvo a um ponto no espaço dentro do alcance. O ponto precisa ser fixo, mas não precisa de nenhum apoio ou superfície (pode simplesmente flutuar no ar). O alvo não pode se afastar mais de 3m do ponto, nem fisicamente, nem com movimento planar. O fio possui 20 PV e resistência a dano 20 (mas pode ser dissipado por efeitos que libertam criaturas, como o Julgamento Divino: Libertação do paladino).","isTrick":false},{"cost":"+4 PM","effect":"muda o efeito para criar um fio de energia cor de esmeralda que prende o alvo a um ponto no espaço dentro do alcance. O ponto precisa ser fixo, mas não precisa de nenhum apoio ou superfície (pode simplesmente flutuar no ar). O alvo não pode se afastar mais de 3m do ponto, nem fisicamente, nem com movimento planar. O fio possui 20 PV e redução de dano 40 (mas pode ser dissipado por efeitos que libertam criaturas, como o Julgamento Divino: Libertação do paladino).","isTrick":false},{"cost":"+4 PM","effect":"muda o alvo para área de cubo de 9m, a duração para permanente e adiciona componente material (chave de esmeralda no valor de T$ 2.000). Em vez do normal, nenhum tipo de movimento planar pode ser feito para entrar ou sair da área.","isTrick":false},{"cost":"+9 PM","effect":"muda o alcance para médio, a área para esfera de 3m de raio e o alvo para criaturas escolhidas. Cria um fio de energia (veja acima) que prende todos os alvos ao centro da área.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Alterar Memória', 'Arcana', 4, 'Encantamento', 'padrão', 'toque', 'instantânea', '', 'Vontade anula', '', 'Você invade a mente do alvo e altera ou apaga suas memórias da última hora.', '[{"cost":"+2 PM","effect":"muda o alcance para pessoal e o alvo para área cone de 4,5m.","isTrick":false},{"cost":"+5 PM","effect":"você pode alterar ou apagar as memórias das últimas 24 horas.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Animar Objetos', 'Arcana', 4, 'Transmutação', 'padrão', 'médio', 'cena', '', '', '', 'Você concede vida a objetos inanimados. Cada objeto se torna um parceiro sob seu controle. O tipo dele é escolhido da lista de tamanho e ele não conta em seu limite de parceiros. Com uma ação de movimento, você pode comandar mentalmente qualquer objeto animado dentro do alcance para que auxilie você ou outra criatura. Outros usos criativos para os objetos ficam a cargo do mestre. Objetos animados são construtos com valores de Força, Destreza e  PV de acordo com seu tamanho. Todos os outros atributos nulos, eles não têm valor de Defesa ou testes de resistência e falham automaticamente em qualquer teste oposto. Diferente de parceiros comuns, um objeto pode ser alvo de um ataque direto. Esta magia não afeta itens mágicos, nem objetos que estejam sendo carregados por outra criatura.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Assassino Fantasmagórico', 'Arcana', 4, 'Necromancia', 'padrão', 'longo', 'cena, até ser descarregada', '', 'Vontade Anula, Fortitude Parcial', '', 'Usando os medos subconscientes do alvo, você cria uma imagem daquilo que ele mais teme. Apenas a própria vítima pode ver o Assassino Fantasmagórico com nitidez; outras criaturas presentes (incluindo o conjurador) enxergam apenas um espectro sombrio.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Campo Antimagia', 'Arcana', 4, 'Abjuração', 'padrão', 'pessoal', 'sustentada', '', '', '', 'Você é cercado por uma barreira invisível com 3m de raio que o acompanha. Qualquer habilidade mágica ou item mágico que entre na área da barreira é suprimida enquanto estiver lá.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Conceder Milagre', 'Divina', 4, 'Encantamento', 'padrão', 'toque', 'permanente ou até ser descarregada', '', '', '', 'Você transfere um pouco de seu poder divino a outra criatura. Escolha uma magia de até 2º círculo que você conheça; o alvo pode lançar essa magia uma vez, sem pagar o custo base dela em PM (aprimoramentos podem ser usados, mas o alvo deve gastar seus próprios PM). Você sofre uma penalidade de –3 PM até que o alvo lance a magia.', '[{"cost":"+4 PM","effect":"muda o círculo da magia concedida para 3º e a penalidade de PM para –6.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Conjurar Elemental', 'Arcana', 4, 'Convocação', 'completa', 'médio', 'sustentada', '', '', '', 'Esta magia transforma uma porção de um elemento inerte em uma criatura elemental Grande do tipo do elemento alvo. Por exemplo, lançar esta magia numa fogueira ou tocha cria um elemental do fogo. Você pode criar elementais do ar, água, fogo e terra com essa magia. O elemental obedece a todos os seus comandos e pode funcionar como um parceiro mestre do tipo destruidor (cuja habilidade custa apenas 2 PM para ser usada) e mais um tipo entre os indicados na lista abaixo. O elemental auxilia apenas você e não conta em seu limite de parceiros.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Controlar a Gravidade', 'Arcana', 4, 'Transmutação', 'padrão', 'médio', 'sustentada', 'cubo de 12m de lado', '', '', 'Você controla os efeitos da gravidade dentro da área. Ao lançar a magia, escolha um dos efeitos abaixo. Enquanto a magia durar, você pode gastar uma ação padrão para mudar o efeito.Aumentar: no início de seus turnos, cada criatura na área deve fazer um teste de Atletismo. Se passar, fica fatigada. Se falhar, fica  Fatigado e Caído;Inverter: inverte a gravidade da área, fazendo com que criaturas e objetos “caiam” para cima, atingindo o topo (12m) em uma rodada. Se um obstáculo (como um teto) impedir o movimento das criaturas, elas sofrem 1d6 pontos de dano de impacto para cada 1,5m de “queda”. Elas podem então se levantar e caminhar no obstáculo, de cabeça para baixo. Se não houver obstáculo, as criaturas e objetos ficam flutuando no topo da área afetada, sem poder sair do lugar. Criaturas voadoras podem se movimentar normalmente. Alguém adjacente a algo que possa agarrar tem direito a um teste de Reflexos para evitar a “queda”. A criatura deve permanecer presa pela duração da magia; caso contrário “cairá”.Reduzir: criaturas ou objetos livres Médios ou menores flutuam para cima e para baixo conforme sua vontade, com deslocamento de voo 6m. Criaturas na área recebem +20 em testes de Atletismo para escalar e saltar. Uma criatura levitando fica instável, sofrendo –2 em testes de ataque.', '[]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Controlar o Clima', 'Divina', 4, 'Transmutação', 'completa', '2km', '4d12 horas', 'esfera com 2km de raio', '', '', 'Você muda o clima da área onde se encontra, podendo criar qualquer condição climática: chuva, neve, ventos, névoas... Veja o Capítulo 6: O Mestre para os efeitos em jogo do clima.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Círculo da Restauração', 'Divina', 4, 'Evocação', 'padrão', 'curto', '5 rodadas', 'esfera de 3m de raio', '', '', 'Você evoca um círculo de luz que emana uma energia poderosa. Qualquer criatura viva que termine o turno dentro do círculo recupera 3d8+3 PV e 1 PM. Mortos-vivos e criaturas que sofrem dano por luz perdem PV e PM na mesma quantidade. Uma criatura pode recuperar no máximo 5 PM por dia com esta magia.', '[{"cost":"+2 PM","effect":"aumenta a regeneração de PV em 1d8+1.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Cólera de Azgher', 'Divina', 4, 'Evocação', 'padrão', 'médio', 'instantânea', 'esfera com 6m de raio', 'Reflexos Parcial', '', 'Você cria um fulgor dourado e intenso. Criaturas na área ficam cegas por 1d4 rodadas e em chamas, e sofrem 10d6 pontos de dano de fogo (mortos-vivos sofrem 10d8 pontos de dano). Uma criatura que passe no teste de resistência não fica cega nem em chamas e sofre metade do dano.', '[{"cost":"+2 PM","effect":"aumenta o dano em +2d6 (+2d8 contra mortos-vivos).","isTrick":false},{"cost":"+2 PM","effect":"aumenta a área em +6m de raio.","isTrick":false},{"cost":"+5 PM","effect":"a luz purificadora do Deus-Sol dissipa todas as magias de necromancia ativas na área. Requer 5º círculo","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Cúpula de Repulsão', 'Divina', 4, 'Abjuração', 'padrão', 'pessoal', 'sustentada', '', 'Vontade Anula', '', 'Uma cúpula de energia invisível o cerca, impedindo a aproximação de certas criaturas. Escolha um tipo de criatura (animais, espíritos, monstros...) ou uma raça de humanoides (elfos, goblins, minotauros..). Criaturas do grupo escolhido que tentem se aproximar a menos de 3m de você (ou seja, que tentem ficar adjacentes a você) devem fazer um teste de Vontade. Se falharem, não conseguem, gastam a ação e só podem tentar novamente na rodada seguinte. Isso impede ataques corpo a corpo, mas não ataques ou outros efeitos à distância. Se você tentar se aproximar além do limite de 3m, rompe a cúpula e a magia é dissipada.', '[{"cost":"+2 PM","effect":"a cúpula impede criaturas de se aproximarem a menos de 4,5m de você (ou seja, deve haver dois quadrados entre você e as criaturas).","isTrick":false},{"cost":"+5 PM","effect":"além do normal, criaturas afetadas também precisam fazer o teste de resistência se fizerem um ataque ou efeito à distância você. Se falharem, o efeito é desviado pela cúpula. Requer 5º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Desintegrar', 'Arcana', 4, 'Transmutação', 'padrão', 'médio', 'instantânea', '', 'Fortitude parcial', '', 'Você dispara um raio fino e esverdeado que causa 10d12 pontos de dano de essência. Se o alvo passar no teste de resistência, em vez disso sofre 2d12 pontos de dano.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Duplicata Ilusória', 'Arcana', 4, 'Ilusão', 'padrão', 'médio', 'cena', '', '', '', 'Você cria uma cópia ilusória semirreal de... você mesmo! Ela é idêntica em aparência, som e cheiro, mas é intangível. A cada turno, você escolhe se verá e ouvirá através da duplicata ou de seu corpo original. A cópia reproduz todas as suas ações, incluindo fala. Qualquer magia com alcance de toque ou maior que você lançar pode se originar da duplicata, em vez do seu corpo original. As magias afetam outros alvos normalmente, com a única diferença de se originarem da cópia, em vez de você. Se quiser que a duplicata faça algo diferente de você, você deve gastar uma ação de movimento. Qualquer criatura que interagir com a cópia tem direito a um teste de Vontade para perceber que é uma ilusão. As magias que se originam dela, no entanto, são reais. A cópia desaparece se sair do alcance.', '[{"cost":"+3 PM","effect":"cria uma cópia adicional.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Explosão Caleidoscópica', 'Arcana', 4, 'Ilusão', 'padrão', 'curto', 'instantânea', 'esfera com 6m de raio', 'Fortitude parcial', '', 'Esta magia cria uma forte explosão de luzes estroboscópicas e sons cacofônicos que desorientam as criaturas atingidas. O efeito que cada criatura sofre depende do ND dela.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Forma Etérea', 'Arcana', 4, 'Transmutação', 'completa', 'pessoal', 'sustentada', '', '', '', 'Você e todo o equipamento que está com você são transportados para o plano etéreo, que existe paralelamente ao plano material (o mundo físico). Na prática, é como ser transformado em um fantasma (mas você ainda é considerado uma criatura viva). Uma criatura etérea é invisível (pode alterar entre visível e invisível como ação livre), incorpórea e capaz de se mover em qualquer direção, inclusive para cima e para baixo. Ela enxerga o plano material, mas tudo parece cinza e insubstancial, reduzindo o alcance da visão e audição para 18m. Magias de abjuração e essência afetam criaturas etéreas, mas outras magias, não. Da mesma forma, uma criatura etérea não pode atacar nem lançar magias contra criaturas no plano material. Duas criaturas etéreas podem se afetar normalmente. Uma criatura afetada pode se materializar como uma ação de movimento, encerrando a magia. Uma criatura etérea que se materialize em um espaço ocupado é jogada para o espaço não ocupado mais próximo e sofre 1d6 pontos de dano de impacto para cada 1,5m de deslocamento.', '[{"cost":"+5 PM","effect":"muda o alcance para toque e o alvo para até 5 criaturas voluntárias que estejam de mãos dadas. Depois que a magia é lançada, as criaturas podem soltar as mãos. Requer 5º círculo.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Guardião Divino', 'Divina', 4, 'Convocação', 'padrão', 'curto', 'Cena ou até ser descarregado', '', '', '', 'A magia invoca um elemental Pequeno, com a forma de um orbe feito de luz divina. A criatura é incorpórea, imune a dano e ilumina como uma tocha. O elemental tem 100 pontos de luz.Uma vez por rodada, durante o seu turno, o elemental pode se movimentar (deslocamento de voo 18m) e gastar quantos pontos de luz quiser para curar dano ou condições de criaturas em alcance curto, à taxa de 1 PV por 1 ponto de luz ou uma condição por 3 pontos de luz (entre abalado, apavorado, alquebrado, atordoado, cego, confuso, debilitado, enjoado, esmorecido, exausto, fascinado, fatigado, fraco, frustrado, ofuscado, pasmo, sangrando, surdo ou vulnerável). A magia é encerrada quando o elemental fica sem pontos de luz.', '[]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Libertação', 'Universal', 4, 'Abjuração', 'padrão', 'curto', 'cena', '', '', '', 'O alvo fica imune a efeitos de movimento e ignora qualquer efeito que impeça ou restrinja seu deslocamento. Por fim, pode usar habilidades que exigem liberdade de movimentos mesmo se estiver usando armadura ou escudo.', '[{"cost":"+2 PM","effect":"além do normal, o alvo pode caminhar sobre a água ou outros líquidos com seu deslocamento normal. Entretanto, isso não protege contra qualquer efeito que o líquido possa causar (o alvo pode andar sobre lava, mas ainda vai sofrer dano).","isTrick":false},{"cost":"+2 PM","effect":"além do normal, o alvo pode escolher 20 em todos os testes de Atletismo.","isTrick":false},{"cost":"+2 PM","effect":"além do normal, o alvo pode escolher 20 em todos os testes de Acrobacia e pode fazer todas as manobras desta perícia mesmo sem treinamento.","isTrick":false},{"cost":"+5 PM","effect":"muda o alvo para até 5 criaturas.","isTrick":false},{"cost":"+5 PM","effect":"pode dissipar Aprisionamento.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Ligação Sombria', 'Divina', 4, 'Necromancia', 'padrão', 'longo', '1 dia', '', 'Fortitude anula', '', 'Cria uma conexão entre seu corpo e o da criatura alvo, deixando uma marca idêntica na pele de ambos. Enquanto a magia durar, sempre que você sofrer qualquer dano ou condição, o alvo desta magia deve fazer um teste de Fortitude; se falhar, sofre o mesmo dano que você ou adquire a mesma condição. A magia termina se o alvo chegar a 0 pontos de vida.', '[{"cost":"+5 PM","effect":"a magia não termina se o alvo chegar a 0 PV (o que significa que dano causado por essa magia pode matá-lo).","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Manto do Cruzado', 'Divina', 4, 'Evocação', 'padrão', 'pessoal', 'sustentada', '', '', '', 'Você invoca o poder de sua divindade na forma de um manto de energia que reveste seu corpo. Esta magia tem duas versões. Você escolhe qual versão pode lançar quando aprende esta magia. Ela não pode ser mudada.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Marionete', 'Arcana', 4, 'Encantamento', 'padrão', 'médio', 'sustentada', '', 'Fortitude anula', '', 'Esta magia manipula o sistema nervoso do alvo. Ao sofrer a magia, e no início de cada um de seus turnos, a vítima faz um teste de Fortitude. Se passar, a magia é anulada. Se falhar, todas as suas ações físicas naquele turno estarão sob controle do conjurador. A vítima ainda tem consciência de tudo que acontece à sua volta, podendo ver, ouvir e até falar com certo esforço (mas não para lançar magias). Contudo, seu corpo realiza apenas os movimentos que o conjurador deseja. A vítima pode ser manipulada para se movimentar, lutar, usar habilidades de combate... Enfim, qualquer coisa de que seja fisicamente capaz.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Muralha de Ossos', 'Universal', 4, 'Necromancia', 'padrão', 'médio', 'cena', '', '', '', 'Uma parede de ossos se eleva da terra. A parede tem 15m de comprimento, 9m de altura e 1,5m de espessura. Ela pode ter qualquer forma — não precisa ser uma linha reta —, mas sua base precisa estar sempre tocando o solo. Quando a parede surge, criaturas na área ocupada ou adjacentes sofrem 4d8 pontos de dano de corte e precisam fazer um teste de Reflexos para não ficarem presas no emaranhado de ossos. Uma criatura presa dessa maneira fica Agarrado, e pode usar uma ação padrão para fazer um teste de Atletismo (CD da magia) para se soltar. Se passar no teste, sai da muralha para um dos lados adjacentes. Se falhar, sofre 4d8 pontos de dano de corte.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Mão Poderosa de Talude', 'Arcana', 4, 'Convocação', 'padrão', 'médio', 'sustentada', '', '', '', 'Esta magia cria uma mão flutuante de tamanho Grande que sempre se posiciona entre você e um oponente a sua escolha. A mão fornece cobertura leve (+5 na Defesa) contra esse oponente. Nada é capaz de enganar a mão — coisas como escuridão, invisibilidade, metamorfose e disfarces mundanos não a impedem de protegê-lo. A mão tem Defesa 20 e PV e resistências iguais aos seus. Com uma ação de movimento, você pode comandar a mão para que o proteja de outro oponente ou para que realize uma das ações a seguir.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Premonição', 'Divina', 4, 'Adivinhação', 'padrão', 'pessoal', 'cena', '', '', '', 'Vislumbres do futuro permitem que você reavalie suas ações. Uma vez por rodada, você pode rolar novamente um teste recém realizado, mas deve aceitar o resultado da nova rolagem.', '[{"cost":"+3 PM","effect":"muda a execução para reação, o alcance para curto, o alvo para 1 criatura e a duração para instantânea. Esta magia só pode ser usada em uma criatura que tenha acabado de fazer um teste. Obriga a criatura a fazer uma nova rolagem de dados e aceitar o novo resultado, seja ele um sucesso ou falha. Criaturas involuntárias têm direito a um teste de Vontade para negar o efeito.","isTrick":false},{"cost":"+10 PM","effect":"muda a duração para 1 dia.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Raio Polar', 'Arcana', 4, 'Evocação', 'padrão', 'médio', 'instantânea', '', 'Fortitude parcial', '', 'Você dispara um raio azul esbranquiçado de gelo e ar congelante. O alvo sofre 10d8 pontos de dano de frio e fica preso em um bloco de gelo (Paralisado). Se passar no teste de resistência, sofre metade do dano e, em vez de paralisado, fica Lento por uma rodada.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Relâmpago Flamejante de Reynard', 'Arcana', 4, 'Evocação', 'Duas Rodadas', 'médio', 'sustentada', '', 'Reflexos reduz à metade', '', 'Esta é uma magia poderosa, desenvolvida pelo metódico e impassível arquimago Reynard. Você invoca as energias elementais do fogo e do relâmpago, fazendo com que uma de suas mãos fique em chamas e a outra mão eletrificada. Pela duração da magia, você pode gastar uma ação de movimento para disparar uma bola de fogo (10d6 pontos de dano de fogo numa esfera com 6m de raio) ou um relâmpago (10d6 pontos de dano de eletricidade numa linha). Você também pode, como uma ação padrão, usar as duas mãos num ataque de energia mista (20d12 pontos de dano, metade de fogo e metade de eletricidade, numa esfera com 9m de raio). Você precisa estar com as duas mãos livres para invocar o efeito misto e isso consome toda a energia da magia, terminando-a imediatamente. Por se tratar de um ritual complexo, o tempo de execução dessa magia não pode ser reduzido.', '[{"cost":"+2 PM","effect":"aumenta o dano das rajadas em +1d6 e o dano da rajada mista em +2d12.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Sonho', 'Arcana', 4, 'Adivinhação', '10 minutos', 'ilimitado (veja texto)', 'Veja Texto', '', '', '', 'Você entra nos sonhos de uma criatura. Uma vez lá, pode conversar com ela até que ela acorde. Se o alvo não estiver dormindo quando você lançar a magia, você pode permanecer em transe até que ele adormeça. Durante o transe, você fica Indefeso e sem consciência dos arredores. Você pode sair do transe quando quiser, mas a magia termina.', '[{"cost":"+2 PM","effect":"transforma o sonho do alvo em um pesadelo. A vítima deve fazer um teste de Vontade. Se falhar, não recupera PV ou PM pela noite, sofre 1d10 pontos de dano de trevas e acorda fatigada. A vítima recebe bônus ou penalidades em seu teste de resistência, dependendo do conhecimento que você tiver dela. Use os mesmos modificadores da magia Vidência.","isTrick":false},{"cost":"+1 PM","effect":"aumenta o número de alvos em +1. Todos os alvos compartilham um mesmo sonho (ou pesadelo) entre si e com você.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Talho Invisível de Edauros', 'Arcana', 4, 'Evocação', 'padrão', 'pessoal', 'instantânea', 'cone de 9m', 'Fortitude parcial', '', 'Esta magia cruel foi desenvolvida pelo mago de combate Edauros, quando ainda era um bípede. Você faz um gesto rápido e dispara uma lâmina de ar em alta velocidade. Criaturas na área sofrem 10d8 pontos de dano de corte e ficam sangrando. Alvos que passem no teste de resistência sofrem metade do dano e não ficam sangrando.', '[{"cost":"+2 PM","effect":"aumenta o dano em +2d8.","isTrick":false},{"cost":"+2 PM","effect":"muda o alvo para você, a duração para sustentada e o efeito para uma vez por rodada, como uma ação de movimento, você pode disparar uma lâmina de ar contra um alvo em alcance médio, causando 6d8 pontos de dano de corte (Fortitude reduz à metade).","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Terremoto', 'Divina', 4, 'Evocação', 'padrão', 'longo', '1 rodada', 'esfera com 30m de raio', 'veja texto', '', 'Esta magia cria um tremor de terra que rasga o solo. O terremoto dura uma rodada, durante a qual criaturas sobre o solo ficam atordoadas. Barreiras físicas não interrompem a área de Terremoto.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Transformação em Dragão', 'Arcana', 4, 'Transmutação', 'completa', 'pessoal', 'sustentada', '', '', '', 'Esta magia invoca o poder de um dragão, causando mutações no conjurador que o tornam semelhante a uma criatura dracônica. Você recebe +2 em Força, Constituição, Inteligência e Carisma (esse aumento não oferece PV, PM ou perícias adicionais), +5 na Defesa e redução 30 contra o elemento do sopro do dragão cujo componente material você usou. Uma vez por rodada, você pode gastar uma ação padrão para exalar um sopro que causa 8d6+8 pontos de dano do elemento correspondente em um cone de 9m (Reflexos reduz à metade). 
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Viagem Planar', 'Universal', 4, 'Convocação', 'completa', 'toque', 'instantânea', '', '', '', 'Você viaja instantaneamente para outro plano da Criação. Lá, você chega de 10 a 1.000km do destino pretendido (role 1d100 e multiplique por 10km).Componente material: um bastão de metal precioso em forma de forquilha (no valor de T$ 1.000). O tipo de metal determina para qual plano de existência você será enviado. Os metais que levam a dimensões específicas podem ser difíceis de encontrar, de acordo com o mestre.', '[{"cost":"+2 PM","effect":"muda o alvo para até cinco criaturas voluntárias que você esteja tocando.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Visão da Verdade', 'Universal', 4, 'Adivinhação', 'movimento', 'pessoal', 'cena', '', '', '', 'Você enxerga a forma real das coisas. Você pode ver através de camuflagem e escuridão (normais e mágicas), assim como efeitos de ilusão e transmutação (enxergando a verdade como formas translúcidas ou sobrepostas).', '[{"cost":"+1 PM","effect":"muda o alcance para toque e o alvo para 1 criatura.","isTrick":false},{"cost":"+1 PM","effect":"além do normal, o alvo fica com sentidos apurados; ele recebe +10 em todos os testes de Percepção.","isTrick":false},{"cost":"+2 PM","effect":"além do normal, o alvo escuta falsidades; ele recebe +10 em todos os testes de Intuição.","isTrick":false},{"cost":"+4 PM","effect":"além do normal, o alvo enxerga através de paredes e barreiras com 30cm de espessura ou menos (as paredes e barreiras parecem translúcidas).","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Alterar Destino', 'Arcana', 5, 'Abjuração', 'reação', 'pessoal', 'instantânea', '', '', '', 'Sua mente visualiza todas as possibilidades de um evento, permitindo a você escolher o melhor curso de ação. Você pode rolar novamente um teste de resistência com um bônus de +10 ou um inimigo deve rolar novamente um ataque contra você com uma penalidade de –10', '[]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Aprisionamento', 'Arcana', 5, 'Abjuração', 'completa', 'curto', 'permanente', '', 'Vontade anula', '', 'Você cria uma prisão mágica para aprisionar uma criatura. Se falhar no testede resistência, o alvo sofre o efeito da magia; se passar, fica imune a esta magia por uma semana. Enquanto estiver aprisionada, a criatura não precisa respirar e alimentar-se, e não envelhece. Magias de adivinhação não conseguem localizar ou perceber o alvo. Ao lançar a magia, você escolhe uma das seguintes formas de prisão. O componente material varia, mas todos custam T$ 1.000.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Aura Divina', 'Divina', 5, 'Abjuração', 'padrão', 'pessoal', 'cena', 'esfera com 9m de raio', 'Vontade parcial', '', 'Você se torna um conduíte da energia de sua divindade, emanando uma aura brilhante. Você e aliados devotos da mesma divindade ficam imunes a encantamento e recebem +10 na Defesa e em testes de resistência. Aliados não devotos da mesma divindade recebem+5 na Defesa e em testes de resistência.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Barragem elemental de Vectorius', 'Arcana', 5, 'Evocação', 'padrão', 'longo', 'instantânea', '', 'Reflexos parcial', '', 'Criada pelo arquimago Vectorius, esta magia produz quatro esferas, de ácido, eletricidade, fogo e frio, que voam até um ponto a sua escolha. Quando atingem o ponto escolhido, explodem causando 6d6 pontos de dano de seu respectivo tipo numa área com 12m de raio. Um teste de Reflexos reduz o dano à metade. Você pode mirar cada esfera em uma criatura ou ponto dife- rente. Uma criatura ao alcance da explosão de mais de uma esfera deve fazer um teste de resistência para cada uma. Além disso, as esferas causam os seguintes efeitos em criaturas que falharem em seus testes de resistência::
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Buraco Negro', 'Universal', 5, 'Abjuração', 'completa', 'longo', '3 rodadas', '', 'Fortitude parcial', '', 'Esta magia cria um vácuo capaz de sugar tudo nas proximidades. Escolha um espaço desocupado para o buraco negro. No início de cada um de seus três turnos seguintes, todas as criaturas a até alcance longo do buraco negro, incluindo você, devem fazer um teste de Fortitude. Em caso de falha, ficam caídas e são puxadas 30m na direção do buraco. Objetos soltos também são puxados. Criaturas podem gastar uma ação de movimento para se segurar em algum objeto fixo, recebendo +2 em seus testes de resistência.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Chuva de Meteoros', 'Arcana', 5, 'Convocação', 'completa', 'longo', 'instantânea', 'quadrado com 18m de lado', 'Reflexos parcial', '', 'Meteoros caem dos céus, devastando a área afetada. Criaturas na área sofrem 15d6 pontos de dano de impacto, 15d6 pontos de dano de fogo e ficam Caído e presas sob os escombros (Agarrado).
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Controlar o Tempo', 'Arcana', 5, 'Transmutação', 'padrão', 'veja texto', 'veja texto', '', '', '', 'Aquele que controla o tempo controla o mundo. Escolha um dos efeitos a seguir.Congelar o tempo: você gera uma bolha do seu tamanho na qual o tempo passa mais lentamente. Para outras criaturas, a bolha surge e desaparece instantaneamente, mas, para você, ela dura 3 rodadas (o que fornece 2 turnos extras após o atual), durante as quais você pode agir e não é afetado por efeitos contínuos (como chamas). Porém, durante essas 3 rodadas, você e quaisquer efeitos que você gerar não podem sair da área que você ocupava quando lançou esta magia. Efeitos de área com duração maior que a da bolha voltam a agir normalmente quando ela termina. Você não pode congelar o tempo nem preparar ações enquanto está sob esse efeito.Saltar no tempo: você e até 5 criaturas voluntárias são transportadas de 1 a 24 horas para o futuro, desaparecendo com um brilho. Vocês ressurgem no mesmo lugar, com a mesma velocidade e orientação; do seu ponto de vista, nenhum tempo se passou. Se um objeto sólido agora ocupa o espaço de uma criatura, ela ressurge na área vazia mais próxima.Voltar no tempo: você revive os últimos segundos. Todas as ações da rodada anterior são desfeitas (incluindo perda de PV e PM — exceto os gastos nesta magia). Tudo retorna à posição em que estava no início do seu turno na última rodada e você é o único que sabe o que acontecerá. Outros personagens devem repetir as mesmas ações — exceto se você fizer algo a respeito (como avisar seus aliados sobre o que vai acontecer). Você só pode reviver uma mesma rodada uma vez.', '[]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Deflagração de Mana', 'Arcana', 5, 'Evocação', 'completa', 'pessoal', 'instantânea', 'esfera de 15m de raio', 'Fortitude parcial', '', 'Após concentrar seu mana, você emana energia, como uma estrela em plena terra. Todas as criaturas na área sofrem 150 pontos de dano de essência e todos os itens mágicos (exceto artefatos) tornam-se mundanos. Você não é afetado pela magia. Alvos que passem no teste de Fortitude sofrem metade do dano e seus itens mágicos voltam a funcionar após um dia.', '[{"cost":"+1 PM","effect":"aumenta o dano em 10.","isTrick":false},{"cost":"+5 PM","effect":"afeta apenas criaturas a sua escolha.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Desejo', 'Arcana', 5, 'Transmutação', 'completa', 'veja texto', 'veja texto', '', 'veja texto', '', 'Esta é a mais poderosa das magias arcanas, permitindo alterar a realidade a seu bel-prazer. Você pode:
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Engenho de Mana', 'Divina', 5, 'Abjuração', 'padrão', 'médio', 'sustentada', '', '', '', 'Você cria um disco de energia que lembra uma roda de engenho e flutua no ponto em que foi conjurado. O disco é imune a dano, não pode ser movido e faz uma contramágica automática contra qualquer magia lançada em alcance médio dele (exceto as suas), usando seu teste de Misticismo. Caso vença o teste, o engenho não só anula a magia como absorve os PM usados para lançá-la, acumulando PM temporários. No seu turno, se estiver ao alcance do disco, você pode gastar PM nele para lançar magias.', '[{"cost":"+1 PM","effect":"em vez de flutuar no ponto em que foi conjurado, o disco flutua atrás de você, mantendo-se sempre adjacente.","isTrick":false},{"cost":"+4 PM","effect":"muda a duração para 1 dia.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Fúria do Panteão', 'Divina', 5, 'Evocação', 'completa', 'longo', 'sustentada', 'cubo de 90m', 'veja texto', '', 'Você cria uma nuvem de tempestade violenta. Os ventos tornam ataques à distância impossíveis e fazem a área contar como condição terrível para lançar magia. Além disso, inimigos na área têm a visibilidade reduzida (como a magia Névoa). Uma vez por turno, você pode gastar uma ação de movimento para gerar um dos efeitos a seguir.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Intervenção Divina', 'Divina', 5, 'Convocação', 'completa', 'veja texto', '', '', 'veja texto', '', 'Você pede a sua divindade para interceder diretamente. Você pode:
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Invulnerabilidade', 'Universal', 5, 'Abjuração', 'padrão', 'pessoal', 'cena', '', '', '', 'Esta magia cria uma barreira mágica impenetrável que protege você contra efeitos nocivos mentais ou físicos, a sua escolha.Proteção mental: você fica imune às condições abalado, alquebrado, apavorado, atordoado, confuso, esmorecido, fascinado, frustrado e pasmo, além de efeitos de encantamento e ilusão.Proteção física: você fica imune às condições atordoado, cego, debilitado, enjoado, envenenado, exausto, fatigado, fraco, lento, ofuscado e paralisado, além de acertos críticos, ataques furtivos e doenças.', '[{"cost":"+5 PM","effect":"muda o alcance para curto e o alvo para 1 criatura.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Katana Celestial', 'Divina', 5, 'Evocação', 'padrão', 'pessoal', 'instantânea', 'linha de 60m ou duas linhas de 30m', 'Reflexos parcial', '', 'Um golpe vindo dos céus risca o campo de batalha. Se escolher duas linhas, cada uma deve seguir em uma direção diferente, criando um corte em “V”. Criaturas na área sofrem 12d8 pontos de dano de luz (ou 12d12, se forem mortos-vivos) e ficam cegas e surdas até o fim da cena (Reflexos reduz à metade e evita as condições).', '[{"cost":"+3 PM","effect":"aumenta o dano em +2d8 (ou +2d12 contra mortos-vivos).","isTrick":false},{"cost":"+6 PM","effect":"muda a área para uma linha de 120m ou quatro linhas de 30m em direções opostas, formando um  “X”.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Legião', 'Arcana', 5, 'Encantamento', 'padrão', 'médio', 'sustentada', '', 'Vontade parcial', '', 'Você domina a mente dos alvos. Os alvos obedecem cegamente a seus comandos, exceto ordens claramente suicidas. Um alvo tem direito a um teste no final de cada um de seus turnos para se livrar do efeito. Alvos que passarem no teste ficam Abalado por 1 rodada enquanto recuperam a consciência.', '[{"cost":"+1 PM","effect":"aumenta o número de alvos em +1.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Lágrimas de Wynna', 'Divina', 5, 'Abjuração', 'padrão', 'curto', 'instantânea', '', 'Vontade parcial', '', 'Se falhar no teste de resistência, o alvo perde a habilidade de lançar magias arcanas até o fim da cena. Se passar, perde a habilidade por uma rodada.', '[{"cost":"+2 PM","effect":"muda a área para esfera de 6m de raio e o alvo para criaturas escolhidas.","isTrick":false},{"cost":"+5 PM","effect":"muda a execução para 1 dia e adiciona custo adicional (sacrifício de 1 PM). O alvo da magia precisa ser mantido em alcance curto do conjurador durante toda a execução. Ao término, faz um teste de Vontade. Se falhar, perde a habilidade de lançar magias arcanas permanentemente. Se passar, resiste, mas ainda pode ser alvo da magia no dia seguinte. Nenhum poder mortal é capaz de reverter essa perda. Os clérigos da deusa da Magia dizem que a deusa chora cada vez que este ritual é realizado.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Mata-Dragão', 'Arcana', 5, 'Evocação', '2 Rodadas', 'pessoal', 'instantânea', 'cone de 30m', 'Reflexos reduz à metade', '', 'Esta é uma das mais poderosas magias de destruição existentes. Após entoar longos cânticos, o conjurador dispara uma carga de energia que varre uma enorme área à sua frente, causando 20d12 pontos de dano de essência em todas as criaturas, construções e objetos livres atingidos.  Sempre que rola um resultado 12 em um dado de dano, a magia causa +1d12 pontos de dano. Apesar de seu poder destrutivo, esta magia é lenta, tornando seu uso difícil em combate.', '[{"cost":"+1 PM","effect":"aumenta o dano em 1d12.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Palavra Primordial', 'Universal', 5, 'Encantamento', 'padrão', 'curto', 'instantânea ou veja texto', '', 'Vontade parcial', '', 'Você pronuncia uma palavra do idioma primordial da Criação, que causa um dos efeitos abaixo, a sua escolha.Atordoar: a criatura fica atordoada por 1d4+1 rodadas (apenas uma vez por cena). Se passar no teste de resistência, ou se já foi atordoada por esta magia, fica desprevenida por 1d4 rodadas.Cegar: a criatura fica Cego. Se passar no teste de resistência, fica Sangrando.', '[]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Possessão', 'Arcana', 5, 'Encantamento', 'padrão', 'longo', '1 dia', '', 'Vontade anual', '', 'Você projeta sua consciência no corpo do alvo. Enquanto possuir uma criatura, você assume o controle total do corpo dela. O seu próprio corpo fica inconsciente e a consciência do alvo fica inerte. Em termos de jogo, você continua usando a sua ficha, mas com os atributos físicos e deslocamento da criatura. Se o alvo passar no teste de resistência, sabe que você tentou possuí-lo e fica imune a esta magia por um dia. Caso o corpo da criatura morra enquanto você a possui, a criatura morre e você deve fazer um teste de Vontade contra a CD da sua própria magia. Se passar, sua consciência retorna para o seu corpo (contanto que esteja dentro do alcance). Do contrário, você também morre. Retornar para o seu corpo voluntariamente é uma ação livre.', '[{"cost":"+5 PM","effect":"você ganha acesso às habilidades de raça e classe da criatura.","isTrick":false},{"cost":"+5 PM","effect":"enquanto a magia durar e você estiver dentro do alcance do seu corpo original, pode “saltar” de uma criatura possuída para outra. O novo alvo tem direito a um teste de Vontade. Se falhar, você assume o controle do corpo dele e o alvo anterior recobra a consciência.","isTrick":false},{"cost":"+5 PM","effect":"muda a duração para permanente, mas destrói seu corpo original no processo. Uma criatura possuída pode fazer um teste de Vontade no começo do dia para retomar seu corpo. Se passar, recobra a consciência (e a sua própria consciência fica inerte). O teste se repete no início de cada dia. Se o corpo de uma criatura possuída morrer e houver outra criatura em alcance curto, você pode tentar possuí-la como uma reação. Enquanto houver novos corpos para possuir, você é imortal!","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Projetar Consciência', 'Divina', 5, 'Adivinhação', 'padrão', 'ilimitado (veja texto)', 'sustentada', '', '', '', 'Esta magia faz com que sua consciência deixe seu corpo e se transporte instantaneamente para um local ou para perto de uma criatura alvo. Se escolher um local, ele precisa ser conhecido por você. Se escolher uma criatura, você transporta sua consciência até onde a criatura estiver, contanto que estejam no mesmo plano.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Reanimação Impura', 'Divina', 5, 'Necromancia', 'completa', 'toque', 'cena', '', '', '', 'Você reanima uma criatura morta recentemente (dentro da mesma cena), trazendo sua alma de volta ao corpo de forma forçada. O tipo da criatura muda para morto-vivo, mas ela retém suas memórias e habilidades de quando estava viva, podendo inclusive lançar magias. A criatura pode pensar e falar livremente, mas obedece cegamente a seus comandos. Quando a cena termina, a criatura volta a ficar morta, mas muitos clérigos malignos usam meios para guardar e preservar o corpo de criaturas poderosas para serem reanimadas dessa forma quando necessário. Se for destruída, a criatura não pode ser reanimada novamente com esta magia.', '[]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Roubar a Alma', 'Divina', 5, 'Necromancia', 'padrão', 'curto', 'permanente', '', 'Vontade parcial', '', 'Você rouba a alma da vítima, armazenando-a em um objeto. Se o alvo passar no teste de resistência, sente o impacto de sua alma ser puxada para fora do corpo e fica Abaladopor 1 rodada. Se falhar, seu corpo fica caído, Inconscientee inerte, enquanto sua alma é transportada para dentro do objeto. O corpo não envelhece nem se decompõe, permanecendo em estase. Ele pode ser atacado e destruído normalmente. O objeto escolhido deve custar T$ 1.000 por nível ou ND da criatura e não possuir uma alma presa ou se quebrará quando a magia for lançada (embora personagens não conheçam o conceito de “nível” dentro do mundo de jogo, podem ter noção do poder geral de uma criatura, estimando assim o valor do objeto). Se o objeto for destruído, a magia se esvai. Se o corpo ainda estiver disponível, a alma retorna para ele. Caso contrário, escapa para os Mundos dos Deuses.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Réquiem', 'Arcana', 5, 'Ilusão', 'completa', 'curto', 'sustentada', '', 'Vontade anula', '', 'Esta magia cria uma ilusão particular para cada uma das criaturas que atingir. Enquanto a magia durar, no início de cada um de seus turnos, cada criatura afetada deve fazer um teste de Vontade; se falhar, acha que não tomou as ações que realmente fez no turno anterior e é obrigada a repetir as mesmas ações neste turno, com uma penalidade cumulativa de –5 em todos os testes para cada vez que se repetir (a penalidade não se aplica ao teste de Vontade contra esta magia). Por exemplo, se a criatura se aproximou de um alvo e o atacou, precisa se aproximar desse mesmo alvo e atacar novamente. A ação repetida consome PM e recursos normalmente e, caso exija um teste de resistência, qualquer alvo faz esse teste com um bônus igual ao da penalidade desta magia.', '[]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Segunda Chance', 'Divina', 5, 'Evocação', 'padrão', 'toque', 'instantânea', '', '', '', 'Um brilho alaranjado, na forma de asas de fênix, emana do alvo. Ele recupera 200 pontos de vida e se cura de qualquer das seguintes condições: abalado, apavorado, alquebrado, atordoado, cego, confuso, debilitado, enjoado, envenenado, esmorecido, exausto, fascinado, fatigado, fraco, frustrado, lento, ofuscado, paralisado, pasmo ou surdo.', '[{"cost":"+1 PM","effect":"aumenta a cura em +20 PV.","isTrick":false},{"cost":"+2 PM","effect":"muda o alcance para curto e o alvo para até 5 criaturas.","isTrick":false},{"cost":"+5 PM","effect":"muda o alvo para uma criatura que tenha morrido há até uma rodada. Esta magia pode curá-la.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Semiplano', 'Arcana', 5, 'Convocação', 'completa', 'curto', '1 dia', '', '', '', 'Você cria uma dimensão particular. Você pode entrar no semiplano gastando uma ação padrão e 10 PM, desaparecendo do plano material como se tivesse se teletransportado. Você pode levar criaturas voluntárias que esteja tocando, ao custo de 1 PM por criatura extra. Você também pode levar objetos que esteja tocando, ao custo de 1 PM por objeto Médio ou menor, 2 PM por objeto Grande, 5 PM por Enorme e 10 PM por Colossal. Uma vez no semiplano, pode gastar uma ação completa para voltar ao plano material, no mesmo local onde estava. Caso conheça a magia Viagem Planar, pode lançá-la para voltar ao plano material em outro local.
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Sombra Assassina', 'Arcana', 5, 'Ilusão', 'padrão', 'curto', 'cena', '', 'Vontade parcial', '', 'Esta magia cria uma duplicata ilusória do alvo na forma de uma silhueta, ligada a ele como se fosse uma manifestação sólida de sua própria sombra. A duplicata de sombras segue automaticamente o alvo. Sempre que o alvo faz uma ação hostil — fazer um ataque, usar uma habilidade, lançar uma magia — a sombra imediatamente realiza a mesma ação contra o alvo, usando as mesmas estatísticas e rolagens. A sombra pode ser atacada, tem as mesmas estatísticas do alvo e é destruída quando chega a 0 PV. Se o alvo passar no teste de resistência, a sombra desaparece no final do turno do alvo, depois de copiar sua ação dessa rodada.', '[{"cost":"+10 PM","effect":"muda o alvo para criaturas escolhidas na área.","isTrick":false}]'::jsonb, true);
INSERT INTO spells (name, type, circle, school, execution, range, duration, target, resistance, publication, effect, amplifiers, is_public) VALUES ('Toque da Morte', 'Universal', 5, 'Necromancia', 'padrão', 'toque', 'instantânea', '', 'Veja texto', '', 'Sua mão exala energias letais. A criatura sofre 10d8+10 pontos de dano de trevas. Se estiver com menos da metade de seus PV, em vez disso deve fazer um teste de Fortitude. Se passar, sofre o dano normal. Se falhar, seus PV são reduzidos a –10.', '[{"cost":"+2 PM","effect":"muda o alcance para curto. Em vez de tocar no alvo, você dispara um raio púrpura da ponta de seu dedo indicador.","isTrick":false},{"cost":"+10 PM","effect":"muda o alcance para curto e o alvo para inimigos no alcance. Em vez de tocar no alvo, você dispara raios púrpuras da ponta de seus dedos.","isTrick":false}]'::jsonb, true);
